async function xmppOmemoEncryptMessageForPeers(peers, plaintext, ownBare) {
  if (!xmppOmemoRuntimeAvailable()) return null;
  const store = await xmppOmemoEnsureLocalIdentity(ownBare);
  if (!store) return null;
  const senderDeviceId = await store.getLocalRegistrationId();
  if (!senderDeviceId) return null;
  let targets = [];
  try {
    targets = await xmppOmemoGatherDeviceTargets([...peers, ownBare], ownBare);
  } catch (error) {
    addXmppDebugEvent("error", "OMEMO device collision", { error: String(error?.message || error) });
    return null;
  }
  if (targets.length === 0) return null;
  const contentPayload = await xmppOmemoEncryptPlaintextContentCore(plaintext, {
    arrayBufferToBase64,
    concatArrayBuffers
  });
  if (!contentPayload) return null;
  const messageKeys = {};
  let successCount = 0;
  for (const target of targets) {
    const address = new globalThis.libsignal.SignalProtocolAddress(target.jid, Number(target.deviceId));
    await xmppOmemoEnsureSession(target.jid, target.deviceId, ownBare);
    const sessionCipher = new globalThis.libsignal.SessionCipher(store, address);
    try {
      // eslint-disable-next-line no-await-in-loop
      const payload = await sessionCipher.encrypt(contentPayload.keyAndTag);
      messageKeys[target.deviceId] = {
        payload: btoa(payload.body || ""),
        prekey: Number(payload.type) === 3
      };
      successCount += 1;
    } catch (error) {
      addXmppDebugEvent("error", "OMEMO encryption failed for device", {
        peer: target.jid,
        device: target.deviceId,
        error: String(error?.message || error)
      });
    }
  }
  if (successCount === 0) return null;
  return {
    sid: String(senderDeviceId),
    keys: messageKeys,
    iv: contentPayload.ivBase64,
    payload: contentPayload.payloadBase64
  };
}

async function xmppOmemoDecryptPayload(peerBare, payload, ownBare) {
  if (!xmppOmemoRuntimeAvailable()) return null;
  if (!payload || !payload.keys) return null;
  const store = await xmppOmemoEnsureLocalIdentity(ownBare);
  if (!store) return null;
  const deviceId = await store.getLocalRegistrationId();
  if (!deviceId) return null;
  const keyEntry = payload.keys[String(deviceId)];
  if (!keyEntry || !keyEntry.payload) return null;
  const senderDevice = payload.sid;
  if (!senderDevice) return null;
  if (!keyEntry.prekey) {
    await xmppOmemoEnsureSession(peerBare, senderDevice, ownBare);
  }
  const address = new globalThis.libsignal.SignalProtocolAddress(peerBare, Number(senderDevice || 0));
  const sessionCipher = new globalThis.libsignal.SessionCipher(store, address);
  const cipherBytes = base64ToArrayBuffer(keyEntry.payload);
  const keyAndTag = keyEntry.prekey
    ? await sessionCipher.decryptPreKeyWhisperMessage(cipherBytes, "binary")
    : await sessionCipher.decryptWhisperMessage(cipherBytes, "binary");
  return xmppOmemoDecryptContentFromKeyAndPayloadCore(keyAndTag, payload, {
    base64ToArrayBuffer,
    concatArrayBuffers
  });
}

function xmppOmemoTryDecryptIntoMessage({
  stanza,
  message,
  peerBare,
  ownBare,
  onUpdated
}) {
  xmppOmemoTryDecryptIntoMessageCore({
    stanza,
    message,
    peerBare,
    ownBare,
    onUpdated,
    runtimeAvailableFn: xmppOmemoRuntimeAvailable,
    parseEncryptedPayloadFn: xmppOmemoParseEncryptedPayload,
    decryptPayloadFn: xmppOmemoDecryptPayload,
    extractAesgcmUrlsFn: extractAesgcmUrls,
    stripAesgcmUrlsFn: stripAesgcmUrls,
    normalizeAttachmentsFn: normalizeAttachments,
    saveStateFn: saveState,
    debugEventFn: addXmppDebugEvent,
    inFlightByMessageId: xmppOmemoDecryptInFlightByMessageId,
    resolveMessageIdFn: ({ stanza: inputStanza, message: inputMessage, peerBare: inputPeer }) => {
      return `${inputPeer}|${inputMessage.id || xmppStanzaStableId(inputStanza) || createId().slice(0, 8)}`;
    }
  });
}

function resolveOmemoHeaderState(conversation, account = getCurrentAccount()) {
  if (!conversation || conversation.type !== "dm" || !account) return { visible: false };
  const peerJid = xmppPeerJidForDmThread(conversation.thread, account);
  const peerBare = xmppBareJid(peerJid || "");
  if (!peerBare) return { visible: false };
  const prefs = getPreferences();
  const enabled = xmppOmemoEnabledForPeer(peerBare, prefs);
  const runtimeReady = xmppOmemoRuntimeAvailable();
  const connected = prefs.relayMode === "xmpp" && relayStatus === "connected";
  return {
    visible: true,
    peerBare,
    enabled,
    runtimeReady,
    connected
  };
}

function updateOmemoHeaderControl(conversation = getActiveConversation(), account = getCurrentAccount()) {
  if (!ui.omemoHeaderBtn) return;
  const state = resolveOmemoHeaderState(conversation, account);
  if (!state.visible) {
    ui.omemoHeaderBtn.hidden = true;
    ui.omemoHeaderBtn.setAttribute("aria-hidden", "true");
    return;
  }
  ui.omemoHeaderBtn.hidden = false;
  ui.omemoHeaderBtn.setAttribute("aria-hidden", "false");
  ui.omemoHeaderBtn.textContent = state.enabled ? "🔒" : "🔓";
  ui.omemoHeaderBtn.setAttribute("aria-pressed", state.enabled ? "true" : "false");
  const detail = !state.runtimeReady
    ? "OMEMO runtime unavailable"
    : (!state.connected ? "XMPP offline" : "XMPP connected");
  ui.omemoHeaderBtn.title = `OMEMO ${state.enabled ? "on" : "off"} · ${detail}`;
}

function ensureXmppMamState(roomJid) {
  const bareRoom = xmppBareJid(roomJid);
  if (!bareRoom) return null;
  if (!xmppMamStateByRoomJid.has(bareRoom)) {
    xmppMamStateByRoomJid.set(bareRoom, {
      before: "",
      complete: false,
      loading: false,
      loadingSince: 0,
      pagesLoaded: 0,
      lastQueryId: ""
    });
  }
  return xmppMamStateByRoomJid.get(bareRoom) || null;
}

function ensureXmppDmMamState(peerJid) {
  const barePeer = xmppBareJid(peerJid);
  if (!barePeer) return null;
  if (!xmppMamStateByPeerJid.has(barePeer)) {
    xmppMamStateByPeerJid.set(barePeer, {
      before: "",
      complete: false,
      loading: false,
      loadingSince: 0,
      pagesLoaded: 0,
      lastQueryId: "",
      targetIndex: 0
    });
  }
  return xmppMamStateByPeerJid.get(barePeer) || null;
}

function beginXmppMamLoading(mamState, queryId = "") {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.beginXmppMamLoading !== "function") return;
  XEP_0313_MAM_LOADING_GLOBAL.beginXmppMamLoading(mamState, queryId);
}

function endXmppMamLoading(mamState) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.endXmppMamLoading !== "function") return;
  XEP_0313_MAM_LOADING_GLOBAL.endXmppMamLoading(mamState);
}

function recoverStaleXmppMamLoading(mamState, details = {}) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.recoverStaleXmppMamLoading !== "function") return false;
  return XEP_0313_MAM_LOADING_GLOBAL.recoverStaleXmppMamLoading(mamState, details, {
    staleMs: XMPP_MAM_LOADING_STALE_MS,
    endXmppMamLoadingFn: endXmppMamLoading,
    addXmppDebugEventFn: addXmppDebugEvent
  });
}

function xmppMamArchiveTargetJid(prefs = getPreferences()) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.xmppMamArchiveTargetJid !== "function") return "";
  return XEP_0313_MAM_LOADING_GLOBAL.xmppMamArchiveTargetJid(prefs, {
    xmppDomainFromJidFn: xmppDomainFromJid
  });
}

function buildXmppMamQueryIq({
  to = "",
  queryId = "",
  withJid = "",
  maxRows = XMPP_MAM_PAGE_SIZE,
  beforeToken = ""
} = {}) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.buildXmppMamQueryIq !== "function") return null;
  return XEP_0313_MAM_LOADING_GLOBAL.buildXmppMamQueryIq({
    to,
    queryId,
    withJid,
    maxRows,
    beforeToken,
    mamNamespace: XMPP_MAM_NAMESPACE
  }, {
    $iq: globalThis.$iq
  });
}

function parseXmppMamFinPage(stanza) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.parseXmppMamFinPage !== "function") {
    return { complete: false, firstId: "" };
  }
  return XEP_0313_MAM_LOADING_GLOBAL.parseXmppMamFinPage(stanza, {
    mamNamespace: XMPP_MAM_NAMESPACE
  }, {
    xmppNodeHasXmlnsFn: xmppNodeHasXmlns,
    xmppNodeTextFn: xmppNodeText
  });
}

function xmppMamErrorIsPermanent(stanza) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.xmppMamErrorIsPermanent === "function") {
    return XEP_0313_MAM_LOADING_GLOBAL.xmppMamErrorIsPermanent(stanza);
  }
  const errorNode = stanza?.getElementsByTagName?.("error")?.[0] || null;
  return Boolean(
    errorNode?.getElementsByTagName?.("feature-not-implemented")?.length
    || errorNode?.getElementsByTagName?.("service-unavailable")?.length
    || errorNode?.getElementsByTagName?.("item-not-found")?.length
  );
}

function xmppMamUpdateStateFromFinPage(mamState, page) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.xmppMamUpdateStateFromFinPage !== "function") {
    if (!mamState) return mamState;
    const firstId = (page?.firstId || "").toString().trim();
    mamState.pagesLoaded = (Number(mamState.pagesLoaded) || 0) + 1;
    if (firstId) mamState.before = firstId;
    if (page?.complete || !firstId) mamState.complete = true;
    return mamState;
  }
  return XEP_0313_MAM_LOADING_GLOBAL.xmppMamUpdateStateFromFinPage(mamState, page);
}

function xmppMamResetStateForForceReload(mamState, { includeTargetIndex = false } = {}) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.xmppMamResetStateForForceReload !== "function") {
    if (!mamState) return mamState;
    mamState.before = "";
    mamState.complete = false;
    mamState.pagesLoaded = 0;
    if (includeTargetIndex) mamState.targetIndex = 0;
    return mamState;
  }
  return XEP_0313_MAM_LOADING_GLOBAL.xmppMamResetStateForForceReload(mamState, { includeTargetIndex });
}

function xmppMamPrepareFallbackTargetState(mamState, nextTargetIndex = 0) {
  if (typeof XEP_0313_MAM_LOADING_GLOBAL.xmppMamPrepareFallbackTargetState !== "function") {
    if (!mamState) return mamState;
    mamState.targetIndex = Math.max(0, Number(nextTargetIndex) || 0);
    mamState.before = "";
    mamState.pagesLoaded = 0;
    mamState.complete = false;
    return mamState;
  }
  return XEP_0313_MAM_LOADING_GLOBAL.xmppMamPrepareFallbackTargetState(mamState, nextTargetIndex);
}

function requestXmppRoomHistory(roomJid, {
  limit = XMPP_MAM_PAGE_SIZE,
  force = false,
  reason = "manual",
  prefetchPages = 1
} = {}) {
  const bareRoom = xmppBareJid(roomJid);
  if (!bareRoom || !xmppConnection || !globalThis.$iq) return false;
  const mamState = ensureXmppMamState(bareRoom);
  if (!mamState) return false;
  recoverStaleXmppMamLoading(mamState, { scope: "muc", roomJid: bareRoom, reason: `${reason}-precheck` });
  if (mamState.loading) return false;
  if (!force && mamState.complete) return false;
  if (force) {
    xmppMamResetStateForForceReload(mamState);
  }
  const maxRows = Math.max(10, Math.min(200, Number(limit) || XMPP_MAM_PAGE_SIZE));
  const beforeToken = mamState.before || "";
  const queryId = `mam-${createId().slice(0, 8)}-${mamState.pagesLoaded + 1}`;
  beginXmppMamLoading(mamState, queryId);
  const iqBuilder = buildXmppMamQueryIq({
    to: bareRoom,
    queryId,
    withJid: "",
    maxRows,
    beforeToken
  });
  if (!iqBuilder) return false;
  addXmppDebugEvent("iq", "Requesting MUC history", {
    roomJid: bareRoom,
    max: maxRows,
    before: beforeToken || "(latest)",
    page: mamState.pagesLoaded + 1,
    reason
  });
  try {
    xmppConnection.sendIQ(
      iqBuilder,
      (stanza) => {
        endXmppMamLoading(mamState);
        const { complete, firstId } = parseXmppMamFinPage(stanza);
        xmppMamUpdateStateFromFinPage(mamState, { complete, firstId });
        const nextPrefetchPages = Math.max(1, Number(prefetchPages) || 1);
        if (nextPrefetchPages > 1 && !mamState.complete) {
          setTimeout(() => {
            requestXmppRoomHistory(bareRoom, {
              limit: maxRows,
              force: false,
              reason: `${reason}-prefetch`,
              prefetchPages: nextPrefetchPages - 1
            });
          }, 120);
        }
        const activeRoomJid = xmppBareJid(getActiveChannel()?.xmppRoomJid || "");
        if (activeRoomJid && activeRoomJid === bareRoom) {
          renderMessages();
        }
        renderChannels();
        addXmppDebugEvent("iq", "MUC history query completed", {
          roomJid: bareRoom,
          queryId,
          page: mamState.pagesLoaded,
          complete: mamState.complete,
          first: firstId || "",
          canLoadMore: !mamState.complete
        });
      },
      (stanza) => {
        endXmppMamLoading(mamState);
        const permanent = xmppMamErrorIsPermanent(stanza);
        if (permanent) mamState.complete = true;
        const activeRoomJid = xmppBareJid(getActiveChannel()?.xmppRoomJid || "");
        if (activeRoomJid && activeRoomJid === bareRoom) {
          renderMessages();
        }
        renderChannels();
        addXmppDebugEvent("iq", "MUC history query unavailable", {
          roomJid: bareRoom,
          queryId,
          page: mamState.pagesLoaded + 1,
          reason,
          permanent
        });
      },
      XMPP_MAM_REQUEST_TIMEOUT_MS
    );
  } catch (error) {
    endXmppMamLoading(mamState);
    addXmppDebugEvent("error", "Failed to send MUC history query", {
      roomJid: bareRoom,
      queryId,
      reason,
      error: String(error?.message || error || "unknown")
    });
    return false;
  }
  return true;
}

function requestXmppDirectHistory(peerJid, {
  limit = XMPP_MAM_PAGE_SIZE,
  force = false,
  reason = "manual",
  prefetchPages = 1
} = {}) {
  const barePeer = xmppBareJid(peerJid);
  if (!barePeer || !xmppConnection || !globalThis.$iq) return false;
  const prefs = getPreferences();
  const ownBare = xmppBareJid(prefs.xmppJid || "");
  const domainTarget = xmppMamArchiveTargetJid(prefs);
  const archiveTargets = [...new Set([domainTarget, ownBare].filter(Boolean))];
  if (!ownBare || archiveTargets.length === 0) return false;
  const mamState = ensureXmppDmMamState(barePeer);
  if (!mamState) return false;
  recoverStaleXmppMamLoading(mamState, { scope: "dm", peerJid: barePeer, reason: `${reason}-precheck` });
  if (mamState.loading) return false;
  if (!force && mamState.complete) return false;
  if (force) {
    xmppMamResetStateForForceReload(mamState, { includeTargetIndex: true });
  }
  const targetIndex = Math.max(0, Math.min(archiveTargets.length - 1, Number(mamState.targetIndex) || 0));
  const archiveTarget = archiveTargets[targetIndex] || archiveTargets[0];
  if (!archiveTarget) return false;
  const maxRows = Math.max(10, Math.min(200, Number(limit) || XMPP_MAM_PAGE_SIZE));
  const beforeToken = mamState.before || "";
  const queryId = `mam-dm-${createId().slice(0, 8)}-${mamState.pagesLoaded + 1}`;
  beginXmppMamLoading(mamState, queryId);
  const iqBuilder = buildXmppMamQueryIq({
    to: archiveTarget,
    queryId,
    withJid: barePeer,
    maxRows,
    beforeToken
  });
  if (!iqBuilder) return false;
  addXmppDebugEvent("iq", "Requesting DM history", {
    peerJid: barePeer,
    target: archiveTarget,
    targetIndex: targetIndex + 1,
    targetCount: archiveTargets.length,
    max: maxRows,
    before: beforeToken || "(latest)",
    page: mamState.pagesLoaded + 1,
    reason
  });
  try {
    xmppConnection.sendIQ(
      iqBuilder,
      (stanza) => {
        endXmppMamLoading(mamState);
        mamState.targetIndex = targetIndex;
        const { complete, firstId } = parseXmppMamFinPage(stanza);
        xmppMamUpdateStateFromFinPage(mamState, { complete, firstId });
        const nextPrefetchPages = Math.max(1, Number(prefetchPages) || 1);
        if (nextPrefetchPages > 1 && !mamState.complete) {
          setTimeout(() => {
            requestXmppDirectHistory(barePeer, {
              limit: maxRows,
              force: false,
              reason: `${reason}-prefetch`,
              prefetchPages: nextPrefetchPages - 1
            });
          }, 120);
        }
        const activeConversation = getActiveConversation();
        const activePeer = activeConversation?.type === "dm"
          ? xmppPeerJidForDmThread(activeConversation.thread, getCurrentAccount())
          : "";
        if (activePeer && xmppBareJid(activePeer) === barePeer) {
          renderMessages();
        }
        renderDmList();
        addXmppDebugEvent("iq", "DM history query completed", {
          peerJid: barePeer,
          queryId,
          page: mamState.pagesLoaded,
          complete: mamState.complete,
          first: firstId || "",
          canLoadMore: !mamState.complete
        });
      },
      (stanza) => {
        endXmppMamLoading(mamState);
        const permanent = xmppMamErrorIsPermanent(stanza);
        const canFallbackTarget = permanent && (targetIndex + 1) < archiveTargets.length;
        if (canFallbackTarget) {
          xmppMamPrepareFallbackTargetState(mamState, targetIndex + 1);
          addXmppDebugEvent("iq", "DM history retrying alternate archive target", {
            peerJid: barePeer,
            fromTarget: archiveTarget,
            toTarget: archiveTargets[mamState.targetIndex] || ""
          });
          requestXmppDirectHistory(barePeer, {
            limit: maxRows,
            force: false,
            reason: `${reason}-fallback-target`,
            prefetchPages
          });
          return;
        }
        if (permanent) mamState.complete = true;
        const activeConversation = getActiveConversation();
        const activePeer = activeConversation?.type === "dm"
          ? xmppPeerJidForDmThread(activeConversation.thread, getCurrentAccount())
          : "";
        if (activePeer && xmppBareJid(activePeer) === barePeer) {
          renderMessages();
        }
        renderDmList();
        addXmppDebugEvent("iq", "DM history query unavailable", {
          peerJid: barePeer,
          target: archiveTarget,
          queryId,
          page: mamState.pagesLoaded + 1,
          reason,
          permanent
        });
      },
      XMPP_MAM_REQUEST_TIMEOUT_MS
    );
  } catch (error) {
    endXmppMamLoading(mamState);
    addXmppDebugEvent("error", "Failed to send DM history query", {
      peerJid: barePeer,
      target: archiveTarget,
      queryId,
      reason,
      error: String(error?.message || error || "unknown")
    });
    return false;
  }
  return true;
}

