function xmppNegotiatedCallMediaForPeer(peerJid = "", requestedMedia = XMPP_CALL_DEFAULT_MEDIA) {
  if (typeof XEP_0030_0166_CALL_DISCO_GLOBAL.xmppNegotiatedCallMediaForPeer !== "function") return ["audio"];
  return XEP_0030_0166_CALL_DISCO_GLOBAL.xmppNegotiatedCallMediaForPeer(peerJid, requestedMedia, {
    XMPP_CALL_DEFAULT_MEDIA,
    XMPP_JINGLE_AUDIO_NAMESPACE,
    XMPP_JINGLE_VIDEO_NAMESPACE,
    xmppCachedCallFeaturesForPeerFn: xmppCachedCallFeaturesForPeer
  });
}

function xmppShouldUseMinimalRtpForPeer(peerJid = "", media = ["audio", "video"]) {
  if (typeof XEP_0030_0166_CALL_DISCO_GLOBAL.xmppShouldUseMinimalRtpForPeer !== "function") return true;
  return XEP_0030_0166_CALL_DISCO_GLOBAL.xmppShouldUseMinimalRtpForPeer(peerJid, media, {
    XMPP_JINGLE_RTP_RTCP_FB_NAMESPACE,
    XMPP_JINGLE_RTP_HDR_EXT_NAMESPACE,
    XMPP_JINGLE_RTP_SSMA_NAMESPACE,
    XMPP_JINGLE_AUDIO_NAMESPACE,
    XMPP_JINGLE_VIDEO_NAMESPACE,
    xmppCachedCallFeaturesForPeerFn: xmppCachedCallFeaturesForPeer
  });
}

async function xmppAssessConversationCallInterop(conversation = getActiveConversation(), { force = false } = {}) {
  const targets = xmppCallCapabilityTargetsForConversation(conversation);
  if (!conversation || targets.length === 0) {
    return {
      ready: false,
      targets: [],
      chosenTarget: "",
      details: [],
      reason: "no-target"
    };
  }
  const details = [];
  for (const target of targets) {
    try {
      // eslint-disable-next-line no-await-in-loop
      const info = await xmppFetchDiscoInfoCached(target, { force });
      const evalResult = xmppEvaluateCallFeatures(info?.features || new Set());
      const featureList = [...(info?.features || [])];
      details.push({
        target,
        ok: evalResult.ready,
        evalResult,
        featureList
      });
      if (evalResult.ready) {
        return {
          ready: true,
          targets,
          chosenTarget: target,
          details,
          reason: "ok"
        };
      }
    } catch (error) {
      details.push({
        target,
        ok: false,
        evalResult: { hasCore: false, hasMedia: false, hasTransport: false, hasInvite: false, ready: false },
        featureList: [],
        error: String(error?.message || error || "unknown")
      });
    }
  }
  return {
    ready: false,
    targets,
    chosenTarget: "",
    details,
    reason: "missing-features"
  };
}

async function discoverXmppMucRooms({
  connection = xmppConnection,
  prefs = getPreferences(),
  force = false
} = {}) {
  if (!connection || !globalThis.$iq) return [];
  const mucService = resolveXmppMucService(prefs);
  if (!mucService) return [];
  const cacheKey = mucService.toLowerCase();
  const now = Date.now();
  const cached = xmppRoomDiscoveryCacheByService.get(cacheKey);
  if (!force && cached && cached.expiresAt > now) {
    return Array.isArray(cached.rooms) ? cached.rooms : [];
  }
  if (!force && xmppRoomDiscoveryInFlightByService.has(cacheKey)) {
    return xmppRoomDiscoveryInFlightByService.get(cacheKey);
  }
  const task = (async () => {
    try {
      const stanza = await xmppSendIqPromise(
        connection,
        globalThis.$iq({ type: "get", to: mucService }).c("query", { xmlns: "http://jabber.org/protocol/disco#items" }),
        7000
      );
      const rooms = [...stanza.getElementsByTagName("item")]
        .map((node) => {
          const jid = xmppBareJid(node.getAttribute("jid") || "");
          if (!jid || !looksLikeXmppMucJid(jid, prefs)) return null;
          return {
            jid,
            name: decodeHtmlEntities((node.getAttribute("name") || "").toString()).trim().slice(0, 90),
            autojoin: false,
            nick: ""
          };
        })
        .filter(Boolean)
        .slice(0, XMPP_ROOM_DISCOVERY_MAX_ITEMS);
      addXmppDebugEvent("iq", "Discovered MUC rooms via disco#items", {
        service: mucService,
        count: rooms.length
      });
      return rooms;
    } catch (error) {
      addXmppDebugEvent("iq", "MUC room discovery unavailable", {
        service: mucService,
        error: String(error?.message || error || "unknown")
      });
      return [];
    }
  })()
    .then((rooms) => {
      const normalizedRooms = Array.isArray(rooms) ? rooms : [];
      const ttl = normalizedRooms.length > 0
        ? XMPP_ROOM_DISCOVERY_TTL_MS
        : Math.max(60_000, Math.floor(XMPP_ROOM_DISCOVERY_TTL_MS / 4));
      xmppRoomDiscoveryCacheByService.set(cacheKey, {
        rooms: normalizedRooms,
        expiresAt: Date.now() + ttl
      });
      return normalizedRooms;
    })
    .finally(() => {
      xmppRoomDiscoveryInFlightByService.delete(cacheKey);
    });
  xmppRoomDiscoveryInFlightByService.set(cacheKey, task);
  return task;
}

async function discoverXmppHttpUploadService({ connection = xmppConnection, prefs = getPreferences(), force = false } = {}) {
  if (!connection || !globalThis.$iq) return null;
  const domain = xmppDomainFromJid(prefs?.xmppJid || "");
  if (!domain) return null;
  const cacheKey = domain.toLowerCase();
  const now = Date.now();
  const cached = xmppHttpUploadServiceCache.get(cacheKey);
  if (!force && cached && cached.expiresAt > now) {
    if (!cached.serviceJid || !cached.namespace) return null;
    return {
      serviceJid: cached.serviceJid,
      namespace: cached.namespace,
      maxFileSize: cached.maxFileSize
    };
  }
  if (!force && xmppHttpUploadDiscoveryInFlight.has(cacheKey)) {
    return xmppHttpUploadDiscoveryInFlight.get(cacheKey);
  }
  const task = (async () => {
    const candidates = new Set([domain, `upload.${domain}`]);
    try {
      const itemsStanza = await xmppSendIqPromise(
        connection,
        globalThis.$iq({ type: "get", to: domain }).c("query", { xmlns: "http://jabber.org/protocol/disco#items" }),
        7000
      );
      [...itemsStanza.getElementsByTagName("item")].forEach((node) => {
        const jid = xmppBareJid(node.getAttribute("jid") || "");
        if (jid) candidates.add(jid);
      });
    } catch {
      // Domain-level item discovery is optional; continue with known candidates.
    }
    const ordered = [...candidates]
      .map((jid) => xmppBareJid(jid))
      .filter(Boolean);
    for (const jid of ordered) {
      try {
        // eslint-disable-next-line no-await-in-loop
        const info = await xmppFetchDiscoInfo(jid, connection);
        const namespace = info.features.has(XMPP_HTTP_UPLOAD_NAMESPACE)
          ? XMPP_HTTP_UPLOAD_NAMESPACE
          : (info.features.has(XMPP_HTTP_UPLOAD_LEGACY_NAMESPACE) ? XMPP_HTTP_UPLOAD_LEGACY_NAMESPACE : "");
        if (!namespace) continue;
        return {
          serviceJid: jid,
          namespace,
          maxFileSize: Math.max(0, Number(info.maxFileSize) || 0)
        };
      } catch {
        // Try next candidate.
      }
    }
    return null;
  })()
    .then((result) => {
      const ttl = result
        ? XMPP_HTTP_UPLOAD_DISCOVERY_TTL_MS
        : Math.max(90_000, Math.floor(XMPP_HTTP_UPLOAD_DISCOVERY_TTL_MS / 4));
      xmppHttpUploadServiceCache.set(cacheKey, {
        serviceJid: result?.serviceJid || "",
        namespace: result?.namespace || "",
        maxFileSize: result?.maxFileSize || 0,
        expiresAt: Date.now() + ttl
      });
      return result;
    })
    .finally(() => {
      xmppHttpUploadDiscoveryInFlight.delete(cacheKey);
    });
  xmppHttpUploadDiscoveryInFlight.set(cacheKey, task);
  return task;
}

function xmppAttachmentDefaultExtension(type = "", mime = "", currentName = "") {
  const normalizedType = (type || "").toString().toLowerCase();
  const normalizedMime = (mime || "").toString().toLowerCase();
  const normalizedName = (currentName || "").toString().toLowerCase();
  if (/\.[a-z0-9]{1,12}$/i.test(normalizedName)) return "";
  if (normalizedType === "pdf" || normalizedMime.includes("pdf")) return "pdf";
  if (normalizedType === "svg" || normalizedMime.includes("svg")) return "svg";
  if (normalizedType === "swf" || normalizedMime.includes("shockwave-flash")) return "swf";
  if (normalizedType === "audio") return "mp3";
  if (normalizedType === "video") return "mp4";
  if (normalizedType === "text" || normalizedType === "rtf" || normalizedMime.startsWith("text/")) return "txt";
  if (normalizedType === "odf") return "odt";
  if (normalizedType === "html" || normalizedMime.includes("html")) return "html";
  if (normalizedType === "bin") return "bin";
  if (normalizedType === "gif" || normalizedType === "sticker") return "png";
  return "bin";
}

function xmppAttachmentDefaultMimeType(type = "", format = "", fallbackName = "") {
  const normalizedType = (type || "").toString().toLowerCase();
  const normalizedFormat = (format || "").toString().toLowerCase();
  const lowerName = (fallbackName || "").toString().toLowerCase();
  if (normalizedType === "pdf" || /\.pdf$/i.test(lowerName)) return "application/pdf";
  if (normalizedType === "svg" || /\.svg$/i.test(lowerName)) return "image/svg+xml";
  if (normalizedType === "swf" || /\.swf$/i.test(lowerName)) return "application/x-shockwave-flash";
  if (normalizedType === "audio") return "audio/mpeg";
  if (normalizedType === "video") return inferVideoMimeType(lowerName) || "video/mp4";
  if (normalizedType === "text") return "text/plain";
  if (normalizedType === "rtf") return "application/rtf";
  if (normalizedType === "odf") return "application/vnd.oasis.opendocument.text";
  if (normalizedType === "html") return "text/html";
  if (normalizedType === "bin") return "application/octet-stream";
  if (normalizedType === "sticker" && normalizedFormat === "dotlottie") return "application/zip";
  return "image/png";
}

function xmppSafeUploadFileName(name = "", type = "", mime = "") {
  const raw = (name || "").toString().trim().slice(0, 120);
  const cleanedBase = (raw || `${type || "attachment"}-${Date.now().toString(36)}`)
    .replace(/[\\/:*?"<>|]+/g, "-")
    .replace(/\s+/g, " ")
    .replace(/^\.+/, "")
    .trim()
    .slice(0, 100) || `attachment-${Date.now().toString(36)}`;
  const ext = xmppAttachmentDefaultExtension(type, mime, cleanedBase);
  return ext && !/\.[a-z0-9]{1,12}$/i.test(cleanedBase)
    ? `${cleanedBase}.${ext}`
    : cleanedBase;
}

async function xmppAttachmentPayloadFromEntry(entry) {
  const sourceUrl = resolveMediaUrl((entry?.url || "").toString().trim());
  if (!sourceUrl || /^https?:\/\//i.test(sourceUrl)) return null;
  const response = await fetch(sourceUrl, { cache: "no-store" });
  if (!response.ok) throw new Error(`Attachment fetch failed (${response.status})`);
  const blob = await response.blob();
  const fallbackMime = xmppAttachmentDefaultMimeType(entry?.type || "", entry?.format || "", entry?.name || sourceUrl);
  const contentType = (blob.type || fallbackMime || "application/octet-stream").toString();
  const fileName = xmppSafeUploadFileName(entry?.name || "", entry?.type || "", contentType);
  return {
    blob,
    size: Number(blob.size) || 0,
    contentType,
    fileName
  };
}

async function xmppHttpUploadRequestSlot(serviceInfo, payload, connection = xmppConnection) {
  if (!serviceInfo?.serviceJid || !serviceInfo.namespace || !payload) throw new Error("Missing upload slot request data");
  if (!globalThis.$iq) throw new Error("XMPP IQ builder unavailable");
  const requestAttrs = {
    xmlns: serviceInfo.namespace,
    filename: payload.fileName,
    size: String(Math.max(0, Math.floor(Number(payload.size) || 0)))
  };
  if (payload.contentType) requestAttrs["content-type"] = payload.contentType;
  const slotStanza = await xmppSendIqPromise(
    connection,
    globalThis.$iq({ type: "get", to: serviceInfo.serviceJid }).c("request", requestAttrs),
    XMPP_HTTP_UPLOAD_SLOT_TIMEOUT_MS
  );
  const slotNode = [...slotStanza.getElementsByTagName("slot")]
    .find((node) => xmppNodeHasXmlns(node, serviceInfo.namespace))
    || slotStanza.getElementsByTagName("slot")[0]
    || null;
  const putNode = slotNode ? slotNode.getElementsByTagName("put")[0] : null;
  const getNode = slotNode ? slotNode.getElementsByTagName("get")[0] : null;
  const putUrl = (putNode?.getAttribute("url") || "").toString().trim();
  const getUrl = (getNode?.getAttribute("url") || "").toString().trim();
  if (!/^https?:\/\//i.test(putUrl) || !/^https?:\/\//i.test(getUrl)) {
    throw new Error("XMPP upload slot missing PUT/GET URLs");
  }
  const headers = {};
  if (putNode) {
    [...putNode.getElementsByTagName("header")].forEach((node) => {
      const name = (node.getAttribute("name") || "").toString().trim();
      const value = xmppNodeText(node).trim();
      if (!name || !value || headers[name]) return;
      headers[name] = value;
    });
  }
  return { putUrl, getUrl, headers };
}

async function xmppHttpUploadPutFile(slot, payload) {
  if (!slot?.putUrl || !payload?.blob) throw new Error("Missing upload PUT payload");
  const headers = {};
  Object.entries(slot.headers || {}).forEach(([name, value]) => {
    const safeName = (name || "").toString().trim();
    const safeValue = (value || "").toString().trim();
    if (!safeName || !safeValue) return;
    const lower = safeName.toLowerCase();
    if (["host", "origin", "content-length", "cookie"].includes(lower)) return;
    headers[safeName] = safeValue;
  });
  if (!Object.keys(headers).some((key) => key.toLowerCase() === "content-type") && payload.contentType) {
    headers["Content-Type"] = payload.contentType;
  }
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), XMPP_HTTP_UPLOAD_PUT_TIMEOUT_MS);
  try {
    const response = await fetch(slot.putUrl, {
      method: "PUT",
      headers,
      body: payload.blob,
      signal: controller.signal
    });
    if (response.type === "opaque") return true;
    if (!response.ok) throw new Error(`Upload PUT failed (${response.status})`);
    return true;
  } finally {
    clearTimeout(timeoutId);
  }
}

async function encryptAttachmentForOmemo(payload) {
  return encryptBlobForAesgcm(payload?.blob);
}

async function xmppOmemoEncryptAndUploadAttachments(message, { conversationId = "" } = {}) {
  const currentAttachments = normalizeAttachments(message?.attachments);
  if (currentAttachments.length === 0) return { attachments: [], urls: [], failed: 0 };
  const serviceInfo = await discoverXmppHttpUploadService();
  if (!serviceInfo) {
    addXmppDebugEvent("message", "OMEMO HTTP upload unavailable", {
      localAttachmentCount: relayUnshareableAttachmentCount(currentAttachments)
    });
    return { attachments: [], urls: [], failed: currentAttachments.length };
  }
  const maxByService = Math.max(0, Number(serviceInfo.maxFileSize) || 0);
  const hardLimit = maxByService > 0
    ? Math.min(XMPP_HTTP_UPLOAD_MAX_BYTES, maxByService)
    : XMPP_HTTP_UPLOAD_MAX_BYTES;
  const encryptedAttachments = [];
  const aesgcmUrls = [];
  let failedCount = 0;
  for (const entry of currentAttachments) {
    try {
      // eslint-disable-next-line no-await-in-loop
      const payload = await xmppAttachmentPayloadFromEntry(entry);
      if (!payload) {
        failedCount += 1;
        continue;
      }
      if (payload.size <= 0 || payload.size > hardLimit) {
        failedCount += 1;
        addXmppDebugEvent("warn", "Skipped OMEMO attachment size limit", {
          name: entry?.name || "",
          bytes: payload.size,
          hardLimit
        });
        continue;
      }
      // eslint-disable-next-line no-await-in-loop
      const encrypted = await encryptAttachmentForOmemo(payload);
      // eslint-disable-next-line no-await-in-loop
      const slot = await xmppHttpUploadRequestSlot(serviceInfo, {
        fileName: payload.fileName,
        contentType: "application/octet-stream",
        size: encrypted.encryptedBlob.size,
        blob: encrypted.encryptedBlob
      });
      // eslint-disable-next-line no-await-in-loop
      await xmppHttpUploadPutFile(slot, {
        blob: encrypted.encryptedBlob,
        contentType: "application/octet-stream"
      });
      const aesgcmUrl = buildAesgcmUrl(slot.getUrl, encrypted.ivBytes, encrypted.keyBytes);
      if (!aesgcmUrl) {
        failedCount += 1;
        continue;
      }
      aesgcmUrls.push(aesgcmUrl);
      encryptedAttachments.push({
        type: "file",
        url: aesgcmUrl,
        name: payload.fileName,
        format: "aesgcm"
      });
    } catch (error) {
      failedCount += 1;
      addXmppDebugEvent("error", "OMEMO attachment encryption failed", {
        name: entry?.name || "",
        error: String(error?.message || error)
      });
    }
  }
  if (encryptedAttachments.length > 0 && message && typeof message === "object") {
    message.attachments = normalizeAttachments(encryptedAttachments);
    saveState();
    const activeConversation = getActiveConversation();
    if (conversationId && activeConversation?.id === conversationId) renderMessages();
  }
  return { attachments: encryptedAttachments, urls: aesgcmUrls, failed: failedCount };
}

function attachmentSignatureForXmppUpload(attachments) {
  return normalizeAttachments(attachments)
    .map((entry) => `${entry.type}|${entry.url}|${entry.name}|${entry.format}`)
    .join("||");
}

async function xmppPrepareMessageAttachmentsForUpload(message, { conversationId = "" } = {}) {
  const currentAttachments = normalizeAttachments(message?.attachments);
  if (currentAttachments.length === 0) return currentAttachments;
  const hasLocal = currentAttachments.some((entry) => !normalizeRelayTransportAttachmentUrl(entry?.url || ""));
  if (!hasLocal) return currentAttachments;
  const serviceInfo = await discoverXmppHttpUploadService();
  if (!serviceInfo) {
    addXmppDebugEvent("message", "XMPP HTTP upload unavailable; sending local attachment notice only", {
      localAttachmentCount: relayUnshareableAttachmentCount(currentAttachments)
    });
    return currentAttachments;
  }
  const maxByService = Math.max(0, Number(serviceInfo.maxFileSize) || 0);
  const hardLimit = maxByService > 0
    ? Math.min(XMPP_HTTP_UPLOAD_MAX_BYTES, maxByService)
    : XMPP_HTTP_UPLOAD_MAX_BYTES;
  const updated = [];
  let uploadedCount = 0;
  let failedCount = 0;
  for (const entry of currentAttachments) {
    const remoteUrl = normalizeRelayTransportAttachmentUrl(entry?.url || "");
    if (remoteUrl) {
      updated.push(entry);
      continue;
    }
    try {
      // eslint-disable-next-line no-await-in-loop
      const payload = await xmppAttachmentPayloadFromEntry(entry);
      if (!payload) {
        updated.push(entry);
        continue;
      }
      if (payload.size <= 0 || payload.size > hardLimit) {
        failedCount += 1;
        updated.push(entry);
        addXmppDebugEvent("warn", "Skipped XMPP HTTP upload for attachment size limit", {
          name: entry?.name || "",
          bytes: payload.size,
          hardLimit
        });
        continue;
      }
      // eslint-disable-next-line no-await-in-loop
      const slot = await xmppHttpUploadRequestSlot(serviceInfo, payload);
      // eslint-disable-next-line no-await-in-loop
      await xmppHttpUploadPutFile(slot, payload);
      const uploadedType = inferAttachmentTypeFromUrl(slot.getUrl) || entry.type || "file";
      updated.push({
        type: uploadedType,
        url: slot.getUrl,
        name: payload.fileName,
        format: entry.format || inferAttachmentFormat(uploadedType, slot.getUrl)
      });
      uploadedCount += 1;
    } catch (error) {
      failedCount += 1;
      updated.push(entry);
      addXmppDebugEvent("error", "XMPP HTTP upload failed for attachment", {
        name: entry?.name || "",
        error: String(error?.message || error)
      });
    }
  }
  const normalizedUpdated = normalizeAttachments(updated);
  const changed = attachmentSignatureForXmppUpload(normalizedUpdated) !== attachmentSignatureForXmppUpload(currentAttachments);
  if (changed && message && typeof message === "object") {
    message.attachments = normalizedUpdated;
    saveState();
    const activeConversation = getActiveConversation();
    if (conversationId && activeConversation?.id === conversationId) renderMessages();
  }
  if (uploadedCount > 0) {
    if (failedCount > 0) {
      showToast(`${uploadedCount} attachment${uploadedCount === 1 ? "" : "s"} uploaded over XMPP (${failedCount} failed).`, { tone: "info" });
    } else {
      showToast(uploadedCount === 1 ? "Attachment uploaded over XMPP." : `${uploadedCount} attachments uploaded over XMPP.`, { tone: "info" });
    }
  }
  return normalizedUpdated;
}

function publishXmppMessageReaction(conversation, message, account) {
  const prefs = getPreferences();
  if (prefs.relayMode !== "xmpp" || relayStatus !== "connected" || !xmppConnection || !globalThis.$msg) {
    return { ok: false, reason: "xmpp-offline" };
  }
  if (!conversation || !message || !account?.id) return { ok: false, reason: "invalid-args" };
  const targetRefId = preferredXmppReferenceIdForConversationMessage(conversation, message);
  if (!targetRefId) return { ok: false, reason: "missing-reference" };
  const emojiSet = xmppReactionEmojisForActor(message, account.id);
  const reactionStanzaId = `s67-react-${createId().slice(0, 12)}`;
  const reactionOriginId = `s67-origin-${createId().slice(0, 12)}`;
  if (conversation.type === "dm" && conversation.thread) {
    const peerJid = xmppPeerJidForDmThread(conversation.thread, account);
    const dmRoom = relayRoomForDmThread(conversation.thread);
    const roomJid = xmppRoomJidForToken(dmRoom, prefs);
    if (peerJid) {
      const stanza = globalThis.$msg({ to: peerJid, type: "chat", id: reactionStanzaId });
      appendXmppReactionsNode(stanza, targetRefId, emojiSet);
      appendXmppOriginIdNode(stanza, reactionOriginId);
      appendXmppMessageProcessingHints(stanza, { encrypted: false, preferStore: true });
      xmppConnection.send(stanza);
      rememberXmppLocalSentRefs([reactionStanzaId, reactionOriginId]);
      message.xmppRefIds = normalizeXmppRefIdsList([
        ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
        targetRefId,
        reactionStanzaId,
        reactionOriginId
      ]);
      rememberXmppDmMessage(peerJid, reactionStanzaId, message);
      rememberXmppDmMessage(peerJid, reactionOriginId, message);
      addXmppDebugEvent("message", "Sent XMPP message reactions", {
        scope: "dm",
        to: peerJid,
        targetId: targetRefId,
        emojis: emojiSet,
        id: reactionStanzaId,
        originId: reactionOriginId
      });
      return { ok: true, id: reactionStanzaId, targetId: targetRefId };
    }
    if (roomJid) {
      const stanza = globalThis.$msg({ to: roomJid, type: "groupchat", id: reactionStanzaId });
      appendXmppReactionsNode(stanza, targetRefId, emojiSet);
      appendXmppOriginIdNode(stanza, reactionOriginId);
      appendXmppMessageProcessingHints(stanza, { encrypted: false, preferStore: true });
      xmppConnection.send(stanza);
      rememberXmppLocalSentRefs([reactionStanzaId, reactionOriginId]);
      message.xmppRefIds = normalizeXmppRefIdsList([
        ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
        targetRefId,
        reactionStanzaId,
        reactionOriginId
      ]);
      rememberXmppRoomMessage(roomJid, reactionStanzaId, message);
      rememberXmppRoomMessage(roomJid, reactionOriginId, message);
      addXmppDebugEvent("message", "Sent XMPP message reactions", {
        scope: "dm-room",
        to: roomJid,
        targetId: targetRefId,
        emojis: emojiSet,
        id: reactionStanzaId,
        originId: reactionOriginId
      });
      return { ok: true, id: reactionStanzaId, targetId: targetRefId };
    }
    return { ok: false, reason: "missing-dm-target" };
  }
  if (conversation.type === "channel" && conversation.channel) {
    if (!isXmppBackedChannel(conversation.channel)) return { ok: false, reason: "not-xmpp-channel" };
    let roomJid = xmppBareJid(conversation.channel.xmppRoomJid || "");
    if (!roomJid) {
      const roomToken = (conversation.channel.relayRoomToken || "").toString().trim();
      roomJid = xmppRoomJidForToken(roomToken || relayRoomForActiveConversation(), prefs);
    }
    if (!roomJid) return { ok: false, reason: "missing-room-target" };
    const stanza = globalThis.$msg({ to: roomJid, type: "groupchat", id: reactionStanzaId });
    appendXmppReactionsNode(stanza, targetRefId, emojiSet);
    appendXmppOriginIdNode(stanza, reactionOriginId);
    appendXmppMessageProcessingHints(stanza, { encrypted: false, preferStore: true });
    xmppConnection.send(stanza);
    rememberXmppLocalSentRefs([reactionStanzaId, reactionOriginId]);
    message.xmppRefIds = normalizeXmppRefIdsList([
      ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
      targetRefId,
      reactionStanzaId,
      reactionOriginId
    ]);
    rememberXmppRoomMessage(roomJid, reactionStanzaId, message);
    rememberXmppRoomMessage(roomJid, reactionOriginId, message);
    addXmppDebugEvent("message", "Sent XMPP message reactions", {
      scope: "muc",
      to: roomJid,
      targetId: targetRefId,
      emojis: emojiSet,
      id: reactionStanzaId,
      originId: reactionOriginId
    });
    return { ok: true, id: reactionStanzaId, targetId: targetRefId };
  }
  return { ok: false, reason: "unsupported-conversation" };
}

function publishXmppMessageCorrection(conversation, message, account) {
  const prefs = getPreferences();
  if (prefs.relayMode !== "xmpp" || relayStatus !== "connected" || !xmppConnection || !globalThis.$msg) {
    return { ok: false, reason: "xmpp-offline" };
  }
  if (!conversation || !message || !account) return { ok: false, reason: "invalid-args" };
  if ((message.userId || "") !== account.id) return { ok: false, reason: "not-author" };
  const targetRefId = preferredXmppReferenceIdForConversationMessage(conversation, message);
  if (!targetRefId) return { ok: false, reason: "missing-reference" };
  const correctionStanzaId = `s67-edit-${createId().slice(0, 12)}`;
  const correctionOriginId = `s67-origin-${createId().slice(0, 12)}`;
  if (conversation.type === "dm" && conversation.thread) {
    const peerJid = xmppPeerJidForDmThread(conversation.thread, account);
    const dmRoom = relayRoomForDmThread(conversation.thread);
    const roomJid = xmppRoomJidForToken(dmRoom, prefs);
    if (peerJid) {
      const replyMeta = resolveXmppReplyMetaForDm(conversation.thread, message, account, peerJid);
      const bodyPayload = buildXmppMessageBody(message, replyMeta);
      if (!(bodyPayload.body || "").trim()) return { ok: false, reason: "empty-body" };
      const xmppAttachments = xmppShareableAttachmentsForStanza(message);
      const stanza = globalThis.$msg({ to: peerJid, type: "chat", id: correctionStanzaId })
        .c("body").t(bodyPayload.body);
      appendXmppReplyNodes(stanza, replyMeta, bodyPayload.fallbackPrefixLength);
      appendXmppMessageReplaceNode(stanza, targetRefId);
      appendXmppOriginIdNode(stanza, correctionOriginId);
      appendXmppMessageProcessingHints(stanza, { encrypted: false, preferStore: true });
      appendXmppAttachmentMetadataNodes(stanza, xmppAttachments);
      appendXmppChatMarkableNode(stanza);
      appendXmppReceiptRequestNode(stanza);
      xmppConnection.send(stanza);
      rememberXmppLocalSentRefs([correctionStanzaId, correctionOriginId]);
      rememberXmppPendingReceipt(correctionStanzaId, conversation.thread, message, peerJid);
      message.xmppRefIds = normalizeXmppRefIdsList([
        ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
        targetRefId,
        correctionStanzaId,
        correctionOriginId
      ]);
      rememberXmppDmMessage(peerJid, correctionStanzaId, message);
      rememberXmppDmMessage(peerJid, correctionOriginId, message);
      addXmppDebugEvent("message", "Sent XMPP message correction", {
        scope: "dm",
        to: peerJid,
        replaceId: targetRefId,
        id: correctionStanzaId,
        originId: correctionOriginId
      });
      return { ok: true, id: correctionStanzaId, targetId: targetRefId };
    }
    if (roomJid) {
      const replyMeta = resolveXmppReplyMetaForRoom(conversation.thread, message, roomJid);
      const bodyPayload = buildXmppMessageBody(message, replyMeta);
      if (!(bodyPayload.body || "").trim()) return { ok: false, reason: "empty-body" };
      const xmppAttachments = xmppShareableAttachmentsForStanza(message);
      const stanza = globalThis.$msg({ to: roomJid, type: "groupchat", id: correctionStanzaId })
        .c("body").t(bodyPayload.body);
      appendXmppReplyNodes(stanza, replyMeta, bodyPayload.fallbackPrefixLength);
      appendXmppMessageReplaceNode(stanza, targetRefId);
      appendXmppOriginIdNode(stanza, correctionOriginId);
      appendXmppMessageProcessingHints(stanza, { encrypted: false, preferStore: true });
      appendXmppAttachmentMetadataNodes(stanza, xmppAttachments);
      xmppConnection.send(stanza);
      rememberXmppLocalSentRefs([correctionStanzaId, correctionOriginId]);
      message.xmppStanzaId = correctionStanzaId;
      message.xmppRefIds = normalizeXmppRefIdsList([
        ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
        targetRefId,
        correctionStanzaId,
        correctionOriginId
      ]);
      rememberXmppRoomMessage(roomJid, correctionStanzaId, message);
      rememberXmppRoomMessage(roomJid, correctionOriginId, message);
      addXmppDebugEvent("message", "Sent XMPP message correction", {
        scope: "dm-room",
        to: roomJid,
        replaceId: targetRefId,
        id: correctionStanzaId,
        originId: correctionOriginId
      });
      return { ok: true, id: correctionStanzaId, targetId: targetRefId };
    }
    return { ok: false, reason: "missing-dm-target" };
  }
  if (conversation.type === "channel" && conversation.channel) {
    if (!isXmppBackedChannel(conversation.channel)) return { ok: false, reason: "not-xmpp-channel" };
    let roomJid = xmppBareJid(conversation.channel.xmppRoomJid || "");
    if (!roomJid) {
      const roomToken = (conversation.channel.relayRoomToken || "").toString().trim();
      roomJid = xmppRoomJidForToken(roomToken || relayRoomForActiveConversation(), prefs);
    }
    if (!roomJid) return { ok: false, reason: "missing-room-target" };
    const replyMeta = resolveXmppReplyMetaForRoom(conversation.channel, message, roomJid);
    const bodyPayload = buildXmppMessageBody(message, replyMeta);
    if (!(bodyPayload.body || "").trim()) return { ok: false, reason: "empty-body" };
    const xmppAttachments = xmppShareableAttachmentsForStanza(message);
    const stanza = globalThis.$msg({ to: roomJid, type: "groupchat", id: correctionStanzaId })
      .c("body").t(bodyPayload.body);
    appendXmppReplyNodes(stanza, replyMeta, bodyPayload.fallbackPrefixLength);
    appendXmppMessageReplaceNode(stanza, targetRefId);
    appendXmppOriginIdNode(stanza, correctionOriginId);
    appendXmppMessageProcessingHints(stanza, { encrypted: false, preferStore: true });
    appendXmppAttachmentMetadataNodes(stanza, xmppAttachments);
    xmppConnection.send(stanza);
    rememberXmppLocalSentRefs([correctionStanzaId, correctionOriginId]);
    message.xmppStanzaId = correctionStanzaId;
    message.xmppRefIds = normalizeXmppRefIdsList([
      ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
      targetRefId,
      correctionStanzaId,
      correctionOriginId
    ]);
    rememberXmppRoomMessage(roomJid, correctionStanzaId, message);
    rememberXmppRoomMessage(roomJid, correctionOriginId, message);
    addXmppDebugEvent("message", "Sent XMPP message correction", {
      scope: "muc",
      to: roomJid,
      replaceId: targetRefId,
      id: correctionStanzaId,
      originId: correctionOriginId
    });
    return { ok: true, id: correctionStanzaId, targetId: targetRefId };
  }
  return { ok: false, reason: "unsupported-conversation" };
}

function publishRelayChannelMessage(channel, message, account) {
  const prefs = getPreferences();
  if (!["ws", "http", "xmpp"].includes(prefs.relayMode)) return false;
  if (!channel || !message || !account) return false;
  const guild = getActiveGuild();
  const room = relayRoomForActiveConversation();
  if (!room) return false;
  if (prefs.relayMode === "xmpp") {
    if (!xmppConnection) return false;
    if (relayStatus !== "connected") return false;
    const roomJid = xmppRoomJidForToken(room, prefs);
    if (!roomJid) {
      setRelayStatus("error", "XMPP MUC service not configured.");
      return false;
    }
    joinXmppRoom(room, account);
    void (async () => {
      if (!xmppConnection || relayStatus !== "connected") return;
      const roomBare = xmppBareJid(roomJid);
      const omemoEnabled = roomBare ? xmppOmemoEnabledForPeer(roomBare, prefs) : false;
      let omemoAttachmentUrls = [];
      if (omemoEnabled && roomBare) {
        const omemoAttachments = await xmppOmemoEncryptAndUploadAttachments(message, { conversationId: channel.id || "" });
        omemoAttachmentUrls = omemoAttachments.urls || [];
        if (normalizeAttachments(message.attachments).length > 0 && omemoAttachmentUrls.length === 0) {
          showToast("OMEMO attachment encryption failed. Message not sent.", { tone: "error" });
          return;
        }
      } else {
        await xmppPrepareMessageAttachmentsForUpload(message, { conversationId: channel.id || "" });
        if (!xmppConnection || relayStatus !== "connected") return;
      }
      const replyMeta = resolveXmppReplyMetaForRoom(channel, message, roomJid);
      const bodyPayload = buildXmppMessageBody(message, replyMeta);
      let baseBody = (bodyPayload.body || "").trim();
      if (!baseBody && omemoAttachmentUrls.length === 0) return;
      if (omemoEnabled && omemoAttachmentUrls.length > 0 && baseBody) {
        showToast("OMEMO attachments must be sent without extra text. Text was not sent.", { tone: "error" });
        baseBody = "";
        message.text = "";
      }
      const omemoBody = omemoAttachmentUrls.length > 0
        ? omemoAttachmentUrls.join("\n")
        : baseBody;
      const stanzaId = `s67-${createId().slice(0, 12)}`;
      const originId = `s67-origin-${createId().slice(0, 12)}`;
      const stanza = globalThis.$msg({ to: roomJid, type: "groupchat", id: stanzaId })
        .c("body")
        .t(omemoEnabled ? "This message is encrypted with OMEMO." : baseBody);
      appendXmppReplyNodes(stanza, replyMeta, bodyPayload.fallbackPrefixLength);
      appendXmppOriginIdNode(stanza, originId);
      appendXmppMessageProcessingHints(stanza, { encrypted: omemoEnabled, preferStore: !omemoEnabled });
      if (omemoEnabled && roomBare) {
        const ownBare = xmppBareJid(prefs.xmppJid || "");
        if (ownBare) {
          await xmppOmemoEnsureOwnBundle(ownBare);
          const occupantMap = xmppOccupantsByRoomJid.get(roomBare);
          const recipientJids = occupantMap
            ? [...occupantMap.values()].map((entry) => xmppBareJid(entry?.jid || "")).filter(Boolean)
            : [];
          if (recipientJids.length === 0) {
            showToast("OMEMO groupchat requires real JIDs (non-anonymous room).", { tone: "error" });
            return;
          }
          const omemoNamespace = xmppOmemoNamespaceForSend(recipientJids);
          const encryptedPayload = await xmppOmemoEncryptMessageForPeers(recipientJids, omemoBody, ownBare);
          if (!encryptedPayload) {
            showToast("OMEMO groupchat encryption failed.", { tone: "error" });
            return;
          }
          appendXmppOmemoEncryptedNode(stanza, encryptedPayload, { namespace: omemoNamespace });
          appendXmppEmeNode(stanza, { namespace: omemoNamespace, name: "OMEMO" });
          message.xmppEncrypted = true;
          message.xmppEncryptedType = omemoNamespace === XMPP_OMEMO_NAMESPACE_V2 ? "omemo2" : "omemo";
          message.xmppEncryptedLabel = "OMEMO";
          saveState();
        }
      } else {
        appendXmppAttachmentMetadataNodes(stanza, xmppShareableAttachmentsForStanza(message));
      }
      xmppConnection.send(stanza);
      rememberXmppLocalSentRefs([stanzaId, originId]);
      message.xmppStanzaId = stanzaId;
      message.xmppRefIds = normalizeXmppRefIdsList([
        ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
        stanzaId,
        originId
      ]);
      rememberXmppRoomMessage(roomJid, stanzaId, message);
      rememberXmppRoomMessage(roomJid, originId, message);
    })().catch((error) => {
      addXmppDebugEvent("error", "Failed to publish XMPP room message", {
        roomJid,
        error: String(error?.message || error)
      });
    });
    return true;
  }
  if (prefs.relayMode === "http") {
    const endpoint = new URL(normalizeRelayUrl(prefs.relayUrl).replace(/^ws:/i, "http:").replace(/^wss:/i, "https:"));
    endpoint.pathname = "/chat";
    const payload = {
      type: "chat",
      room,
      clientId: relayClientId(),
      guildName: guild?.name || "",
      channelName: channel.name || "",
      message: {
        id: message.id,
        text: relayTransportPacketText(message),
        ts: message.ts || new Date().toISOString(),
        authorUsername: account.username,
        authorDisplay: displayNameForAccount(account, guild?.id || null),
        attachments: relayTransportAttachments(message.attachments, { limit: 4, urlMax: 640 })
      }
    };
    fetch(endpoint.toString(), {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(payload)
    }).catch(() => {
      setRelayStatus("error", "HTTP relay post failed");
    });
    return true;
  }
  if (!relaySocket || relaySocket.readyState !== WebSocket.OPEN) return false;
  if (relayJoinedRoom !== room) joinRelayRoom(room);
  return sendRelayPacket({
    type: "chat",
    room,
    clientId: relayClientId(),
    guildName: guild?.name || "",
    channelName: channel.name || "",
    message: {
      id: message.id,
      text: relayTransportPacketText(message),
      ts: message.ts || new Date().toISOString(),
      authorUsername: account.username,
      authorDisplay: displayNameForAccount(account, guild?.id || null),
      attachments: relayTransportAttachments(message.attachments, { limit: 4, urlMax: 640 })
    }
  });
}

function publishRelayDirectMessage(thread, message, account) {
  const prefs = getPreferences();
  if (!["ws", "http", "xmpp"].includes(prefs.relayMode)) return false;
  if (!thread || !message || !account) return false;
  const room = relayRoomForDmThread(thread);
  if (!room) return false;
  if (prefs.relayMode === "xmpp") {
    if (!xmppConnection) return false;
    if (relayStatus !== "connected") return false;
    const peerJid = xmppPeerJidForDmThread(thread, account);
    const roomJid = xmppRoomJidForToken(room, prefs);
    if (!peerJid && !roomJid) {
      setRelayStatus("error", "XMPP MUC service not configured.");
      return false;
    }
    void (async () => {
      if (!xmppConnection || relayStatus !== "connected") return;
      if (peerJid) {
        const peerBare = xmppBareJid(peerJid);
        const omemoEnabled = peerBare ? xmppOmemoEnabledForPeer(peerBare, prefs) : false;
        const hasAttachments = normalizeAttachments(message.attachments).length > 0;
        let omemoAttachmentUrls = [];
        if (omemoEnabled && hasAttachments) {
          const omemoAttachments = await xmppOmemoEncryptAndUploadAttachments(message, { conversationId: thread.id || "" });
          omemoAttachmentUrls = omemoAttachments.urls || [];
          if (omemoAttachmentUrls.length === 0) {
            showToast("OMEMO attachment encryption failed. Message not sent.", { tone: "error" });
            if (peerBare && addSystemDmMessageByPeerJid(peerBare, "OMEMO attachment encryption failed; message was not sent.")) {
              refreshDmUiForPeerJid(peerBare);
            }
            return;
          }
        }
        if (!omemoEnabled) {
          await xmppPrepareMessageAttachmentsForUpload(message, { conversationId: thread.id || "" });
          if (!xmppConnection || relayStatus !== "connected") return;
        }
        const stanzaId = `s67-${createId().slice(0, 12)}`;
        const originId = `s67-origin-${createId().slice(0, 12)}`;
        const replyMeta = resolveXmppReplyMetaForDm(thread, message, account, peerJid);
        const bodyPayload = buildXmppMessageBody(message, replyMeta);
        let baseBody = (bodyPayload.body || "").trim();
        if (!baseBody && omemoAttachmentUrls.length === 0) return;
        if (omemoEnabled && omemoAttachmentUrls.length > 0 && baseBody) {
          showToast("OMEMO attachments must be sent without extra text. Text was not sent.", { tone: "error" });
          baseBody = "";
          message.text = "";
        }
        const omemoBody = omemoAttachmentUrls.length > 0
          ? omemoAttachmentUrls.join("\n")
          : baseBody;
        const stanza = globalThis.$msg({ to: peerJid, type: "chat", id: stanzaId });
        stanza.c("body").t(omemoEnabled ? "This message is encrypted with OMEMO." : baseBody).up();
        appendXmppReplyNodes(stanza, replyMeta, bodyPayload.fallbackPrefixLength);
        appendXmppOriginIdNode(stanza, originId);
        appendXmppMessageProcessingHints(stanza, { encrypted: omemoEnabled, preferStore: !omemoEnabled });
        if (omemoEnabled) {
          const ownBare = xmppBareJid(prefs.xmppJid || "");
          if (!ownBare) {
            showToast("OMEMO encryption requires a valid XMPP JID.", { tone: "error" });
            return;
          }
          await xmppOmemoEnsureOwnBundle(ownBare);
          const omemoNamespace = xmppOmemoNamespaceForSend([peerBare]);
          const encryptedPayload = await xmppOmemoEncryptMessageForPeers([peerBare], omemoBody, ownBare);
          if (!encryptedPayload) {
            showToast("OMEMO encryption failed. Message not sent.", { tone: "error" });
            addXmppDebugEvent("error", "OMEMO DM encryption failed", {
              to: peerBare || ""
            });
            return;
          }
          appendXmppOmemoEncryptedNode(stanza, encryptedPayload, { namespace: omemoNamespace });
          appendXmppEmeNode(stanza, { namespace: omemoNamespace, name: "OMEMO" });
          message.xmppEncrypted = true;
          message.xmppEncryptedType = omemoNamespace === XMPP_OMEMO_NAMESPACE_V2 ? "omemo2" : "omemo";
          message.xmppEncryptedLabel = "OMEMO";
          saveState();
        } else {
          appendXmppAttachmentMetadataNodes(stanza, xmppShareableAttachmentsForStanza(message));
        }
        const callInvite = parseCallInviteFromText(message.text || "");
        if (!omemoEnabled && callInvite?.url) {
          appendXmppCallInviteNode(stanza, {
            url: callInvite.url,
            audio: true,
            video: true
          });
          addXmppDebugEvent("call", "Sent call-invite in DM", {
            to: peerJid,
            id: stanzaId,
            url: callInvite.url,
            screenShare: Boolean(callInvite.screenShare)
          });
        }
        appendXmppChatMarkableNode(stanza);
        appendXmppReceiptRequestNode(stanza);
        xmppConnection.send(stanza);
        rememberXmppLocalSentRefs([stanzaId, originId]);
        rememberXmppPendingReceipt(stanzaId, thread, message, peerJid);
        message.xmppStanzaId = stanzaId;
        message.xmppRefIds = normalizeXmppRefIdsList([
          ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
          stanzaId,
          originId
        ]);
        rememberXmppDmMessage(peerJid, stanzaId, message);
        rememberXmppDmMessage(peerJid, originId, message);
        return;
      }
      await xmppPrepareMessageAttachmentsForUpload(message, { conversationId: thread.id || "" });
      if (!xmppConnection || relayStatus !== "connected") return;
      joinXmppRoom(room, account);
      const stanzaId = `s67-${createId().slice(0, 12)}`;
      const originId = `s67-origin-${createId().slice(0, 12)}`;
      const replyMeta = resolveXmppReplyMetaForRoom(thread, message, roomJid);
      const bodyPayload = buildXmppMessageBody(message, replyMeta);
      if (!(bodyPayload.body || "").trim()) return;
      const stanza = globalThis.$msg({ to: roomJid, type: "groupchat", id: stanzaId })
        .c("body")
        .t(bodyPayload.body);
      appendXmppReplyNodes(stanza, replyMeta, bodyPayload.fallbackPrefixLength);
      appendXmppOriginIdNode(stanza, originId);
      appendXmppMessageProcessingHints(stanza, { encrypted: false, preferStore: true });
      appendXmppAttachmentMetadataNodes(stanza, xmppShareableAttachmentsForStanza(message));
      xmppConnection.send(stanza);
      rememberXmppLocalSentRefs([stanzaId, originId]);
      message.xmppStanzaId = stanzaId;
      message.xmppRefIds = normalizeXmppRefIdsList([
        ...(Array.isArray(message.xmppRefIds) ? message.xmppRefIds : []),
        stanzaId,
        originId
      ]);
      rememberXmppRoomMessage(roomJid, stanzaId, message);
      rememberXmppRoomMessage(roomJid, originId, message);
    })().catch((error) => {
      addXmppDebugEvent("error", "Failed to publish XMPP direct message", {
        peerJid: peerJid || "",
        roomJid: roomJid || "",
        error: String(error?.message || error)
      });
    });
    return true;
  }
  if (prefs.relayMode === "http") {
    const endpoint = new URL(normalizeRelayUrl(prefs.relayUrl).replace(/^ws:/i, "http:").replace(/^wss:/i, "https:"));
    endpoint.pathname = "/chat";
    fetch(endpoint.toString(), {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        type: "chat",
        room,
        clientId: relayClientId(),
        guildName: "",
        channelName: "dm",
        message: {
          id: message.id,
          text: relayTransportPacketText(message),
          ts: message.ts || new Date().toISOString(),
          authorUsername: account.username,
          authorDisplay: account.displayName || account.username,
          attachments: relayTransportAttachments(message.attachments, { limit: 4, urlMax: 640 })
        }
      })
    }).catch(() => {
      setRelayStatus("error", "HTTP relay post failed");
    });
    return true;
  }
  if (!relaySocket || relaySocket.readyState !== WebSocket.OPEN) return false;
  if (relayJoinedRoom !== room) joinRelayRoom(room);
  return sendRelayPacket({
    type: "chat",
    room,
    clientId: relayClientId(),
    guildName: "",
    channelName: "dm",
    message: {
      id: message.id,
      text: relayTransportPacketText(message),
      ts: message.ts || new Date().toISOString(),
      authorUsername: account.username,
      authorDisplay: account.displayName || account.username,
      attachments: relayTransportAttachments(message.attachments, { limit: 4, urlMax: 640 })
    }
  });
}

function getGuildNotificationMode(guildId) {
  if (!guildId) return "all";
  const prefs = getPreferences();
  return prefs.guildNotifications[guildId] || "all";
}

function setGuildNotificationMode(guildId, mode) {
  if (!guildId) return;
  state.preferences = getPreferences();
  state.preferences.guildNotifications = {
    ...state.preferences.guildNotifications,
    [guildId]: normalizeGuildNotificationMode(mode)
  };
}

function applyGuildNotificationModeToStats(stats, mode) {
  if (mode === "mute") return { unread: 0, mentions: 0 };
  if (mode === "mentions") return { unread: 0, mentions: stats.mentions };
  return stats;
}

function isForumThreadCollapsed(channelId, threadId) {
  if (!channelId || !threadId) return false;
  const prefs = getPreferences();
  return Boolean(prefs.forumCollapsedThreads?.[channelId]?.[threadId]);
}

function setForumThreadCollapsed(channelId, threadId, collapsed) {
  if (!channelId || !threadId) return;
  state.preferences = getPreferences();
  const current = state.preferences.forumCollapsedThreads || {};
  state.preferences.forumCollapsedThreads = {
    ...current,
    [channelId]: {
      ...(current[channelId] || {}),
      [threadId]: Boolean(collapsed)
    }
  };
}

function getForumThreadReadTimestamp(channelId, threadId) {
  if (!channelId || !threadId) return "";
  const prefs = getPreferences();
  return prefs.forumThreadReadState?.[channelId]?.[threadId] || "";
}

function setForumThreadReadTimestamp(channelId, threadId, tsValue) {
  if (!channelId || !threadId) return;
  state.preferences = getPreferences();
  const current = state.preferences.forumThreadReadState || {};
  state.preferences.forumThreadReadState = {
    ...current,
    [channelId]: {
      ...(current[channelId] || {}),
      [threadId]: typeof tsValue === "string" ? tsValue : new Date().toISOString()
    }
  };
}

function getForumThreadSortMode(channelId) {
  if (!channelId) return "latest";
  const prefs = getPreferences();
  return prefs.forumThreadSort?.[channelId] === "created" ? "created" : "latest";
}

function setForumThreadSortMode(channelId, mode) {
  if (!channelId) return;
  state.preferences = getPreferences();
  state.preferences.forumThreadSort = {
    ...(state.preferences.forumThreadSort || {}),
    [channelId]: mode === "created" ? "created" : "latest"
  };
}

function getForumThreadTagFilter(channelId) {
  if (!channelId) return [];
  const prefs = getPreferences();
  return Array.isArray(prefs.forumThreadTagFilter?.[channelId]) ? prefs.forumThreadTagFilter[channelId] : [];
}

function setForumThreadTagFilter(channelId, tagIds) {
  if (!channelId) return;
  state.preferences = getPreferences();
  const current = state.preferences.forumThreadTagFilter || {};
  const normalized = [...new Set((Array.isArray(tagIds) ? tagIds : []).map((id) => (id || "").toString()).filter(Boolean))].slice(0, 8);
  if (normalized.length === 0) {
    const next = { ...current };
    delete next[channelId];
    state.preferences.forumThreadTagFilter = next;
    return;
  }
  state.preferences.forumThreadTagFilter = {
    ...current,
    [channelId]: normalized
  };
}

function toggleForumThreadTagFilter(channelId, tagId) {
  if (!channelId || !tagId) return;
  const current = getForumThreadTagFilter(channelId);
  const has = current.includes(tagId);
  const next = has ? current.filter((entry) => entry !== tagId) : [...current, tagId];
  setForumThreadTagFilter(channelId, next);
}

function forumTagsForChannel(channel) {
  return normalizeForumTags(channel?.forumTags || []);
}

function resolveForumTagByName(channel, name) {
  const normalizedName = sanitizeForumTagName(name);
  if (!normalizedName) return null;
  const tags = forumTagsForChannel(channel);
  return tags.find((tag) => tag.name === normalizedName) || null;
}

function swfAutoplayFromPreferences() {
  return getPreferences().swfAutoplay === "off" ? "off" : "on";
}

function resolveAccountGuildNickname(account, guildId) {
  if (!account || !guildId) return "";
  if (!account.guildProfiles || typeof account.guildProfiles !== "object") return "";
  const profile = account.guildProfiles[guildId];
  return (profile?.nickname || "").toString().trim().slice(0, 32);
}

function displayNameForAccount(account, guildId = null) {
  if (!account) return "Unknown";
  const nick = resolveAccountGuildNickname(account, guildId);
  if (nick) return nick;
  return account.displayName || account.username;
}

function accountBareXmppJid(account) {
  return xmppBareJid(account?.xmppJid || "");
}

function dmPrimaryLabelForAccount(account) {
  if (!account) return "Unknown DM";
  const bareJid = accountBareXmppJid(account);
  if (bareJid) return bareJid;
  return `@${account.username || "unknown"}`;
}

function dmSecondaryLabelForAccount(account) {
  if (!account) return "";
  const bareJid = accountBareXmppJid(account);
  if (bareJid) return `xmpp:${bareJid}`;
  const display = displayNameForAccount(account, null);
  const fallback = `@${account.username || "unknown"}`;
  return display && display !== account.username ? display : fallback;
}

function resolveAccountAvatar(account, guildId = null) {
  const fallback = {
    color: account?.avatarColor || "#57f287",
    url: account?.avatarUrl || ""
  };
  if (!account || !guildId || !account.guildProfiles || typeof account.guildProfiles !== "object") {
    return fallback;
  }
  const profile = account.guildProfiles[guildId];
  if (!profile || typeof profile !== "object") return fallback;
  return {
    color: (profile.avatarColor || fallback.color || "#57f287").toString(),
    url: (profile.avatarUrl || fallback.url || "").toString()
  };
}

function resolveAccountBanner(account, guildId = null) {
  const fallback = (account?.banner || "").toString();
  if (!account || !guildId || !account.guildProfiles || typeof account.guildProfiles !== "object") return fallback;
  const profile = account.guildProfiles[guildId];
  if (!profile || typeof profile !== "object") return fallback;
  return (profile.banner || fallback || "").toString();
}

function getMemberTopRoleColor(server, accountId) {
  const roles = getMemberRoles(server, accountId).filter((role) => role.name !== "@everyone");
  if (roles.length === 0) return "";
  const top = roles[roles.length - 1];
  return (top?.color || "").toString();
}

function getMemberTopRoleName(server, accountId) {
  const roles = getMemberRoles(server, accountId).filter((role) => role.name !== "@everyone");
  if (roles.length === 0) return "";
  return (roles[roles.length - 1]?.name || "").toString();
}

function parseStatusExpiryAt(value) {
  const now = new Date();
  if (value === "30m") return new Date(now.getTime() + 30 * 60 * 1000).toISOString();
  if (value === "1h") return new Date(now.getTime() + 60 * 60 * 1000).toISOString();
  if (value === "4h") return new Date(now.getTime() + 4 * 60 * 60 * 1000).toISOString();
  if (value === "today") {
    const end = new Date(now);
    end.setHours(23, 59, 59, 999);
    return end.toISOString();
  }
  return null;
}

function statusExpiryPreset(account) {
  if (!account?.customStatusExpiresAt) return "never";
  const expiry = new Date(account.customStatusExpiresAt).getTime();
  const now = Date.now();
  const delta = Math.max(0, expiry - now);
  if (delta <= 35 * 60 * 1000) return "30m";
  if (delta <= 65 * 60 * 1000) return "1h";
  if (delta <= 4.5 * 60 * 60 * 1000) return "4h";
  return "today";
}

function resolveAccountStatus(account, guildId = null) {
  if (!account) return { text: "", emoji: "" };
  if (guildId && account.guildProfiles && typeof account.guildProfiles === "object") {
    const profile = account.guildProfiles[guildId];
    const guildStatus = (profile?.status || "").toString().trim().slice(0, 80);
    if (guildStatus) {
      return {
        text: guildStatus,
        emoji: (profile?.statusEmoji || account.customStatusEmoji || "").toString().trim().slice(0, 4)
      };
    }
  }
  return {
    text: (account.customStatus || "").trim(),
    emoji: (account.customStatusEmoji || "").trim().slice(0, 4)
  };
}

function pruneExpiredStatuses() {
  let changed = false;
  const now = Date.now();
  state.accounts.forEach((account) => {
    if (!account?.customStatusExpiresAt) return;
    const expiry = Date.parse(account.customStatusExpiresAt);
    if (!Number.isFinite(expiry) || expiry > now) return;
    account.customStatus = "";
    account.customStatusEmoji = "";
    account.customStatusExpiresAt = null;
    changed = true;
  });
  return changed;
}

function displayStatus(account, guildId = null) {
  if (!account) return "Offline";
  const status = resolveAccountStatus(account, guildId);
  const statusText = status.text;
  if (statusText) {
    const emoji = status.emoji;
    return emoji ? `${emoji} ${statusText}` : statusText;
  }
  return presenceLabel(account.presence);
}

function accountDecorationEmoji(account) {
  return (account?.avatarDecoration || "").toString().trim().slice(0, 4);
}

function accountGuildTag(account) {
  return (account?.guildTag || "").toString().trim().slice(0, 8);
}

function resolveGuildTagGuild(account) {
  if (!account) return null;
  const explicitId = normalizeGuildTagGuildId(account.guildTagGuildId);
  if (explicitId) {
    const explicitGuild = state.guilds.find((guild) => guild.id === explicitId) || null;
    if (explicitGuild) return explicitGuild;
  }
  const memberGuilds = state.guilds.filter((guild) => Array.isArray(guild.memberIds) && guild.memberIds.includes(account.id));
  const activeGuild = getActiveGuild();
  if (activeGuild && memberGuilds.some((guild) => guild.id === activeGuild.id)) return activeGuild;
  const tagToken = accountGuildTag(account).toLowerCase();
  if (tagToken) {
    const matched = memberGuilds.find((guild) => (guild.name || "").toLowerCase().replace(/\s+/g, "").includes(tagToken));
    if (matched) return matched;
  }
  return memberGuilds[0] || null;
}

function accountProfileEffect(account) {
  return normalizeProfileEffect(account?.profileEffect);
}

function accountNameplateSvg(account) {
  const raw = (account?.profileNameplateSvg || "").toString().trim().slice(0, 280);
  if (!raw) return "";
  if (/^data:image\/svg\+xml/i.test(raw)) return raw;
  if (/^https?:\/\//i.test(raw)) return raw;
  return "";
}

function showGuildTagInfo(account) {
  if (!account) return;
  const tag = accountGuildTag(account);
  if (!tag) return;
  const guild = resolveGuildTagGuild(account);
  if (!ui.guildTagInfoDialog) {
    const fallback = guild ? `${tag} · ${guild.name}` : `${tag} · no linked guild`;
    showToast(fallback);
    return;
  }
  const owner = guild?.ownerId ? getAccountById(guild.ownerId) : null;
  const linkedGuildName = guild?.name || "No linked guild";
  const tagOwnerName = displayNameForAccount(account, guild?.id || null);
  if (ui.guildTagInfoTag) ui.guildTagInfoTag.textContent = tag;
  if (ui.guildTagInfoAccount) ui.guildTagInfoAccount.textContent = `Tag owner: ${tagOwnerName}`;
  if (ui.guildTagInfoGuildName) ui.guildTagInfoGuildName.textContent = linkedGuildName;
  if (ui.guildTagInfoMeta) {
    if (guild) {
      const memberCount = Array.isArray(guild.memberIds) ? guild.memberIds.length : 0;
      const channelCount = Array.isArray(guild.channels) ? guild.channels.length : 0;
      ui.guildTagInfoMeta.textContent = `${memberCount} member${memberCount === 1 ? "" : "s"} · ${channelCount} channel${channelCount === 1 ? "" : "s"}`;
    } else {
      ui.guildTagInfoMeta.textContent = "Tag is not linked to a visible guild yet.";
    }
  }
  if (ui.guildTagInfoDescription) {
    ui.guildTagInfoDescription.textContent = guild?.description?.trim() || "No guild description.";
  }
  if (ui.guildTagInfoOwner) {
    ui.guildTagInfoOwner.textContent = owner
      ? `Owner: ${displayNameForAccount(owner, guild?.id || null)}`
      : "Owner: unknown";
  }
  if (ui.guildTagInfoAccent) {
    ui.guildTagInfoAccent.style.background = guild?.accentColor || "#5865f2";
    ui.guildTagInfoAccent.title = guild?.accentColor || "Default accent";
  }
  if (!ui.guildTagInfoDialog.open) ui.guildTagInfoDialog.showModal();
}

function channelTypePrefix(channel) {
  if (!channel || channel.type === "text") return "#";
  if (channel.type === "announcement") return "📣";
  if (channel.type === "forum") return "🗂";
  if (channel.type === "media") return "🖼";
  if (channel.type === "voice") return "🔊";
  if (channel.type === "stage") return "🎙";
  return "#";
}

function channelTypeSymbol(channel) {
  if (!channel || channel.type === "text") return "#";
  if (channel.type === "announcement") return "📣";
  if (channel.type === "forum") return "🧵";
  if (channel.type === "media") return "🖼";
  if (channel.type === "voice") return "🔊";
  if (channel.type === "stage") return "🎙";
  return "#";
}

function channelHeaderGlyph(channel, mode = "channel") {
  if (mode === "dm") return "@";
  if (!channel || channel.type === "text") return "#";
  if (channel.type === "announcement") return "!";
  if (channel.type === "forum") return "≡";
  if (channel.type === "media") return "▦";
  if (channel.type === "voice") return "◉";
  if (channel.type === "stage") return "◎";
  return "#";
}

function setActiveChannelDescription(text) {
  const nextText = (text || "").toString().trim();
  if (!ui.activeChannelDescription) return;
  ui.activeChannelDescription.textContent = nextText;
  ui.activeChannelDescription.classList.toggle("chat-channel-description--empty", !nextText);
}

function setActiveChannelHeader(label, glyph = "#", title = "", description = "") {
  if (ui.activeChannelLabel) ui.activeChannelLabel.textContent = label || "";
  if (ui.activeChannelGlyph) ui.activeChannelGlyph.textContent = glyph || "#";
  if (ui.activeChannelName) {
    ui.activeChannelName.title = title || label || "";
  }
  setActiveChannelDescription(description);
}

function setActiveChannelTopic(text) {
  const nextText = (text || "").toString().trim();
  if (ui.activeChannelTopic) {
    ui.activeChannelTopic.textContent = nextText;
    ui.activeChannelTopic.classList.toggle("chat-topic--empty", !nextText);
  }
}

function activeConversationReferenceText() {
  const conversation = getActiveConversation();
  if (!conversation) return "";
  if (conversation.type === "dm") {
    const current = getCurrentAccount();
    const peerId = conversation.thread?.participantIds?.find((id) => id !== current?.id);
    const peer = peerId ? getAccountById(peerId) : null;
    return peer ? dmSecondaryLabelForAccount(peer) : "@dm";
  }
  const channel = conversation.channel;
  return channel ? `#${channel.name}` : "";
}

function resizeComposerInput() {
  if (!(ui.messageInput instanceof HTMLTextAreaElement)) return;
  ui.messageInput.style.height = "0px";
  const next = Math.max(40, Math.min(160, ui.messageInput.scrollHeight));
  ui.messageInput.style.height = `${next}px`;
}

function isLikelyUrl(value) {
  return /^https?:\/\//i.test((value || "").trim());
}

function isLikelyRichTextLink(value) {
  const token = (value || "").toString().trim();
  return (
    /^https?:\/\//i.test(token)
    || /^mailto:[^\s]+$/i.test(token)
    || /^xmpp:[^\s]+$/i.test(token)
    || /^s67cmd:[^\s]+$/i.test(token)
  );
}

function sanitizeRichTextHref(value) {
  return sanitizeRichTextHrefViaModule(value);
}

function isInlineCommandHref(value) {
  return isInlineCommandHrefViaModule(value);
}

function normalizeSlashCommandInvocation(rawValue) {
  return normalizeSlashCommandInvocationViaModule(rawValue);
}

function invokeInlineCommand(rawValue, { submit = false } = {}) {
  const commandText = normalizeSlashCommandInvocation(rawValue);
  if (!commandText) return false;
  const account = getCurrentAccount();
  const conversation = getActiveConversation();
  if (!account || !conversation || !(ui.messageInput instanceof HTMLTextAreaElement)) {
    showToast("Open a conversation first.", { tone: "error" });
    return false;
  }
  const nextComposerText = submit || /\s/.test(commandText.slice(1))
    ? commandText
    : `${commandText} `;
  ui.messageInput.value = trimTextForConversation(nextComposerText, conversation);
  const caret = ui.messageInput.value.length;
  ui.messageInput.setSelectionRange(caret, caret);
  resizeComposerInput();
  setComposerDraft(conversation.id, ui.messageInput.value);
  queueComposerDraftSave();
  renderSlashSuggestions();
  renderComposerMeta();
  ui.messageInput.focus();
  if (submit) {
    ui.messageForm.requestSubmit();
  }
  return true;
}

function isLikelyImageDataUrl(value) {
  return isLikelyImageDataUrlViaModule(value);
}

function isRenderableAvatarUrl(value) {
  return isRenderableAvatarUrlViaModule(value);
}

function normalizeRenderableAvatarUrl(value) {
  return normalizeRenderableAvatarUrlViaModule(value);
}

function extractUrlFromBackgroundImageValue(value) {
  return extractUrlFromBackgroundImageValueViaModule(value);
}

function avatarUrlHintFromElement(element) {
  if (!(element instanceof HTMLElement)) return "";
  const inlineValue = extractUrlFromBackgroundImageValue(element.style.backgroundImage || "");
  if (inlineValue) return inlineValue;
  try {
    const computedValue = getComputedStyle(element).backgroundImage || "";
    return extractUrlFromBackgroundImageValue(computedValue);
  } catch {
    return "";
  }
}

function applyBannerStyle(element, bannerValue) {
  const value = (bannerValue || "").trim();
  if (!value) {
    element.style.background = "linear-gradient(120deg, #5160f7, #2b45d4)";
    element.style.backgroundImage = "";
    return;
  }
  if (isLikelyUrl(value)) {
    element.style.background = "#2f3136";
    element.style.backgroundImage = `url(${value})`;
    element.style.backgroundSize = "cover";
    element.style.backgroundPosition = "center";
    return;
  }
  element.style.backgroundImage = "";
  element.style.background = value;
}

function applyAvatarStyle(element, account, guildId = null) {
  if (!(element instanceof HTMLElement)) return;
  const avatar = resolveAccountAvatar(account, guildId);
  element.textContent = "";
  delete element.dataset.initial;
  element.removeAttribute("aria-label");
  element.style.backgroundImage = "";
  const resolvedColor = avatar.color || "#57f287";
  element.style.backgroundColor = isDefaultAvatarColor(resolvedColor)
    ? fallbackAvatarColorForAccount(account, guildId, resolvedColor)
    : resolvedColor;
  if (isRenderableAvatarUrl(avatar.url || "")) {
    element.style.backgroundImage = `url(${avatar.url})`;
    element.style.backgroundSize = "cover";
    element.style.backgroundPosition = "center";
    return;
  }
  if (shouldUseStrictInitialAvatar(account, guildId)) {
    applyAvatarInitialGlyph(element, displayNameForAccount(account, guildId) || account?.username || "?");
  }
}

function applyAvatarDecoration(element, account) {
  if (!(element instanceof HTMLElement)) return;
  element.classList.toggle("has-decoration", false);
  const existing = element.querySelector(".avatar-decoration");
  if (existing) existing.remove();
  const emoji = accountDecorationEmoji(account);
  if (!emoji) return;
  const badge = document.createElement("span");
  badge.className = "avatar-decoration";
  badge.textContent = emoji;
  badge.title = "Avatar decoration";
  element.appendChild(badge);
  element.classList.toggle("has-decoration", true);
}

function applyNameplateStyle(element, account) {
  if (!(element instanceof HTMLElement)) return;
  const image = accountNameplateSvg(account);
  if (!image) {
    element.style.removeProperty("--nameplate-image");
    element.classList.remove("has-nameplate");
    return;
  }
  element.style.setProperty("--nameplate-image", `url(${image})`);
  element.classList.add("has-nameplate");
}

function renderProfileAvatarPreview() {
  if (!ui.profileAvatarPreview) return;
  ui.profileAvatarPreview.style.backgroundImage = "";
  ui.profileAvatarPreview.style.backgroundColor = ui.profileAvatarInput.value.trim() || "#57f287";
  const avatarUrl = ui.profileAvatarUrlInput.value.trim();
  if (isRenderableAvatarUrl(avatarUrl)) {
    ui.profileAvatarPreview.style.backgroundImage = `url(${avatarUrl})`;
    ui.profileAvatarPreview.style.backgroundSize = "cover";
    ui.profileAvatarPreview.style.backgroundPosition = "center";
  }
}

function renderProfileIdentityPreview() {
  if (!ui.profileIdentityPreview) return;
  const previewAccount = {
    username: "preview",
    displayName: ui.displayNameInput?.value?.trim() || "Preview User",
    avatarColor: ui.profileAvatarInput?.value?.trim() || "#57f287",
    avatarUrl: ui.profileAvatarUrlInput?.value?.trim() || "",
    banner: ui.profileBannerInput?.value?.trim() || "",
    customStatus: ui.profileStatusInput?.value?.trim() || "",
    customStatusEmoji: ui.profileStatusEmojiInput?.value?.trim() || "",
    presence: ui.presenceInput?.value || "online",
    avatarDecoration: ui.profileAvatarDecorationInput?.value?.trim() || "",
    guildTag: ui.profileGuildTagInput?.value?.trim().slice(0, 8).toUpperCase() || "",
    profileEffect: normalizeProfileEffect(ui.profileEffectInput?.value),
    profileNameplateSvg: ui.profileNameplateSvgInput?.value?.trim() || ""
  };
  applyAvatarStyle(ui.profileIdentityPreviewAvatar, previewAccount, null);
  applyAvatarDecoration(ui.profileIdentityPreviewAvatar, previewAccount);
  applyBannerStyle(ui.profileIdentityPreviewBanner, previewAccount.banner);
  ui.profileIdentityPreviewName.textContent = previewAccount.displayName;
  applyNameplateStyle(ui.profileIdentityPreviewName, previewAccount);
  const tag = accountGuildTag(previewAccount);
  if (tag) {
    ui.profileIdentityPreviewName.appendChild(document.createTextNode(" "));
    const chip = document.createElement("span");
    chip.className = "guild-tag-chip";
    chip.textContent = tag;
    ui.profileIdentityPreviewName.appendChild(chip);
  }
  ui.profileIdentityPreviewStatus.textContent = displayStatus(previewAccount, null);
  ui.profileIdentityPreview.classList.remove("profile-effect-aurora", "profile-effect-flame", "profile-effect-ocean");
  const effect = accountProfileEffect(previewAccount);
  if (effect !== "none") ui.profileIdentityPreview.classList.add(`profile-effect-${effect}`);
}

function setProfileAvatarUploadHint(text, isError = false) {
  if (!ui.profileAvatarUploadHint) return;
  ui.profileAvatarUploadHint.textContent = text;
  ui.profileAvatarUploadHint.style.color = isError ? "#f28b82" : "#aeb4bf";
}

function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : "");
    reader.onerror = () => reject(new Error("file_read_failed"));
    reader.readAsDataURL(file);
  });
}

function formatFileSize(bytes) {
  if (!Number.isFinite(bytes) || bytes <= 0) return "";
  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  if (bytes >= 1024) return `${Math.max(1, Math.round(bytes / 1024))} KB`;
  return `${bytes} B`;
}

function inferAttachmentTypeFromFile(file) {
  if (!file) return null;
  const name = (file.name || "").toLowerCase();
  const mime = (file.type || "").toLowerCase();
  if (name.endsWith(".pdf") || mime === "application/pdf") return "pdf";
  if (name.endsWith(".rtf") || mime === "application/rtf" || mime === "text/rtf") return "rtf";
  if (name.endsWith(".odt") || name.endsWith(".ods") || name.endsWith(".odp")
    || mime.includes("vnd.oasis.opendocument")) return "odf";
  if (/\.(doc|docx|xls|xlsx|ppt|pptx)$/i.test(name) || mime.includes("officedocument") || mime === "application/msword") return "odf";
  if (/\.(mp3|ogg|wav|m4a|flac)$/i.test(name) || /^audio\//i.test(mime)) return "audio";
  if (/\.(mp4|webm|mov|m4v|ogv|m3u8|mkv|avi|wmv|mpe?g|m2ts|ts)$/i.test(name) || /^video\//i.test(mime)) return "video";
  if (/\.(txt|md|log|json|js|ts|css|xml|yml|yaml|ini|toml)$/i.test(name) || /^text\//i.test(mime)) return "text";
  if (name.endsWith(".swf")) return "swf";
  if (name.endsWith(".svg") || mime === "image/svg+xml") return "svg";
  if (name.endsWith(".html") || name.endsWith(".htm") || mime === "text/html") return "html";
  if (name.endsWith(".bin")) return "bin";
  if (name.endsWith(".gif") || name.endsWith(".webp") || /^image\//i.test(mime)) return "gif";
  return "gif";
}

function getComposerAttachAllowedTypes() {
  return new Set(["pdf", "text", "odf", "rtf", "bin", "gif", "video", "audio", "swf", "svg", "html"]);
}

function syncPrimaryComposerAttachment() {
  composerPendingAttachment = composerPendingAttachments[0] || null;
}

function composerAttachmentPreviewLabel(entry) {
  if (!entry) return "file";
  const label = entry.name || "file";
  const type = (entry.type || "file").toUpperCase();
  const size = formatFileSize(Number(entry.sizeBytes || 0));
  return size ? `${type}: ${label} (${size})` : `${type}: ${label}`;
}

function renderComposerAttachmentList() {
  if (!ui.composerAttachmentList) return;
  ui.composerAttachmentList.innerHTML = "";
  composerPendingAttachments.forEach((entry, index) => {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "composer-attachment-chip";
    row.title = composerAttachmentPreviewLabel(entry);
    const thumb = document.createElement("span");
    thumb.className = "composer-attachment-chip__thumb";
    const visualType = (entry?.type || "").toString().toLowerCase();
    const visualUrl = resolveMediaUrl((entry?.url || "").toString());
    const canPreviewImage = ["gif", "svg", "sticker"].includes(visualType);
    const canPreviewVideo = visualType === "video";
    if (canPreviewVideo && visualUrl) {
      const video = document.createElement("video");
      video.src = visualUrl;
      video.muted = true;
      video.playsInline = true;
      video.preload = "metadata";
      video.loop = true;
      video.setAttribute("aria-hidden", "true");
      video.addEventListener("loadeddata", () => {
        void video.play().catch(() => {});
      }, { once: true });
      thumb.appendChild(video);
    } else if (canPreviewImage && visualUrl) {
      const img = document.createElement("img");
      img.src = visualUrl;
      img.alt = "";
      img.loading = "eager";
      img.setAttribute("aria-hidden", "true");
      thumb.appendChild(img);
    } else {
      const icon = document.createElement("span");
      icon.className = "composer-attachment-chip__icon";
      const iconByType = {
        audio: "♪",
        swf: "📼",
        pdf: "📄",
        text: "TXT",
        html: "</>",
        odf: "DOC",
        rtf: "RTF",
        bin: "BIN"
      };
      icon.textContent = iconByType[visualType] || "FILE";
      thumb.appendChild(icon);
    }
    const label = document.createElement("span");
    label.textContent = entry.name || "file";
    const remove = document.createElement("span");
    remove.className = "composer-attachment-chip__remove";
    remove.textContent = "✕";
    row.appendChild(thumb);
    row.appendChild(label);
    row.appendChild(remove);
    row.addEventListener("click", () => {
      composerPendingAttachments.splice(index, 1);
      syncPrimaryComposerAttachment();
      if (composerPendingAttachments.length === 0) {
        clearComposerPendingAttachment();
        return;
      }
      setComposerPendingAttachment(null);
      renderComposerMeta();
    });
    ui.composerAttachmentList.appendChild(row);
  });
}

function clearComposerPendingAttachment() {
  composerPendingAttachments = [];
  composerPendingAttachment = null;
  if (ui.composerAttachmentBar) ui.composerAttachmentBar.classList.add("composer-reply--hidden");
  if (ui.composerAttachmentText) ui.composerAttachmentText.textContent = "";
  if (ui.composerAttachmentList) ui.composerAttachmentList.innerHTML = "";
  if (ui.saveComposerAttachmentBtn) ui.saveComposerAttachmentBtn.hidden = true;
  if (ui.quickAttachInput) ui.quickAttachInput.value = "";
  renderComposerMeta();
}

function setComposerPendingAttachment(entry, { append = true } = {}) {
  if (entry) {
    if (!append) composerPendingAttachments = [];
    composerPendingAttachments.push(entry);
    composerPendingAttachments = composerPendingAttachments.slice(-6);
  }
  syncPrimaryComposerAttachment();
  if (!composerPendingAttachment) {
    clearComposerPendingAttachment();
    return;
  }
  if (ui.composerAttachmentText) {
    ui.composerAttachmentText.textContent = composerPendingAttachments.length > 1
      ? `Attached ${composerPendingAttachments.length} files`
      : `Attached ${composerAttachmentPreviewLabel(composerPendingAttachment)}`;
  }
  renderComposerAttachmentList();
  if (ui.composerAttachmentBar) ui.composerAttachmentBar.classList.remove("composer-reply--hidden");
  if (ui.saveComposerAttachmentBtn) ui.saveComposerAttachmentBtn.hidden = false;
  renderComposerMeta();
}

async function attachFileToComposer(file) {
  if (!file) return false;
  const type = inferAttachmentTypeFromFile(file);
  const allowed = getComposerAttachAllowedTypes();
  if (!allowed.has(type)) return false;
  const url = await readFileAsDataUrl(file);
  setComposerPendingAttachment({
    type,
    url,
    name: file.name || `${type}-${Date.now()}`,
    sizeBytes: Number(file.size) || 0
  }, { append: true });
  return true;
}

function pickerTabForAttachmentType(type) {
  if (type === "pdf") return "pdf";
  if (type === "text") return "text";
  if (type === "rtf" || type === "odf" || type === "bin") return "docs";
  if (type === "html") return "html";
  if (type === "swf") return "swf";
  if (type === "svg") return "svg";
  return "gif";
}

function saveComposerAttachmentToPicker() {
  if (!composerPendingAttachment) return false;
  const guild = getActiveGuild();
  if (!guild) return false;
  let savedAny = false;
  composerPendingAttachments.forEach((pending, index) => {
    const type = pending.type || "pdf";
    const tab = pickerTabForAttachmentType(type);
    const baseName = (pending.name || `${type}-${Date.now()}-${index}`).toString().trim().slice(0, 64);
    const extension = type === "pdf"
      ? ".pdf"
      : type === "text"
        ? ".txt"
        : type === "rtf"
          ? ".rtf"
          : type === "odf"
            ? ".odt"
            : type === "bin"
              ? ".bin"
              : "";
    const resolvedName = baseName.includes(".") || !extension ? baseName : `${baseName}${extension}`;
    const entry = {
      name: sanitizeMediaName(resolvedName, `${tab}-${Date.now().toString().slice(-4)}`),
      url: pending.url,
      format: "image",
      type
    };
    if (upsertGuildResource(tab, entry)) savedAny = true;
  });
  if (!savedAny) return false;
  saveState();
  return true;
}

async function applyProfileAvatarFile(file) {
  if (!file) return;
  if (!file.type.startsWith("image/")) {
    setProfileAvatarUploadHint("Invalid file type. Please choose an image.", true);
    return;
  }
  if (file.size > PROFILE_AVATAR_MAX_BYTES) {
    setProfileAvatarUploadHint("Image is too large. Max size is 2 MB.", true);
    return;
  }
  try {
    const dataUrl = await readFileAsDataUrl(file);
    if (!isLikelyImageDataUrl(dataUrl)) {
      setProfileAvatarUploadHint("Unsupported image format.", true);
      return;
    }
    ui.profileAvatarUrlInput.value = dataUrl;
    renderProfileAvatarPreview();
    setProfileAvatarUploadHint(`Loaded ${file.name} (${Math.ceil(file.size / 1024)} KB).`);
  } catch {
    setProfileAvatarUploadHint("Failed to load image file.", true);
  }
}

function normalizeReactions(reactions) {
  if (!Array.isArray(reactions)) return [];
  const byEmoji = new Map();
  reactions.forEach((item) => {
    const emoji = (item?.emoji || "").toString();
    if (!emoji) return;
    if (!byEmoji.has(emoji)) {
      byEmoji.set(emoji, { emoji, userIds: [] });
    }
    const row = byEmoji.get(emoji);
    const seen = new Set(row.userIds);
    const sourceIds = Array.isArray(item?.userIds) ? item.userIds : [];
    sourceIds.forEach((rawId) => {
      const actorId = (rawId || "").toString().trim();
      if (!actorId || seen.has(actorId)) return;
      seen.add(actorId);
      row.userIds.push(actorId);
    });
  });
  return [...byEmoji.values()].filter((entry) => entry.userIds.length > 0);
}

function canonicalReactionActorIdForConversation(actorUserId, conversation = null) {
  const actorId = (actorUserId || "").toString().trim();
  if (!actorId) return "";
  if (!conversation || conversation.type !== "channel" || !conversation.channel) return actorId;
  const roomJid = xmppBareJid(conversation.channel.xmppRoomJid || "");
  if (!roomJid) return actorId;
  return canonicalXmppRoomReactionActorId(roomJid, actorId) || actorId;
}

function normalizeReactionsForConversation(reactions, conversation = null) {
  const normalized = normalizeReactions(reactions);
  if (!conversation) return normalized;
  const rows = normalized.map((entry) => ({
    emoji: entry.emoji,
    userIds: []
  }));
  normalized.forEach((entry, index) => {
    const row = rows[index];
    const seen = new Set();
    entry.userIds.forEach((actorId) => {
      const canonical = canonicalReactionActorIdForConversation(actorId, conversation);
      if (!canonical || seen.has(canonical)) return;
      seen.add(canonical);
      row.userIds.push(canonical);
    });
  });
  return normalizeReactions(rows);
}

function reactionDisplayNameForActorId(actorUserId, { conversation = null, guildId = null } = {}) {
  const actorId = canonicalReactionActorIdForConversation(actorUserId, conversation) || (actorUserId || "").toString().trim();
  if (!actorId) return "Unknown";
  const account = getAccountById(actorId);
  if (account) return displayNameForAccount(account, guildId);
  const alias = parseXmppRoomAliasActorId(actorId);
  if (alias?.occupantId) {
    const occupant = xmppMucOccupantById(alias.roomJid, alias.occupantId);
    if (occupant?.accountId) {
      const linked = getAccountById(occupant.accountId);
      if (linked) return displayNameForAccount(linked, guildId);
    }
    if (occupant?.nick) return occupant.nick;
    return `occupant ${alias.occupantId.slice(0, 8)}`;
  }
  if (alias?.nick) return alias.nick;
  return actorId;
}

function normalizeMessageReactionsForConversation(message, conversation = null) {
  if (!message || typeof message !== "object") return false;
  const before = xmppReactionSignature(message.reactions);
  const next = normalizeReactionsForConversation(message.reactions, conversation);
  const after = xmppReactionSignature(next);
  if (before === after) return false;
  message.reactions = next;
  return true;
}

function normalizeAttachments(attachments) {
  if (!Array.isArray(attachments)) return [];
  const allowedTypes = new Set(["gif", "video", "sticker", "svg", "swf", "html", "pdf", "audio", "text", "odf", "rtf", "bin", "file"]);
  const allowedFormats = new Set(["image", "dotlottie", "apng"]);
  const seen = new Set();
  return attachments
    .filter((item) => item && typeof item.type === "string" && typeof item.url === "string")
    .map((item) => ({
      type: allowedTypes.has(item.type) ? item.type : "gif",
      url: item.url,
      name: (item.name || "").toString().slice(0, 120),
      format: allowedFormats.has(item.format) ? item.format : "image"
    }))
    .filter((item) => {
      const key = `${item.type}|${item.url}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 6);
}

function normalizePoll(poll) {
  if (!poll || typeof poll !== "object") return null;
  const question = (poll.question || "").toString().trim().slice(0, 220);
  if (!question) return null;
  const options = Array.isArray(poll.options)
    ? poll.options
        .map((option) => ({
          id: (option?.id || createId()).toString().slice(0, 64),
          label: (option?.label || "").toString().trim().slice(0, 120),
          voterIds: Array.isArray(option?.voterIds) ? option.voterIds.filter(Boolean) : []
        }))
        .filter((option) => option.label)
    : [];
  if (options.length < 2) return null;
  return {
    question,
    options: options.slice(0, 12),
    allowsMulti: Boolean(poll.allowsMulti),
    closed: Boolean(poll.closed),
    createdBy: (poll.createdBy || "").toString().slice(0, 64)
  };
}

function normalizeForumTags(value) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  return value
    .map((tag) => {
      const name = sanitizeForumTagName(tag?.name || "");
      if (!name || seen.has(name)) return null;
      seen.add(name);
      const color = /^#[0-9a-f]{3,8}$/i.test((tag?.color || "").toString()) ? tag.color : "#5865f2";
      return {
        id: (tag?.id || createId()).toString().slice(0, 64),
        name,
        color
      };
    })
    .filter(Boolean)
    .slice(0, 24);
}

function normalizeThreadTagIds(value, forumTags) {
  if (!Array.isArray(value) || !Array.isArray(forumTags) || forumTags.length === 0) return [];
  const valid = new Set(forumTags.map((tag) => tag.id));
  return [...new Set(value.map((entry) => (entry || "").toString()).filter((id) => valid.has(id)))].slice(0, 8);
}

function normalizeScheduledMessages(value) {
  if (!Array.isArray(value)) return [];
  return value
    .map((entry) => {
      const conversationType = entry?.conversationType === "dm" ? "dm" : "channel";
      const conversationId = (entry?.conversationId || "").toString();
      const authorId = (entry?.authorId || "").toString();
      const text = clampMessageTextForStorage(entry?.text || "");
      const sendAt = typeof entry?.sendAt === "string" ? entry.sendAt : "";
      if (!conversationId || !authorId || !text.trim()) return null;
      if (!toTimestampMs(sendAt)) return null;
      return {
        id: (entry?.id || createId()).toString().slice(0, 64),
        conversationType,
        conversationId,
        guildId: (entry?.guildId || "").toString().slice(0, 64),
        authorId,
        text,
        createdAt: typeof entry?.createdAt === "string" ? entry.createdAt : new Date().toISOString(),
        sendAt,
        replyTo: entry?.replyTo && typeof entry.replyTo === "object"
          ? {
              messageId: (entry.replyTo.messageId || "").toString().slice(0, 64),
              authorName: (entry.replyTo.authorName || "").toString().slice(0, 60),
              text: (entry.replyTo.text || "").toString().slice(0, 180),
              threadId: (entry.replyTo.threadId || "").toString().slice(0, 64)
            }
          : null
      };
    })
    .filter(Boolean)
    .slice(0, 300);
}

function normalizeSavedSwfs(list) {
  if (!Array.isArray(list)) return [];
  return list
    .filter((entry) => entry && typeof entry.url === "string")
    .map((entry) => ({
      name: (entry.name || "swf").toString().slice(0, 120),
      url: entry.url
    }))
    .slice(0, 24);
}

function sanitizeMediaName(value, fallback = "resource") {
  const cleaned = (value || "")
    .toString()
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9_-]/g, "")
    .slice(0, 32);
  return cleaned || fallback;
}

function ensureGuildMediaCollections(guild) {
  if (!guild) return;
  if (!Array.isArray(guild.customEmojis)) guild.customEmojis = [];
  if (!Array.isArray(guild.customStickers)) guild.customStickers = [];
  if (!Array.isArray(guild.customGifs)) guild.customGifs = [];
  if (!Array.isArray(guild.customSvgs)) guild.customSvgs = [];
  if (!Array.isArray(guild.customPdfs)) guild.customPdfs = [];
  if (!Array.isArray(guild.customTexts)) guild.customTexts = [];
  if (!Array.isArray(guild.customDocs)) guild.customDocs = [];
  if (!Array.isArray(guild.customSwfs)) guild.customSwfs = [];
  if (!Array.isArray(guild.customHtmls)) guild.customHtmls = [];
}

function getGuildResourceBucket(guild, tab) {
  ensureGuildMediaCollections(guild);
  if (tab === "emoji") return guild.customEmojis;
  if (tab === "sticker") return guild.customStickers;
  if (tab === "gif") return guild.customGifs;
  if (tab === "svg") return guild.customSvgs;
  if (tab === "pdf") return guild.customPdfs;
  if (tab === "text") return guild.customTexts;
  if (tab === "docs") return guild.customDocs;
  if (tab === "swf") return guild.customSwfs;
  if (tab === "html") return guild.customHtmls;
  return [];
}

function upsertGuildResource(tab, entry) {
  const guild = getActiveGuild();
  if (!guild || !entry?.url) return false;
  const bucket = getGuildResourceBucket(guild, tab);
  const name = sanitizeMediaName(entry.name || `${tab}-${bucket.length + 1}`);
  const normalized = {
    id: entry.id || createId(),
    name,
    url: entry.url,
    format: entry.format || "image",
    type: (entry.type || "").toString()
  };
  const existingIndex = bucket.findIndex((item) => item.name === normalized.name);
  if (existingIndex >= 0) {
    bucket[existingIndex] = { ...bucket[existingIndex], ...normalized };
  } else {
    bucket.unshift(normalized);
  }
  return true;
}

function loadScriptTag(src, type = "text/javascript") {
  return new Promise((resolve, reject) => {
    const existing = document.querySelector(`script[data-src="${src}"]`);
    if (existing) {
      existing.addEventListener("load", () => resolve(), { once: true });
      existing.addEventListener("error", () => reject(new Error(`Failed to load ${src}`)), { once: true });
      if (existing.dataset.loaded === "1") resolve();
      return;
    }
    const script = document.createElement("script");
    script.async = true;
    script.dataset.src = src;
    if (type === "module") script.type = "module";
    script.src = src;
    script.addEventListener("load", () => {
      script.dataset.loaded = "1";
      resolve();
    }, { once: true });
    script.addEventListener("error", () => reject(new Error(`Failed to load ${src}`)), { once: true });
    document.head.appendChild(script);
  });
}

async function localRuntimeExists(src) {
  const isScriptLikeContentType = (contentType = "") => {
    const value = (contentType || "").toLowerCase();
    if (!value) return true;
    if (value.includes("javascript")) return true;
    if (value.includes("ecmascript")) return true;
    if (value.includes("application/octet-stream")) return true;
    // Guard against dev servers returning index.html for missing files.
    if (value.includes("text/html")) return false;
    return true;
  };
  try {
    const headResponse = await fetch(src, { method: "HEAD", cache: "no-store" });
    if (headResponse.ok) {
      return isScriptLikeContentType(headResponse.headers.get("content-type") || "");
    }
    if (![403, 405, 501].includes(Number(headResponse.status) || 0)) return false;
  } catch {
    // Fall through to GET probe when HEAD is blocked or unsupported.
  }
  try {
    const getResponse = await fetch(src, {
      method: "GET",
      cache: "no-store",
      headers: { Range: "bytes=0-0" }
    });
    if (!getResponse.ok) return false;
    return isScriptLikeContentType(getResponse.headers.get("content-type") || "");
  } catch {
    return false;
  }
}

async function deployMediaRuntimes() {
  let shouldRerender = false;
  const localRuffleCandidates = [
    "vendor/ruffle/ruffle.js"
  ];
  for (const candidate of localRuffleCandidates) {
    if (window.RufflePlayer?.newest) break;
    try {
      // eslint-disable-next-line no-await-in-loop
      const exists = await localRuntimeExists(candidate);
      if (!exists) continue;
      // eslint-disable-next-line no-await-in-loop
      await loadScriptTag(candidate);
      shouldRerender = true;
      addDebugLog("info", "Loaded local Ruffle runtime", { src: candidate });
      break;
    } catch (error) {
      addDebugLog("warn", "Local Ruffle runtime candidate failed", { src: candidate, error: String(error) });
    }
  }
  if (!window.RufflePlayer?.newest) {
    const remoteRuffleCandidates = [
      "https://unpkg.com/@ruffle-rs/ruffle",
      "https://cdn.jsdelivr.net/npm/@ruffle-rs/ruffle"
    ];
    for (const candidate of remoteRuffleCandidates) {
      try {
        // eslint-disable-next-line no-await-in-loop
        await loadScriptTag(candidate);
        shouldRerender = true;
        addDebugLog("info", "Loaded CDN Ruffle runtime", { src: candidate });
        break;
      } catch (error) {
        addDebugLog("warn", "CDN Ruffle runtime candidate failed", { src: candidate, error: String(error) });
      }
    }
  }
  if (!window.RufflePlayer?.newest) {
    addDebugLog("warn", "Failed to load Ruffle runtime (local + CDN fallbacks)");
    // SWF fallback card remains available.
  }
  const localDotLottieCandidates = [
    "vendor/dotlottie/dotlottie-player.mjs"
  ];
  for (const candidate of localDotLottieCandidates) {
    if (typeof customElements !== "undefined" && customElements.get("dotlottie-player")) break;
    try {
      // eslint-disable-next-line no-await-in-loop
      const exists = await localRuntimeExists(candidate);
      if (!exists) continue;
      // eslint-disable-next-line no-await-in-loop
      await loadScriptTag(candidate, "module");
      shouldRerender = true;
      addDebugLog("info", "Loaded local dotLottie runtime", { src: candidate });
      break;
    } catch (error) {
      addDebugLog("warn", "Local dotLottie runtime candidate failed", { src: candidate, error: String(error) });
    }
  }
  if (!(typeof customElements !== "undefined" && customElements.get("dotlottie-player"))) {
    const remoteDotLottieCandidates = [
      "https://unpkg.com/@dotlottie/player-component@2.7.12/dist/dotlottie-player.mjs",
      "https://cdn.jsdelivr.net/npm/@dotlottie/player-component@2.7.12/dist/dotlottie-player.mjs"
    ];
    for (const candidate of remoteDotLottieCandidates) {
      try {
        // eslint-disable-next-line no-await-in-loop
        await loadScriptTag(candidate, "module");
        shouldRerender = true;
        addDebugLog("info", "Loaded CDN dotLottie runtime", { src: candidate });
        break;
      } catch (error) {
        addDebugLog("warn", "CDN dotLottie runtime candidate failed", { src: candidate, error: String(error) });
      }
    }
  }
  if (!(typeof customElements !== "undefined" && customElements.get("dotlottie-player"))) {
    addDebugLog("warn", "Failed to load dotLottie runtime (local + CDN fallbacks)");
    // dotLottie falls back to link/file preview behavior.
  }
  if (shouldRerender && state.currentAccountId) {
    renderMessages();
    if (mediaPickerOpen && mediaPickerTab === "swf") renderMediaPicker();
  }
}

function resolveMediaUrl(url) {
  try {
    return new URL(url, window.location.href).href;
  } catch {
    return url;
  }
}

function mediaProxyUrl(url) {
  const resolved = resolveMediaUrl(url);
  if (!resolved) return "";
  try {
    const parsed = new URL(resolved);
    if (!/^https?:$/i.test(parsed.protocol)) return "";
    if (parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1") return resolved;
  } catch {
    return "";
  }
  return `${XMPP_LOCAL_AUTH_GATEWAY_URL}/media-proxy?url=${encodeURIComponent(resolved)}`;
}

function resolveMediaPlaybackUrl(url, { kind = "" } = {}) {
  const resolved = resolveMediaUrl(url);
  const normalizedKind = (kind || "").toString().toLowerCase();
  if (!resolved) return resolved;
  if (!["video", "swf"].includes(normalizedKind)) return resolved;
  if (!isExternalMediaUrl(resolved)) return resolved;
  if (normalizedKind === "video") {
    const host = mediaUrlHost(resolved);
    const accountDomain = xmppDomainFromJid(getPreferences().xmppJid || "");
    if (accountDomain && (host === accountDomain || host.endsWith(`.${accountDomain}`))) {
      return resolved;
    }
    if (isTrustedMediaUrl(resolved)) return resolved;
  }
  const proxied = mediaProxyUrl(resolved);
  return proxied || resolved;
}

function mediaUrlHost(url) {
  try {
    return new URL(url, window.location.href).hostname.toLowerCase();
  } catch {
    return "";
  }
}

function isIpLikeHost(host) {
  return /^[0-9.]+$/.test(host) || host.includes(":");
}

function registrableDomainForHost(host) {
  const normalized = (host || "").toString().trim().toLowerCase();
  if (!normalized || normalized === "localhost" || isIpLikeHost(normalized)) return normalized;
  const labels = normalized.split(".").filter(Boolean);
  if (labels.length <= 2) return normalized;
  const commonSecondLevel = new Set(["co.uk", "org.uk", "gov.uk", "ac.uk", "com.au", "net.au", "org.au", "co.jp", "com.br"]);
  const suffix2 = labels.slice(-2).join(".");
  if (commonSecondLevel.has(suffix2) && labels.length >= 3) {
    return labels.slice(-3).join(".");
  }
  return labels.slice(-2).join(".");
}

function suggestSubdomainTrustRule(host) {
  const cleaned = (host || "").toString().trim().toLowerCase();
  if (!cleaned) return "";
  const domain = registrableDomainForHost(cleaned);
  if (!domain || domain === cleaned) return cleaned;
  return `*.${domain}`;
}

function normalizeMediaPrivacyUrl(url) {
  return normalizeMediaPrivacyUrlViaModule(url);
}

function mediaPrivacyUrlKeys(url, { includePathVariant = false } = {}) {
  const keys = new Set();
  const normalized = normalizeMediaPrivacyUrl(url);
  if (normalized) keys.add(normalized);
  const resolved = resolveMediaUrl(url);
  if (resolved) keys.add(resolved);
  if (includePathVariant) {
    try {
      const parsed = new URL(normalized || resolved, window.location.href);
      parsed.search = "";
      parsed.hash = "";
      keys.add(parsed.href);
    } catch {
      // Skip invalid URLs.
    }
  }
  return [...keys].filter(Boolean);
}

function allowMediaUrlOnce(url) {
  mediaPrivacyUrlKeys(url, { includePathVariant: true }).forEach((key) => {
    mediaAllowOnceUrls.add(key);
  });
}

function mediaAllowOnceAttachmentKey(attachment, contextKey = "") {
  if (!attachment || typeof attachment !== "object") return "";
  const mediaUrl = (attachment?.url || "").toString().trim();
  if (!mediaUrl) return "";
  const normalized = mediaPrivacyUrlKeys(mediaUrl, { includePathVariant: true })[0] || normalizeMediaPrivacyUrl(mediaUrl);
  if (!normalized) return "";
  return [
    (contextKey || "").toString(),
    (attachment?.type || "").toString(),
    normalized
  ].join("|");
}

function allowMediaAttachmentOnce(attachment, contextKey = "") {
  const key = mediaAllowOnceAttachmentKey(attachment, contextKey);
  if (key) mediaAllowOnceAttachmentKeys.add(key);
  const mediaUrl = (attachment?.url || "").toString().trim();
  if (mediaUrl) allowMediaUrlOnce(mediaUrl);
}

function isMediaAttachmentAllowedOnce(attachment, contextKey = "") {
  const key = mediaAllowOnceAttachmentKey(attachment, contextKey);
  return Boolean(key && mediaAllowOnceAttachmentKeys.has(key));
}

function isExternalMediaUrl(url) {
  return isExternalMediaUrlViaModule(url);
}

function doesMediaRuleMatchHost(rule, host) {
  return doesMediaRuleMatchHostViaModule(rule, host);
}

function isBuiltInTrustedMediaHost(host = "") {
  return isBuiltInTrustedMediaHostViaModule(host);
}

function normalizeMediaRuleToken(rule) {
  return normalizeMediaRuleTokenViaModule(rule);
}

function isBlockedMediaUrl(url) {
  const normalized = normalizeMediaPrivacyUrl(url);
  const host = mediaUrlHost(normalized);
  if (!host) return false;
  const prefs = getPreferences();
  return prefs.mediaDenyRules.some((rule) => doesMediaRuleMatchHost(rule, host));
}

function isTrustedMediaUrl(url) {
  if (isBlockedMediaUrl(url)) return false;
  const candidates = mediaPrivacyUrlKeys(url, { includePathVariant: true });
  if (candidates.some((entry) => mediaAllowOnceUrls.has(entry))) return true;
  const normalized = candidates[0] || normalizeMediaPrivacyUrl(url);
  const host = mediaUrlHost(normalized);
  if (!host) return false;
  const prefs = getPreferences();
  const accountDomain = xmppDomainFromJid(prefs.xmppJid || "");
  if (accountDomain && (host === accountDomain || host.endsWith(`.${accountDomain}`))) {
    return true;
  }
  if (isBuiltInTrustedMediaHost(host)) return true;
  return prefs.mediaTrustRules.some((rule) => doesMediaRuleMatchHost(rule, host));
}

function shouldGateMediaUrl(url) {
  const normalized = normalizeMediaPrivacyUrl(url);
  if (!isExternalMediaUrl(normalized)) return false;
  if (isBlockedMediaUrl(normalized)) return true;
  const prefs = getPreferences();
  if (prefs.mediaPrivacyMode === "off") return false;
  return !isTrustedMediaUrl(normalized);
}

function addMediaTrustRule(rule) {
  const cleaned = normalizeMediaRuleToken(rule);
  if (!cleaned) return false;
  state.preferences = getPreferences();
  const current = normalizeMediaTrustRules(state.preferences.mediaTrustRules);
  if (current.includes(cleaned)) return false;
  state.preferences.mediaTrustRules = [cleaned, ...current].slice(0, 120);
  return true;
}

function removeMediaTrustRule(rule) {
  const cleaned = normalizeMediaRuleToken(rule);
  if (!cleaned) return false;
  state.preferences = getPreferences();
  const current = normalizeMediaTrustRules(state.preferences.mediaTrustRules);
  if (!current.includes(cleaned)) return false;
  state.preferences.mediaTrustRules = current.filter((entry) => entry !== cleaned);
  return true;
}

function addMediaDenyRule(rule) {
  const cleaned = normalizeMediaRuleToken(rule);
  if (!cleaned) return false;
  state.preferences = getPreferences();
  const current = normalizeMediaDenyRules(state.preferences.mediaDenyRules);
  if (current.includes(cleaned)) return false;
  state.preferences.mediaDenyRules = [cleaned, ...current].slice(0, 120);
  return true;
}

function removeMediaDenyRule(rule) {
  const cleaned = normalizeMediaRuleToken(rule);
  if (!cleaned) return false;
  state.preferences = getPreferences();
  const current = normalizeMediaDenyRules(state.preferences.mediaDenyRules);
  if (!current.includes(cleaned)) return false;
  state.preferences.mediaDenyRules = current.filter((entry) => entry !== cleaned);
  return true;
}

function addDebugLog(level, message, data = null) {
  const entry = {
    ts: new Date().toISOString(),
    level,
    message,
    data
  };
  debugLogs.push(entry);
  if (debugLogs.length > 220) debugLogs.shift();
}

function xmppSerializePayload(payload) {
  if (!payload) return "";
  try {
    if (typeof payload === "string") return payload;
    if (typeof payload.tree === "function") {
      const node = payload.tree();
      if (node) return new XMLSerializer().serializeToString(node);
    }
    if (payload.nodeType) return new XMLSerializer().serializeToString(payload);
    if (typeof payload.toString === "function") return payload.toString();
    return JSON.stringify(payload);
  } catch {
    return String(payload);
  }
}

function trimXmppRaw(value, limit = XMPP_DEBUG_RAW_TRUNCATE) {
  const text = (value || "").toString();
  if (text.length <= limit) return text;
  return `${text.slice(0, limit)} ... [truncated ${text.length - limit} chars]`;
}

function addXmppDebugEvent(category, message, data = null) {
  const entry = {
    ts: new Date().toISOString(),
    category: (category || "misc").toString(),
    message: (message || "").toString(),
    data
  };
  xmppDebugEvents.push(entry);
  if (xmppDebugEvents.length > XMPP_DEBUG_EVENT_LIMIT) xmppDebugEvents.shift();
  if (ui.xmppConsoleDialog?.open && !xmppDebugPaused) renderXmppConsoleDialog();
}

function formatXmppConsoleLogs() {
  const normalizedFilter = (xmppDebugFilter || "all").toString();
  const searchToken = (xmppDebugSearch || "").toString().trim().toLowerCase();
  const filtered = xmppDebugEvents.filter((entry) => {
    const category = (entry.category || "").toLowerCase();
    const message = (entry.message || "").toLowerCase();
    let dataText = "";
    if (entry.data != null) {
      try {
        dataText = JSON.stringify(entry.data).toLowerCase();
      } catch {
        dataText = String(entry.data).toLowerCase();
      }
    }
    if (normalizedFilter !== "all") {
      if (normalizedFilter === "message" && !["message", "stanza"].includes(category)) return false;
      else if (normalizedFilter === "raw" && category !== "raw") return false;
      else if (normalizedFilter !== "message" && normalizedFilter !== "raw" && category !== normalizedFilter) return false;
    }
    if (!searchToken) return true;
    return message.includes(searchToken) || dataText.includes(searchToken) || category.includes(searchToken);
  });
  const runtime = {
    relayMode: getPreferences().relayMode,
    relayStatus,
    xmppConnected: Boolean(xmppConnection),
    xmppRuntimeReady,
    xmppRuntimeLastError: xmppRuntimeLastError || "",
    filter: normalizedFilter,
    search: searchToken || "",
    paused: xmppDebugPaused,
    eventsTotal: xmppDebugEvents.length,
    eventsShown: filtered.length,
    activeCallSessions: xmppCallDebugSnapshotAll().slice(0, 8)
  };
  const lines = filtered.map((entry) => {
    const head = `[${entry.ts}] [${entry.category}] ${entry.message}`;
    if (entry.data == null) return head;
    let body = "";
    try {
      body = typeof entry.data === "string" ? entry.data : JSON.stringify(entry.data, null, 2);
    } catch {
      body = String(entry.data);
    }
    return `${head}\n${trimXmppRaw(body)}`;
  });
  return `${JSON.stringify(runtime, null, 2)}\n\n${lines.join("\n\n") || "(no XMPP events yet)"}`;
}

function renderXmppConsoleDialog() {
  if (!ui.xmppConsoleOutput) return;
  if (ui.xmppConsoleFilterInput) ui.xmppConsoleFilterInput.value = xmppDebugFilter;
  if (ui.xmppConsoleSearchInput && ui.xmppConsoleSearchInput.value !== xmppDebugSearch) ui.xmppConsoleSearchInput.value = xmppDebugSearch;
  if (ui.pauseXmppConsoleBtn) ui.pauseXmppConsoleBtn.textContent = xmppDebugPaused ? "Resume" : "Pause";
  ui.xmppConsoleOutput.textContent = formatXmppConsoleLogs();
}

function openXmppConsoleDialog() {
  renderXmppConsoleDialog();
  ui.xmppConsoleDialog?.showModal();
}

function xmppConsoleScopeTargetFromConversation(conversation = getActiveConversation(), account = getCurrentAccount()) {
  if (!conversation) return { kind: "", token: "" };
  if (conversation.type === "dm" && conversation.thread) {
    const peerJid = xmppPeerJidForDmThread(conversation.thread, account);
    const token = xmppBareJid(peerJid);
    if (token) return { kind: "dm", token };
  }
  if (conversation.type === "channel" && conversation.channel?.xmppRoomJid) {
    const token = xmppBareJid(conversation.channel.xmppRoomJid);
    if (token) return { kind: "room", token };
  }
  return { kind: "", token: "" };
}

function applyXmppConsoleScopeArg(rawArg = "", conversation = getActiveConversation(), account = getCurrentAccount()) {
  const argText = (rawArg || "").toString().trim();
  if (!argText || /^all$/i.test(argText) || /^clear$/i.test(argText) || /^reset$/i.test(argText)) {
    xmppDebugSearch = "";
    return { ok: true, scoped: false, token: "", message: "Opened full XMPP inspector log." };
  }
  const scopeFromConversation = xmppConsoleScopeTargetFromConversation(conversation, account);
  const [scopeRaw, ...rest] = argText.split(/\s+/).filter(Boolean);
  const scope = (scopeRaw || "").toString().trim().toLowerCase();
  let token = "";
  if (scope === "here") {
    token = scopeFromConversation.token;
  } else if (scope === "dm" || scope === "peer" || scope === "jid" || scope === "user") {
    token = xmppBareJid(rest.join(" ")) || (scopeFromConversation.kind === "dm" ? scopeFromConversation.token : "");
  } else if (scope === "room" || scope === "channel" || scope === "muc") {
    token = xmppBareJid(rest.join(" ")) || (scopeFromConversation.kind === "room" ? scopeFromConversation.token : "");
  } else {
    token = xmppBareJid(argText) || argText.toLowerCase();
  }
  if (!token) {
    return {
      ok: false,
      scoped: false,
      token: "",
      message: "No XMPP DM/room scope was found. Try /xmppconsole all."
    };
  }
  xmppDebugSearch = token;
  return { ok: true, scoped: true, token, message: `Opened XMPP inspector scoped to "${token}".` };
}

function formatDebugLogs() {
  const runtime = {
    location: window.location.href,
    ruffleReady: Boolean(window.RufflePlayer?.newest),
    dotLottieReady: typeof customElements !== "undefined" && Boolean(customElements.get("dotlottie-player")),
    activeGuildId: state.activeGuildId || null,
    activeChannelId: state.activeChannelId || null
  };
  return JSON.stringify({ runtime, logs: debugLogs }, null, 2);
}

function renderDebugDialog() {
  ui.debugOutput.textContent = formatDebugLogs();
}

function openDebugDialog() {
  renderDebugDialog();
  ui.debugDialog.showModal();
}

function serializeMessageAsJson(message) {
  return JSON.stringify({
    id: message.id,
    userId: message.userId || null,
    authorName: message.authorName || "",
    text: message.text || "",
    ts: message.ts,
    editedAt: message.editedAt || null,
    editedByUserId: message.editedByUserId || null,
    editedByName: message.editedByName || "",
    editedByStaff: Boolean(message.editedByStaff),
    collaborative: Boolean(message.collaborative),
    editHistory: messageEditHistory(message),
    replyTo: message.replyTo || null,
    pinned: Boolean(message.pinned),
    reactions: normalizeReactions(message.reactions),
    attachments: normalizeAttachments(message.attachments),
    poll: normalizePoll(message.poll)
  }, null, 2);
}

function xmlEscape(value) {
  return (value || "")
    .toString()
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function nextFrame() {
  return new Promise((resolve) => requestAnimationFrame(() => resolve()));
}

function serializeMessageAsXml(message) {
  const reactionsXml = normalizeReactions(message.reactions)
    .map((reaction) => `    <reaction emoji="${xmlEscape(reaction.emoji)}" count="${reaction.userIds.length}" />`)
    .join("\n");
  const attachmentsXml = normalizeAttachments(message.attachments)
    .map((attachment) => `    <attachment type="${xmlEscape(attachment.type)}" format="${xmlEscape(attachment.format || "image")}" name="${xmlEscape(attachment.name || "")}" url="${xmlEscape(attachment.url)}" />`)
    .join("\n");
  const poll = normalizePoll(message.poll);
  const pollXml = poll
    ? `  <poll question="${xmlEscape(poll.question)}" closed="${poll.closed ? "true" : "false"}" allowsMulti="${poll.allowsMulti ? "true" : "false"}">\n${poll.options.map((option) => `    <option id="${xmlEscape(option.id)}" votes="${option.voterIds.length}">${xmlEscape(option.label)}</option>`).join("\n")}\n  </poll>`
    : "  <poll />";
  return [
    `<message id="${xmlEscape(message.id)}" ts="${xmlEscape(message.ts)}"${message.editedAt ? ` editedAt="${xmlEscape(message.editedAt)}"` : ""}${message.editedByStaff ? " editedByStaff=\"true\"" : ""}>`,
    `  <author userId="${xmlEscape(message.userId || "")}">${xmlEscape(displayNameForMessage(message))}</author>`,
    `  <text>${xmlEscape(message.text || "")}</text>`,
    `  <pinned>${message.pinned ? "true" : "false"}</pinned>`,
    reactionsXml ? `  <reactions>\n${reactionsXml}\n  </reactions>` : "  <reactions />",
    attachmentsXml ? `  <attachments>\n${attachmentsXml}\n  </attachments>` : "  <attachments />",
    pollXml,
    `</message>`
  ].join("\n");
}

function xmppReactionSignature(reactions) {
  return normalizeReactions(reactions)
    .map((entry) => `${entry.emoji}|${entry.userIds.join(",")}`)
    .join("||");
}

function xmppReactionEmojisForActor(message, actorUserId = "") {
  const actorId = (actorUserId || "").toString().trim();
  if (!actorId || !message) return [];
  return normalizeReactions(message.reactions)
    .filter((entry) => entry.userIds.includes(actorId))
    .map((entry) => (entry.emoji || "").toString().trim())
    .filter(Boolean)
    .slice(0, 8);
}

function toggleReaction(message, emoji, userId) {
  if (!message || !emoji || !userId) return false;
  const before = xmppReactionSignature(message.reactions);
  if (emoji) rememberRecentEmoji(emoji);
  message.reactions = normalizeReactions(message.reactions);
  let reaction = message.reactions.find((item) => item.emoji === emoji);
  if (!reaction) {
    reaction = { emoji, userIds: [userId] };
    message.reactions.push(reaction);
    return before !== xmppReactionSignature(message.reactions);
  }
  const idx = reaction.userIds.indexOf(userId);
  if (idx === -1) {
    reaction.userIds.push(userId);
  } else {
    reaction.userIds.splice(idx, 1);
  }
  message.reactions = message.reactions.filter((item) => item.userIds.length > 0);
  return before !== xmppReactionSignature(message.reactions);
}

function toggleMessageReactionForCurrentConversation(conversation, message, emoji, account = getCurrentAccount()) {
  if (!conversation || !message || !emoji || !account?.id) return false;
  const normalizedChanged = normalizeMessageReactionsForConversation(message, conversation);
  const changed = toggleReaction(message, emoji, account.id);
  if (!changed && !normalizedChanged) return false;
  if (changed) {
    const publishResult = publishXmppMessageReaction(conversation, message, account);
    const prefs = getPreferences();
    if (
      prefs.relayMode === "xmpp"
      && publishResult
      && publishResult.ok === false
      && !["not-xmpp-channel", "xmpp-offline"].includes((publishResult.reason || "").toString())
    ) {
      showToast(`Reaction sync issue: ${publishResult.reason || "unknown"}.`, { tone: "error" });
    }
  }
  saveState();
  renderMessages();
  return true;
}

function parsePollFromCommandArg(arg) {
  const parts = (arg || "")
    .split("|")
    .map((part) => part.trim())
    .filter(Boolean);
  if (parts.length < 3) return null;
  const [question, ...optionParts] = parts;
  const options = optionParts
    .slice(0, 12)
    .map((label) => ({ id: createId(), label: label.slice(0, 120), voterIds: [] }))
    .filter((option) => option.label);
  if (!question || options.length < 2) return null;
  return {
    question: question.slice(0, 220),
    options,
    allowsMulti: false,
    closed: false
  };
}

function findLatestPollMessage(channel) {
  if (!channel || !Array.isArray(channel.messages)) return null;
  for (let i = channel.messages.length - 1; i >= 0; i -= 1) {
    const message = channel.messages[i];
    if (normalizePoll(message?.poll)) return message;
  }
  return null;
}

function getPollTotalVotes(poll) {
  const normalized = normalizePoll(poll);
  if (!normalized) return 0;
  const voters = new Set();
  normalized.options.forEach((option) => {
    option.voterIds.forEach((voterId) => voters.add(voterId));
  });
  return voters.size;
}

function setPollVotesForUser(message, optionIds, userId) {
  const poll = normalizePoll(message?.poll);
  if (!poll || poll.closed || !poll.allowsMulti || !userId) return false;
  const allowed = new Set(poll.options.map((option) => option.id));
  const requested = [...new Set((Array.isArray(optionIds) ? optionIds : []).filter((id) => allowed.has(id)))];
  const before = poll.options
    .filter((option) => option.voterIds.includes(userId))
    .map((option) => option.id)
    .sort()
    .join(",");
  poll.options.forEach((option) => {
    option.voterIds = option.voterIds.filter((voterId) => voterId !== userId);
    if (requested.includes(option.id)) option.voterIds.push(userId);
  });
  message.poll = poll;
  const after = poll.options
    .filter((option) => option.voterIds.includes(userId))
    .map((option) => option.id)
    .sort()
    .join(",");
  return before !== after;
}

function togglePollVote(message, optionId, userId) {
  const poll = normalizePoll(message?.poll);
  if (!poll || poll.closed || !optionId || !userId) return false;
  const target = poll.options.find((option) => option.id === optionId);
  if (!target) return false;
  if (poll.allowsMulti) {
    const wasSelected = target.voterIds.includes(userId);
    if (wasSelected) {
      target.voterIds = target.voterIds.filter((voterId) => voterId !== userId);
    } else {
      target.voterIds.push(userId);
    }
  } else {
    const wasSelected = target.voterIds.includes(userId);
    poll.options.forEach((option) => {
      option.voterIds = option.voterIds.filter((voterId) => voterId !== userId);
    });
    if (!wasSelected) {
      target.voterIds.push(userId);
    }
  }
  message.poll = poll;
  return true;
}

function closeOrOpenLatestPoll(channel, closed) {
  const pollMessage = findLatestPollMessage(channel);
  if (!pollMessage) return false;
  const poll = normalizePoll(pollMessage.poll);
  if (!poll) return false;
  if (poll.closed === closed) return false;
  pollMessage.poll = { ...poll, closed };
  return true;
}

function formatPollResultsText(message, { includeVoters = false } = {}) {
  const poll = normalizePoll(message?.poll);
  if (!poll) return "No poll.";
  const total = getPollTotalVotes(poll);
  const lines = poll.options.map((option) => {
    const votes = option.voterIds.length;
    const percent = total > 0 ? Math.round((votes / total) * 100) : 0;
    const voterSuffix = includeVoters ? ` [${formatPollOptionVoters(option)}]` : "";
    return `- ${option.label}: ${votes} vote${votes === 1 ? "" : "s"} (${percent}%)${voterSuffix}`;
  });
  return `${poll.question}\n${lines.join("\n")}\nTotal voters: ${total}`;
}

function formatPollOptionVoters(option) {
  const ids = Array.isArray(option?.voterIds) ? option.voterIds : [];
  if (ids.length === 0) return "No votes yet.";
  const labels = ids
    .slice(0, 8)
    .map((id) => {
      const account = getAccountById(id);
      return account ? `@${account.username}` : id.slice(0, 8);
    });
  const suffix = ids.length > labels.length ? ` +${ids.length - labels.length} more` : "";
  return `${labels.join(", ")}${suffix}`;
}

function canManagePollMessage(message, { isDm = false, canManageMessages = false, currentUser = null } = {}) {
  if (!message?.poll || !currentUser) return false;
  if (message.userId && message.userId === currentUser.id) return true;
  return !isDm && canManageMessages;
}

function renderMessagePoll(container, message, { currentUser = null, isDm = false, canManageMessages = false, onChanged = null } = {}) {
  const poll = normalizePoll(message?.poll);
  if (!poll) return;
  const wrap = document.createElement("div");
  wrap.className = "message-poll";
  const question = document.createElement("div");
  question.className = "message-poll__question";
  question.textContent = poll.question;
  wrap.appendChild(question);
  const total = getPollTotalVotes(poll);
  poll.options.forEach((option) => {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "message-poll__option";
    const votes = option.voterIds.length;
    const percent = total > 0 ? Math.round((votes / total) * 100) : 0;
    const isSelected = currentUser ? option.voterIds.includes(currentUser.id) : false;
    row.classList.toggle("is-selected", isSelected);
    if (poll.closed) row.disabled = true;
    row.style.setProperty("--poll-fill", `${percent}%`);
    row.title = formatPollOptionVoters(option);
    row.innerHTML = `<span>${index + 1}. ${option.label}</span><small>${votes} · ${percent}%</small>`;
    row.addEventListener("click", () => {
      if (!currentUser) return;
      const changed = togglePollVote(message, option.id, currentUser.id);
      if (!changed) return;
      if (typeof onChanged === "function") onChanged();
    });
    wrap.appendChild(row);
  });
  const foot = document.createElement("div");
  foot.className = "message-poll__meta";
  foot.textContent = `${total} voter${total === 1 ? "" : "s"} · ${poll.allowsMulti ? "multi-choice" : "single-choice"}${poll.closed ? " · closed" : ""}`;
  if (canManagePollMessage(message, { isDm, canManageMessages, currentUser })) {
    const closeBtn = document.createElement("button");
    closeBtn.type = "button";
    closeBtn.className = "message-poll__close";
    closeBtn.textContent = poll.closed ? "Reopen poll" : "Close poll";
    closeBtn.addEventListener("click", () => {
      message.poll = { ...poll, closed: !poll.closed };
      if (typeof onChanged === "function") onChanged();
    });
    foot.appendChild(closeBtn);
  }
  wrap.appendChild(foot);
  container.appendChild(wrap);
}

function addSystemMessage(channel, text) {
  channel.messages.push({
    id: createId(),
    userId: null,
    authorName: "system",
    text,
    ts: new Date().toISOString(),
    reactions: [],
    attachments: []
  });
}

function addSystemDmMessageByPeerJid(peerJid, text) {
  const bare = xmppBareJid(peerJid);
  if (!bare) return false;
  let thread = findXmppDmThreadByPeerJid(bare);
  if (!thread) {
    const current = getCurrentAccount();
    const peer = ensureAccountByXmppJid(bare, bare.split("@")[0] || "xmpp");
    if (!current || !peer) return false;
    thread = getOrCreateDmThread(current, peer);
  }
  if (!thread || !Array.isArray(thread.messages) || !text) return false;
  thread.messages.push({
    id: createId(),
    userId: null,
    authorName: "system",
    text: (text || "").toString().slice(0, 480),
    ts: new Date().toISOString(),
    reactions: [],
    attachments: []
  });
  return true;
}

function refreshDmUiForPeerJid(peerJid) {
  const bare = xmppBareJid(peerJid);
  if (!bare) return;
  renderDmList();
  const activeConversation = getActiveConversation();
  if (activeConversation?.type !== "dm") return;
  const activePeer = xmppPeerJidForDmThread(activeConversation.thread, getCurrentAccount());
  if (xmppBareJid(activePeer) !== bare) return;
  renderMessages();
}

function ensureScheduledMessagesStore() {
  if (!Array.isArray(state.scheduledMessages)) {
    state.scheduledMessages = [];
  }
  state.scheduledMessages = normalizeScheduledMessages(state.scheduledMessages);
  return state.scheduledMessages;
}

function parseScheduleWhen(rawWhen) {
  const cleaned = (rawWhen || "").trim().toLowerCase();
  if (!cleaned) return 0;
  const rel = cleaned.match(/^(\d{1,5})\s*([smhd])$/i);
  if (rel) {
    const amount = Number(rel[1]);
    const unit = rel[2].toLowerCase();
    const factor = unit === "s" ? 1000 : unit === "m" ? 60000 : unit === "h" ? 3600000 : 86400000;
    return Date.now() + (amount * factor);
  }
  const parsed = Date.parse(rawWhen);
  return Number.isFinite(parsed) ? parsed : 0;
}

function formatRelativeMs(targetMs) {
  const delta = targetMs - Date.now();
  if (delta <= 0) return "due now";
  const sec = Math.ceil(delta / 1000);
  if (sec < 60) return `${sec}s`;
  const min = Math.ceil(sec / 60);
  if (min < 60) return `${min}m`;
  const hour = Math.ceil(min / 60);
  if (hour < 48) return `${hour}h`;
  const day = Math.ceil(hour / 24);
  return `${day}d`;
}

function queueScheduledMessage(conversation, account, whenRaw, textBody) {
  const whenMs = parseScheduleWhen(whenRaw);
  if (!whenMs || whenMs < Date.now() + 2000) return { ok: false, error: "Choose a time at least 2s in the future." };
  const messageText = trimTextForConversation((textBody || "").toString().trim(), conversation);
  if (!messageText) return { ok: false, error: "Scheduled message cannot be empty." };
  const queue = ensureScheduledMessagesStore();
  const entry = {
    id: createId(),
    conversationType: conversation.type === "dm" ? "dm" : "channel",
    conversationId: conversation.id,
    guildId: conversation.type === "channel" ? (getActiveGuild()?.id || "") : "",
    authorId: account.id,
    text: messageText,
    createdAt: new Date().toISOString(),
    sendAt: new Date(whenMs).toISOString(),
    replyTo: replyTarget && replyTarget.channelId === conversation.id
      ? {
          messageId: replyTarget.messageId,
          authorName: replyTarget.authorName,
          text: replyTarget.text,
          threadId: replyTarget.threadId || null
        }
      : null
  };
  queue.push(entry);
  queue.sort((a, b) => toTimestampMs(a.sendAt) - toTimestampMs(b.sendAt));
  return { ok: true, entry };
}

function listScheduledMessagesForConversation(conversationId) {
  const queue = ensureScheduledMessagesStore();
  return queue
    .filter((entry) => entry.conversationId === conversationId)
    .sort((a, b) => toTimestampMs(a.sendAt) - toTimestampMs(b.sendAt));
}

function removeScheduledMessageByToken(conversationId, token) {
  const queue = ensureScheduledMessagesStore();
  if (!token) return 0;
  const cleaned = token.toLowerCase();
  if (cleaned === "all") {
    const keep = queue.filter((entry) => entry.conversationId !== conversationId);
    const removed = queue.length - keep.length;
    state.scheduledMessages = keep;
    return removed;
  }
  if (cleaned === "last") {
    for (let i = queue.length - 1; i >= 0; i -= 1) {
      if (queue[i].conversationId !== conversationId) continue;
      queue.splice(i, 1);
      return 1;
    }
    return 0;
  }
  const index = queue.findIndex((entry) => (
    entry.conversationId === conversationId
    && (entry.id === token || entry.id.startsWith(token))
  ));
  if (index < 0) return 0;
  queue.splice(index, 1);
  return 1;
}

function runScheduledDispatch() {
  const queue = ensureScheduledMessagesStore();
  if (queue.length === 0) return false;
  const now = Date.now();
  const due = queue.filter((entry) => toTimestampMs(entry.sendAt) <= now);
  if (due.length === 0) return false;
  let changed = false;
  due.forEach((entry) => {
    const author = getAccountById(entry.authorId);
    if (!author) {
      changed = true;
      return;
    }
    if (entry.conversationType === "dm") {
      const thread = state.dmThreads.find((candidate) => candidate.id === entry.conversationId);
      if (!thread) {
        changed = true;
        return;
      }
      thread.messages.push({
        id: createId(),
        userId: author.id,
        authorName: "",
        text: entry.text,
        ts: new Date().toISOString(),
        reactions: [],
        attachments: [],
        replyTo: entry.replyTo || null
      });
      changed = true;
      return;
    }
    const channel = findChannelById(entry.conversationId);
    if (!channel) {
      changed = true;
      return;
    }
    const nextMessage = {
      id: createId(),
      userId: author.id,
      authorName: "",
      text: entry.text,
      ts: new Date().toISOString(),
      reactions: [],
      attachments: [],
      replyTo: entry.replyTo || null
    };
    if (channel.type === "forum") {
      if (entry.replyTo?.threadId) {
        nextMessage.forumThreadId = entry.replyTo.threadId;
        nextMessage.forumParentId = entry.replyTo.messageId || entry.replyTo.threadId;
      } else {
        const [firstLine, ...rest] = entry.text.split("\n");
        nextMessage.forumTitle = (firstLine || "Untitled Post").trim().slice(0, 100) || "Untitled Post";
        nextMessage.text = rest.join("\n").trim();
      }
    }
    channel.messages.push(nextMessage);
    changed = true;
  });
  state.scheduledMessages = queue.filter((entry) => toTimestampMs(entry.sendAt) > now);
  if (changed) {
    saveState();
    safeRender("scheduled-dispatch");
  }
  return changed;
}

function ensureScheduledDispatchTimer() {
  if (scheduledDispatchTimer) return;
  scheduledDispatchTimer = window.setInterval(() => {
    runScheduledDispatch();
  }, 1000);
}

function parseRollExpression(arg) {
  const cleaned = (arg || "").trim().toLowerCase();
  if (!cleaned) return { count: 1, sides: 6, label: "1d6" };
  const direct = Number(cleaned);
  if (Number.isInteger(direct) && direct >= 2 && direct <= 1000) {
    return { count: 1, sides: direct, label: `1d${direct}` };
  }
  const match = cleaned.match(/^(\d{1,2})d(\d{1,4})$/i);
  if (!match) return null;
  const count = Number(match[1]);
  const sides = Number(match[2]);
  if (!Number.isInteger(count) || !Number.isInteger(sides)) return null;
  if (count < 1 || count > 30 || sides < 2 || sides > 1000) return null;
  return { count, sides, label: `${count}d${sides}` };
}

function parseTimestampArg(arg) {
  const cleaned = (arg || "").trim();
  if (!cleaned || cleaned.toLowerCase() === "now") {
    return Math.floor(Date.now() / 1000);
  }
  if (/^\d{10,13}$/.test(cleaned)) {
    const raw = Number(cleaned);
    if (!Number.isFinite(raw)) return null;
    return cleaned.length === 13 ? Math.floor(raw / 1000) : raw;
  }
  const parsed = Date.parse(cleaned);
  if (!Number.isFinite(parsed)) return null;
  return Math.floor(parsed / 1000);
}

