function validateXmppLoginCredentials({ jid, password, wsUrl, timeoutMs = 10000, onProgress = null }) {
  return new Promise((resolve) => {
    const notify = (event, payload = {}) => {
      if (typeof onProgress !== "function") return;
      try {
        onProgress({ event, ...payload });
      } catch {
        // Ignore progress callback errors.
      }
    };
    const cleanJid = normalizeXmppJid(jid);
    const cleanPass = normalizeXmppPassword(password);
    const explicitWs = normalizeXmppWsUrl(wsUrl);
    let candidates = resolveXmppWsCandidates(cleanJid, explicitWs);
    notify("start", { candidateCount: candidates.length, jid: cleanJid });
    addXmppDebugEvent("connect", "Login validation started", {
      jid: cleanJid,
      explicitWs,
      candidates
    });
    if (!cleanJid || !cleanPass || candidates.length === 0) {
      addXmppDebugEvent("error", "Login validation rejected before connect", {
        jidValid: Boolean(cleanJid),
        passwordProvided: Boolean(cleanPass),
        candidates
      });
      notify("failure", { reason: "invalid-input" });
      resolve({ ok: false, error: "XMPP login requires JID, password, and a valid WebSocket URL.", wsUrl: normalizeXmppWsUrl(wsUrl) || "" });
      return;
    }
    const tryCandidate = (candidateWs, index = 0, total = 0) => new Promise((doneAttempt) => {
      let connection = null;
      let finished = false;
      addXmppDebugEvent("connect", "Trying login endpoint", { wsUrl: candidateWs });
      notify("candidate-start", { wsUrl: candidateWs, index, total });
      const done = (result) => {
        if (finished) return;
        finished = true;
        try {
          if (connection) connection.disconnect();
        } catch {
          // Ignore cleanup errors.
        }
        doneAttempt(result);
      };
      let timeoutHandle = setTimeout(() => {
        timeoutHandle = null;
        addXmppDebugEvent("error", "Login endpoint timed out", { wsUrl: candidateWs });
        notify("candidate-timeout", { wsUrl: candidateWs, index, total });
        done({ ok: false, reason: "timeout", wsUrl: candidateWs });
      }, Math.max(2500, Math.min(10000, timeoutMs)));
      try {
        connection = new globalThis.Strophe.Connection(candidateWs, stropheConnectionOptionsForXmpp({
          jid: cleanJid,
          wsUrl: candidateWs
        }));
      } catch (error) {
        if (timeoutHandle) clearTimeout(timeoutHandle);
        addXmppDebugEvent("error", "Failed to create Strophe connection for endpoint", {
          wsUrl: candidateWs,
          error: String(error)
        });
        done({ ok: false, reason: String(error), wsUrl: candidateWs });
        return;
      }
      connection.connect(cleanJid, cleanPass, (status) => {
        const S = globalThis.Strophe.Status;
        const statusName = Object.entries(S || {}).find(([, value]) => value === status)?.[0] || String(status);
        addXmppDebugEvent("connect", "Login endpoint status", { wsUrl: candidateWs, status: statusName });
        notify("candidate-status", { wsUrl: candidateWs, index, total, status: statusName });
        if (status === S.CONNECTED) {
          if (timeoutHandle) clearTimeout(timeoutHandle);
          notify("candidate-success", { wsUrl: candidateWs, index, total });
          done({ ok: true, wsUrl: candidateWs });
          return;
        }
        if (status === S.AUTHFAIL) {
          if (timeoutHandle) clearTimeout(timeoutHandle);
          notify("candidate-authfail", { wsUrl: candidateWs, index, total });
          done({ ok: false, reason: "auth", wsUrl: candidateWs });
          return;
        }
        if (status === S.CONNFAIL || status === S.ERROR || status === S.DISCONNECTED) {
          if (timeoutHandle) clearTimeout(timeoutHandle);
          done({ ok: false, reason: "connect", wsUrl: candidateWs });
        }
      });
    });
    const runBrowserValidation = () => {
      notify("runtime-loading");
      loadXmppLibrary().then(async (ready) => {
        if (!ready || !globalThis.Strophe) {
          addXmppDebugEvent("error", "Login validation could not load runtime", { error: xmppRuntimeLastError || "" });
          notify("failure", { reason: "runtime" });
          resolve({ ok: false, error: `Failed to load XMPP runtime. ${xmppRuntimeLastError || ""}`.trim(), wsUrl: candidates[0] || "" });
          return;
        }
        try {
          const discovered = await discoverXmppWsViaHostMeta(cleanJid);
          if (discovered.length > 0) {
            const merged = [];
            const push = (value) => {
              const normalized = normalizeXmppWsUrl(value);
              if (!normalized) return;
              if (!merged.includes(normalized)) merged.push(normalized);
            };
            push(explicitWs);
            discovered.forEach((entry) => push(entry));
            candidates.forEach((entry) => push(entry));
            candidates = merged;
            addXmppDebugEvent("connect", "Merged host-meta endpoints into candidate list", { candidates });
            notify("candidates", { candidateCount: candidates.length });
          }
        } catch (error) {
          addXmppDebugEvent("runtime", "Host-meta discovery failed during login validation", { error: String(error?.message || error) });
        }
        let sawAuthFail = false;
        for (let i = 0; i < candidates.length; i += 1) {
          const candidateWs = candidates[i];
          // eslint-disable-next-line no-await-in-loop
          const attempt = await tryCandidate(candidateWs, i + 1, candidates.length);
          if (attempt.ok) {
            addXmppDebugEvent("connect", "Login validation succeeded", { wsUrl: candidateWs });
            notify("success", { wsUrl: candidateWs, via: "browser" });
            resolve({ ok: true, wsUrl: candidateWs });
            return;
          }
          if (attempt.reason === "auth") {
            sawAuthFail = true;
            break;
          }
        }
        notify("gateway-start", { mode: "fallback", candidateCount: candidates.length });
        const localGateway = await validateXmppViaLocalGateway({
          jid: cleanJid,
          password: cleanPass,
          candidates,
          timeoutMs
        });
        if (localGateway?.ok) {
          notify("success", { wsUrl: localGateway.wsUrl || candidates[0] || "", via: "local-gateway" });
          resolve({ ok: true, wsUrl: localGateway.wsUrl || candidates[0] || "", via: "local-gateway" });
          return;
        }
        const gatewayHint = localGateway && localGateway.ok === false
          ? ` Local gateway check also failed: ${localGateway.error || "unknown error"}`
          : ` Local gateway unavailable at ${XMPP_LOCAL_AUTH_GATEWAY_URL}; start it with: node scripts/xmpp-auth-gateway.mjs`;
        notify("failure", { reason: sawAuthFail ? "auth" : "connect" });
        resolve({
          ok: false,
          error: sawAuthFail
            ? `XMPP authentication failed. Tried: ${candidates.join(", ")}.${gatewayHint}`
            : `XMPP connection failed for WebSocket endpoints. Tried: ${candidates.join(", ")}.${gatewayHint}`,
          wsUrl: candidates[0] || ""
        });
      }).catch((error) => {
        addXmppDebugEvent("error", "Login validation crashed", { error: String(error) });
        notify("failure", { reason: "crash" });
        resolve({ ok: false, error: String(error), wsUrl: candidates[0] || "" });
      });
    };

    if (shouldUsePlainOnlySasl(cleanJid, explicitWs || candidates[0] || "")) {
      addXmppDebugEvent("connect", "Using local gateway-first login validation strategy", {
        jid: cleanJid,
        gatewayUrl: XMPP_LOCAL_AUTH_GATEWAY_URL
      });
      notify("gateway-start", { mode: "first", candidateCount: candidates.length });
      validateXmppViaLocalGateway({
        jid: cleanJid,
        password: cleanPass,
        candidates,
        timeoutMs
      }).then((gatewayFirst) => {
        if (gatewayFirst?.ok) {
          notify("success", { wsUrl: gatewayFirst.wsUrl || candidates[0] || "", via: "local-gateway-first" });
          resolve({ ok: true, wsUrl: gatewayFirst.wsUrl || candidates[0] || "", via: "local-gateway-first" });
          return;
        }
        addXmppDebugEvent("runtime", "Gateway-first path unavailable; falling back to browser validation", {
          hasGatewayResult: gatewayFirst !== null,
          gatewayError: gatewayFirst?.error || ""
        });
        notify("gateway-fallback", { reason: gatewayFirst?.error || "" });
        runBrowserValidation();
      }).catch((error) => {
        addXmppDebugEvent("runtime", "Gateway-first check crashed; falling back to browser validation", {
          error: String(error?.message || error)
        });
        notify("gateway-fallback", { reason: String(error?.message || error) });
        runBrowserValidation();
      });
      return;
    }

    runBrowserValidation();
  });
}

function renderXmppProviderList() {
  if (!ui.xmppProviderList) return;
  ui.xmppProviderList.innerHTML = "";
  XMPP_PROVIDER_CATALOG.forEach((provider) => {
    const row = document.createElement("div");
    row.className = "quick-switch-item";
    const title = document.createElement("strong");
    title.textContent = provider.name;
    const detail = document.createElement("small");
    const wsHint = provider.ws ? `WS: ${provider.ws}` : "WS endpoint depends on provider config.";
    detail.textContent = `${provider.notes} ${wsHint}`;
    const actions = document.createElement("div");
    actions.className = "settings-inline-actions";
    actions.style.marginTop = "0.35rem";
    const openBtn = document.createElement("button");
    openBtn.type = "button";
    openBtn.textContent = "Open Site";
    openBtn.addEventListener("click", () => {
      window.open(provider.site, "_blank", "noopener,noreferrer");
    });
    actions.appendChild(openBtn);
    const registerBtn = document.createElement("button");
    registerBtn.type = "button";
    registerBtn.textContent = "Register";
    registerBtn.addEventListener("click", () => {
      window.open(provider.register || provider.site, "_blank", "noopener,noreferrer");
    });
    actions.appendChild(registerBtn);
    if (provider.ws) {
      const useBtn = document.createElement("button");
      useBtn.type = "button";
      useBtn.textContent = "Use Server";
      useBtn.addEventListener("click", () => {
        if (ui.loginXmppServer) ui.loginXmppServer.value = provider.ws;
        ui.xmppProviderDialog?.close();
        ui.loginUsername?.focus();
      });
      actions.appendChild(useBtn);
    }
    row.append(title, detail, actions);
    ui.xmppProviderList.appendChild(row);
  });
}

function syncLoginFieldsFromSessionPrefs() {
  const prefs = getPreferences();
  if (ui.loginRememberInput) {
    ui.loginRememberInput.checked = prefs.rememberLogin === "on" && isSessionPersistenceEnabled();
  }
  if (ui.loginUsername && !ui.loginUsername.value && prefs.xmppJid) {
    ui.loginUsername.value = prefs.xmppJid;
  }
  if (ui.loginXmppServer && !ui.loginXmppServer.value && prefs.xmppWsUrl) {
    ui.loginXmppServer.value = prefs.xmppWsUrl;
  }
}

function openXmppRegisterDialog() {
  const jidSeed = normalizeXmppJid(ui.loginUsername?.value || "");
  const wsSeed = normalizeXmppWsUrl(ui.loginXmppServer?.value || "") || inferXmppWsUrlFromJid(jidSeed);
  if (ui.registerJidInput) ui.registerJidInput.value = jidSeed || "";
  if (ui.registerPasswordInput) ui.registerPasswordInput.value = "";
  if (ui.registerXmppServerInput) {
    ui.registerXmppServerInput.value = wsSeed || "";
    ui.registerXmppServerInput.dataset.autofill = wsSeed ? "1" : "0";
  }
  ui.xmppRegisterDialog?.showModal();
  requestAnimationFrame(() => ui.registerJidInput?.focus());
}

function normalizeLocalXmppProfiles(raw) {
  return normalizeLocalXmppProfilesViaModule(raw);
}

function renderLocalXmppProfileSelect() {
  if (!ui.loginLocalProfileWrap || !ui.loginLocalProfileSelect) return;
  ui.loginLocalProfileSelect.innerHTML = "";
  const defaultOption = document.createElement("option");
  defaultOption.value = "";
  defaultOption.textContent = "Select profile from .xmpp.local.json";
  ui.loginLocalProfileSelect.appendChild(defaultOption);
  if (!Array.isArray(loginLocalXmppProfiles) || loginLocalXmppProfiles.length === 0) {
    ui.loginLocalProfileWrap.hidden = true;
    return;
  }
  loginLocalXmppProfiles.forEach((profile) => {
    const option = document.createElement("option");
    option.value = profile.id;
    option.textContent = profile.label;
    ui.loginLocalProfileSelect.appendChild(option);
  });
  ui.loginLocalProfileWrap.hidden = false;
}

function applyLocalXmppProfileById(profileId) {
  if (!profileId) return false;
  const profile = loginLocalXmppProfiles.find((entry) => entry.id === profileId);
  if (!profile) return false;
  if (ui.loginUsername) ui.loginUsername.value = profile.jid;
  if (ui.loginPassword) ui.loginPassword.value = profile.password || "";
  if (ui.loginXmppServer && profile.ws) {
    ui.loginXmppServer.value = profile.ws;
    ui.loginXmppServer.dataset.autofill = "0";
  }
  return true;
}

async function loadLocalXmppProfiles() {
  const candidates = [".xmpp.local.json", "./.xmpp.local.json"];
  for (const path of candidates) {
    try {
      // Try to load local secret profiles if static server exposes dotfiles.
      // Hidden when unavailable.
      // eslint-disable-next-line no-await-in-loop
      const response = await fetch(path, { cache: "no-store" });
      if (!response.ok) continue;
      // eslint-disable-next-line no-await-in-loop
      const json = await response.json();
      const parsed = normalizeLocalXmppProfiles(json);
      if (parsed.length > 0) {
        loginLocalXmppProfiles = parsed;
        renderLocalXmppProfileSelect();
        return true;
      }
    } catch {
      // Try next fetch path variant.
    }
  }
  loginLocalXmppProfiles = [];
  renderLocalXmppProfileSelect();
  return false;
}

function createOrSwitchAccount(usernameInput, options = {}) {
  const normalized = normalizeUsername(usernameInput);
  if (!normalized) return false;

  let account = getAccountByUsername(normalized);
  if (!account) {
    const displayName = (options.displayName || usernameInput || "").toString().trim().slice(0, 32);
    account = createAccount(normalized, displayName);
    ensureAccountCosmetics(account);
    state.accounts.push(account);
  } else {
    if (!account.guildProfiles || typeof account.guildProfiles !== "object") account.guildProfiles = {};
    if (typeof account.xmppIdleSince !== "string") account.xmppIdleSince = "";
    if (typeof account.xmppLastActiveAt !== "string") account.xmppLastActiveAt = "";
    if (typeof account.customStatusEmoji !== "string") account.customStatusEmoji = "";
    if (!("customStatusExpiresAt" in account)) account.customStatusExpiresAt = null;
    if (typeof account.activityText !== "string") account.activityText = "";
    if (!Array.isArray(account.activities)) account.activities = [];
    ensureAccountCosmetics(account);
  }

  state.preferences = getPreferences();
  const requestedRelayMode = typeof options.relayMode === "string"
    ? normalizeRelayMode(options.relayMode)
    : "";
  const rememberRequested = typeof options.rememberLogin === "boolean"
    ? options.rememberLogin
    : state.preferences.rememberLogin !== "off";
  const rememberLogin = rememberRequested ? "on" : "off";
  state.preferences.rememberLogin = rememberLogin;
  if (requestedRelayMode) {
    state.preferences.relayMode = requestedRelayMode;
    if (["ws", "http", "xmpp"].includes(requestedRelayMode)) {
      state.preferences.relayAutoConnect = "on";
    }
  }
  state.currentAccountId = account.id;
  rememberAccountSession(account.id, rememberLogin === "on");
  const xmpp = options.xmpp && typeof options.xmpp === "object" ? options.xmpp : null;
  if (xmpp) {
    const jid = normalizeXmppJid(xmpp.jid || "");
    const password = normalizeXmppPassword(xmpp.password || "");
    const wsInput = normalizeXmppWsUrl(xmpp.wsUrl || "") || inferXmppWsUrlFromJid(jid);
    if (jid) state.preferences.xmppJid = jid;
    if (typeof xmpp.password === "string") state.preferences.xmppPassword = password;
    if (wsInput) state.preferences.xmppWsUrl = wsInput;
    if (jid && !state.preferences.xmppMucService) {
      const domain = xmppDomainFromJid(jid);
      if (domain) state.preferences.xmppMucService = `conference.${domain}`;
    }
    if (jid && password && (!requestedRelayMode || requestedRelayMode === "xmpp")) {
      state.preferences.relayMode = "xmpp";
      state.preferences.relayAutoConnect = "on";
    }
  }
  if (state.viewMode !== "dm" && state.viewMode !== "guild") state.viewMode = "guild";
  if (!state.activeGuildId && state.guilds[0]) {
    state.activeGuildId = state.guilds[0].id;
  }
  if (!state.activeChannelId && state.guilds[0]) {
    state.activeChannelId = getFirstOpenableChannelIdForGuild(state.guilds[0]) || state.guilds[0]?.channels?.[0]?.id || null;
  }
  ensureActiveGuildForCurrentAccount();
  ensureCurrentUserInActiveServer();
  const prefs = getPreferences();
  if (["ws", "http", "xmpp"].includes(prefs.relayMode) && prefs.relayAutoConnect === "on") connectRelaySocket({ force: true });
  return true;
}

ui.loginForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const typed = ui.loginUsername.value;
  const selectedRelayMode = "xmpp";
  const wantsXmpp = true;
  const explicitJid = typed;
  const password = ui.loginPassword?.value || "";
  const wsServer = ui.loginXmppServer?.value || "";
  const rememberLogin = ui.loginRememberInput?.checked !== false;
  const parsed = parseLoginIdentity(typed, explicitJid);
  if (!parsed.accountUsername) {
    showToast("Username must include at least one letter or number.", { tone: "error" });
    return;
  }
  if (wantsXmpp && (!parsed.xmppJid || !password)) {
    showToast("XMPP mode requires a valid JID and password.", { tone: "error" });
    return;
  }
  const submitBtn = ui.loginForm.querySelector("button[type=\"submit\"]");
  if (submitBtn instanceof HTMLButtonElement) submitBtn.disabled = true;
  let loginSucceeded = false;
  try {
    let validatedWsUrl = normalizeXmppWsUrl(wsServer);
    if (wantsXmpp) {
      beginLoginXmppProgress();
      const check = await validateXmppLoginCredentials({
        jid: parsed.xmppJid,
        password,
        wsUrl: wsServer,
        onProgress: applyLoginXmppProgressEvent
      });
      validatedWsUrl = check.wsUrl || validatedWsUrl;
      if (!check.ok) {
        applyLoginXmppProgressEvent({ event: "failure", reason: "validation" });
        showToast(check.error || "XMPP login failed.", { tone: "error" });
        return;
      }
    } else {
      resetLoginXmppProgress();
    }
    const xmppConfig = wantsXmpp
      ? {
        jid: parsed.xmppJid,
        password,
        wsUrl: validatedWsUrl || wsServer
      }
      : null;
    if (!createOrSwitchAccount(parsed.accountUsername, {
      displayName: parsed.accountDisplay,
      rememberLogin,
      relayMode: selectedRelayMode,
      xmpp: xmppConfig
    })) {
      showToast("Could not create or switch account.", { tone: "error" });
      return;
    }
    loginSucceeded = true;
    renderScreens();
    ui.loginUsername.value = "";
    if (ui.loginPassword) ui.loginPassword.value = "";
    saveState();
    safeRender("login-submit");
    closeSettingsScreen();
    requestAnimationFrame(() => {
      ui.messageInput.focus();
    });
  } finally {
    if (loginSucceeded) resetLoginXmppProgress();
    if (submitBtn instanceof HTMLButtonElement) submitBtn.disabled = false;
  }
});

ui.loginUsername?.addEventListener("input", () => {
  resetLoginXmppProgress();
  const raw = (ui.loginUsername.value || "").trim();
  if (!looksLikeCompleteJid(raw)) {
    loginXmppDiscoveryToken += 1;
    return;
  }
  if (ui.loginXmppServer && (!ui.loginXmppServer.value.trim() || ui.loginXmppServer.dataset.autofill === "1")) {
    const inferred = inferXmppWsUrlFromJid(raw);
    if (inferred) {
      ui.loginXmppServer.value = inferred;
      ui.loginXmppServer.dataset.autofill = "1";
    }
  }
  void maybeDiscoverLoginXmppWsUrl(raw);
});

ui.loginLocalProfileSelect?.addEventListener("change", () => {
  const selectedId = (ui.loginLocalProfileSelect?.value || "").toString();
  if (!selectedId) return;
  const applied = applyLocalXmppProfileById(selectedId);
  if (!applied) return;
  ui.loginUsername?.focus();
});

ui.loginXmppServer?.addEventListener("input", () => {
  resetLoginXmppProgress();
  if (!ui.loginXmppServer) return;
  const normalized = normalizeXmppWsUrl(ui.loginXmppServer.value || "");
  const inferred = inferXmppWsUrlFromJid(ui.loginUsername?.value || "");
  ui.loginXmppServer.dataset.autofill = normalized && inferred && normalized === inferred ? "1" : "0";
});

ui.loginPassword?.addEventListener("input", () => {
  resetLoginXmppProgress();
});

ui.loginProvidersBtn?.addEventListener("click", () => {
  renderXmppProviderList();
  ui.xmppProviderDialog?.showModal();
});

ui.loginRegisterBtn?.addEventListener("click", () => {
  openXmppRegisterDialog();
});

ui.loginXmppConsoleBtn?.addEventListener("click", () => {
  openXmppConsoleDialog();
});

ui.xmppProviderCloseBtn?.addEventListener("click", () => {
  ui.xmppProviderDialog?.close();
});

ui.registerOpenProviderBtn?.addEventListener("click", () => {
  renderXmppProviderList();
  ui.xmppProviderDialog?.showModal();
});

ui.registerCancelBtn?.addEventListener("click", () => {
  ui.xmppRegisterDialog?.close();
});

ui.registerJidInput?.addEventListener("input", () => {
  const raw = normalizeXmppJid(ui.registerJidInput?.value || "");
  if (!looksLikeCompleteJid(raw)) return;
  if (!ui.registerXmppServerInput) return;
  if (!ui.registerXmppServerInput.value.trim() || ui.registerXmppServerInput.dataset.autofill === "1") {
    const inferred = inferXmppWsUrlFromJid(raw);
    if (inferred) {
      ui.registerXmppServerInput.value = inferred;
      ui.registerXmppServerInput.dataset.autofill = "1";
    }
  }
});

ui.registerXmppServerInput?.addEventListener("input", () => {
  if (!ui.registerXmppServerInput) return;
  const normalized = normalizeXmppWsUrl(ui.registerXmppServerInput.value || "");
  const inferred = inferXmppWsUrlFromJid(ui.registerJidInput?.value || "");
  ui.registerXmppServerInput.dataset.autofill = normalized && inferred && normalized === inferred ? "1" : "0";
});

ui.xmppRegisterForm?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const jid = normalizeXmppJid(ui.registerJidInput?.value || "");
  const password = normalizeXmppPassword(ui.registerPasswordInput?.value || "");
  const wsUrl = normalizeXmppWsUrl(ui.registerXmppServerInput?.value || "");
  if (!looksLikeCompleteJid(jid)) {
    showToast("Enter a valid XMPP JID for registration.", { tone: "error" });
    return;
  }
  if (!password) {
    showToast("Password is required for registration.", { tone: "error" });
    return;
  }
  if (ui.registerSubmitBtn instanceof HTMLButtonElement) ui.registerSubmitBtn.disabled = true;
  try {
    const result = await registerXmppViaLocalGateway({
      jid,
      password,
      wsUrl
    });
    if (!result.ok) {
      addXmppDebugEvent("error", "In-client registration failed", {
        jid,
        wsUrl: result.wsUrl || wsUrl || "",
        error: result.error || "",
        failures: result.failures || []
      });
      showToast(result.error || "Registration failed.", { tone: "error", duration: 3400 });
      return;
    }
    addXmppDebugEvent("connect", "In-client registration succeeded", {
      jid,
      wsUrl: result.wsUrl || wsUrl || ""
    });
    if (ui.loginUsername) ui.loginUsername.value = jid;
    if (ui.loginPassword) ui.loginPassword.value = password;
    if (ui.loginXmppServer) {
      ui.loginXmppServer.value = result.wsUrl || wsUrl || inferXmppWsUrlFromJid(jid);
      ui.loginXmppServer.dataset.autofill = "1";
    }
    ui.xmppRegisterDialog?.close();
    showToast("Account registered. Log in with the prefilled credentials.");
  } finally {
    if (ui.registerSubmitBtn instanceof HTMLButtonElement) ui.registerSubmitBtn.disabled = false;
  }
});

ui.messageForm.addEventListener("submit", (event) => {
  event.preventDefault();
  publishRelayTypingState(false, { force: true });
  const conversation = getActiveConversation();
  const text = trimTextForConversation((ui.messageInput.value || "").trim(), conversation);
  const account = getCurrentAccount();
  if (!conversation || !account || (!text && composerPendingAttachments.length === 0)) return;
  if (conversation.type === "dm" && text.startsWith("/")) {
    const [rawCommand, ...rawRest] = text.slice(1).split(" ");
    const dmCommand = rawCommand.toLowerCase();
    const dmArg = rawRest.join(" ").trim();
    if ([
      "serverinfo",
      "serverroles",
      "members",
      "membercount",
      "channels",
      "channeltypes",
      "mentions",
      "nextmention",
      "prevmention",
      "markmentionsread",
      "copyguildid",
      "copyguildname",
      "copychannelname"
    ].includes(dmCommand)) {
      showToast("This command only works in guild channels.", { tone: "error" });
      return;
    }
    if (dmCommand === "closedm") {
      const closingId = state.activeDmId;
      if (closingId) {
        state.dmThreads = state.dmThreads.filter((entry) => entry.id !== closingId);
        state.activeDmId = null;
        ui.messageInput.value = "";
        resizeComposerInput();
        saveState();
        render();
      }
      return;
    }
    if (dmCommand === "newdm") {
      const rawIdentity = (dmArg || "").toString().trim();
      if (!rawIdentity) {
        showToast("Usage: /newdm <username-or-jid>", { tone: "error" });
        return;
      }
      const target = openDmByIdentity(rawIdentity);
      if (!target) {
        showToast("Could not open DM (check username/JID).", { tone: "error" });
        return;
      }
      ui.messageInput.value = "";
      resizeComposerInput();
      return;
    }
    if (dmCommand === "markdmread") {
      if (!markDmRead(conversation.thread, account.id)) return;
      saveState();
      render();
      return;
    }
    if (dmCommand === "markallread") {
      if (!markAllReadForAccount(account.id)) return;
      saveState();
      render();
      return;
    }
    if (dmCommand === "markdmmentionsread") {
      let changed = 0;
      state.dmThreads.forEach((thread) => {
        if (!Array.isArray(thread.participantIds) || !thread.participantIds.includes(account.id)) return;
        const stats = getDmUnreadStats(thread, account);
        if (stats.mentions <= 0) return;
        if (markDmRead(thread, account.id)) changed += 1;
      });
      if (changed <= 0) {
        showToast("No DM threads with unread mentions.", { tone: "error" });
        return;
      }
      saveState();
      render();
      showToast(`Marked ${changed} DM thread${changed === 1 ? "" : "s"} with mentions as read.`);
      return;
    }
    if (dmCommand === "listdms") {
      const threads = getSortedDmThreadsForAccount(account);
      if (threads.length === 0) {
        showToast("No DM threads yet.", { tone: "error" });
        return;
      }
      const labels = threads
        .slice(0, 5)
        .map((thread) => {
          const peer = dmPeerAccountForThread(thread, account.id);
          return peer ? dmPrimaryLabelForAccount(peer) : "(unknown DM)";
        })
        .join(", ");
      showToast(`DMs (${threads.length}): ${labels}${threads.length > 5 ? " ..." : ""}`);
      return;
    }
    if (dmCommand === "dmnext") {
      if (!cycleActiveDmThread(1)) showToast("No other DM threads.", { tone: "error" });
      return;
    }
    if (dmCommand === "dmprev") {
      if (!cycleActiveDmThread(-1)) showToast("No other DM threads.", { tone: "error" });
      return;
    }
    if (dmCommand === "copyid") {
      void copyText(conversation.thread.id).then((ok) => {
        showToast(ok ? "DM ID copied." : "Failed to copy DM ID.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "copylink") {
      const link = `${window.location.href.split("#")[0]}#msg=${conversation.thread.id}:`;
      void copyText(link).then((ok) => {
        showToast(ok ? "DM link copied." : "Failed to copy DM link.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "copyaccountid") {
      void copyText(account.id || "").then((ok) => {
        showToast(ok ? "Account ID copied." : "Failed to copy account ID.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "copyjid") {
      const jid = accountBareXmppJid(account);
      if (!jid) {
        showToast("No XMPP JID set for this account.", { tone: "error" });
        return;
      }
      void copyText(jid).then((ok) => {
        showToast(ok ? "XMPP JID copied." : "Failed to copy XMPP JID.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "copypresence") {
      const presence = normalizePresence(account.presence || "online");
      void copyText(presence).then((ok) => {
        showToast(ok ? "Presence copied." : "Failed to copy presence.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "copydisplayname") {
      const display = displayNameForAccount(account, null);
      void copyText(display).then((ok) => {
        showToast(ok ? "Display name copied." : "Failed to copy display name.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "copyref") {
      const ref = activeConversationReferenceText();
      if (!ref) {
        showToast("No active DM reference to copy.", { tone: "error" });
        return;
      }
      void copyText(ref).then((ok) => {
        showToast(ok ? "Conversation reference copied." : "Failed to copy conversation reference.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "copyroom") {
      const room = relayRoomForActiveConversation();
      if (!room) {
        showToast("No relay room token available.", { tone: "error" });
        return;
      }
      void copyText(room).then((ok) => {
        showToast(ok ? "Relay room token copied." : "Failed to copy relay room token.", { tone: ok ? "info" : "error" });
      });
      return;
    }
    if (dmCommand === "call" || dmCommand === "callscreen" || dmCommand === "callweb") {
      const raw = (dmArg || "").trim();
      const parts = raw ? raw.split(/\s+/) : [];
      const first = (parts[0] || "").toLowerCase();
      const explicitAction = ["join", "start", "screen", "screenshare", "share", "link", "copy"].includes(first) ? first : "";
      const action = dmCommand === "callscreen" ? "screen" : (explicitAction || "join");
      const roomOverride = dmCommand === "callscreen"
        ? raw
        : (explicitAction ? parts.slice(1).join(" ") : raw);
      if (action === "link" || action === "copy") {
        const url = conversationCallUrl(conversation, { roomOverride });
        if (!url) {
          showToast("Could not resolve call room URL.", { tone: "error" });
          return;
        }
        if (action === "copy") {
          void copyText(url).then((ok) => showToast(ok ? "Call link copied." : "Failed to copy call link.", { tone: ok ? "info" : "error" }));
        } else {
          showToast(url, { duration: 2600 });
        }
        return;
      }
      launchConversationCall({
        screenShare: ["screen", "screenshare", "share"].includes(action),
        roomOverride,
        autoPost: true,
        allowNative: dmCommand !== "callweb"
      });
      return;
    }
    if (dmCommand === "callxmpp") {
      const raw = (dmArg || "").trim();
      const [subRaw, tokenRaw] = raw.split(/\s+/, 2);
      const sub = (subRaw || "").toLowerCase();
      const token = (tokenRaw || "").trim().toLowerCase();
      if (sub === "status") {
        xmppAssessConversationCallInterop(conversation, { force: true }).then((interop) => {
          const snapshots = xmppCallDebugSnapshotForConversation(conversation, getCurrentAccount());
          const snapshotText = snapshots.length > 0
            ? ` · ${xmppFormatCallSnapshotLine(snapshots[0])}${snapshots.length > 1 ? " …" : ""}`
            : "";
          if (interop.ready) {
            showToast(`XMPP call interop ready (${interop.chosenTarget || "target"}).${snapshotText}`);
            return;
          }
          const first = interop.details[0]?.evalResult || {};
          const missing = [
            first.hasCore ? "" : "jingle",
            first.hasMedia ? "" : "rtp-media",
            first.hasTransport ? "" : "ice-udp",
            first.hasInvite ? "" : "invite"
          ].filter(Boolean);
          showToast(`XMPP call interop not ready${missing.length > 0 ? ` (${missing.join(", ")})` : ""}.${snapshotText}`, { tone: "error", duration: 3000 });
        }).catch(() => {
          showToast("XMPP call interop check failed.", { tone: "error" });
        });
        return;
      }
      if (sub === "accept" || sub === "reject" || sub === "cancel" || sub === "ring" || sub === "transport" || sub === "end") {
        const peerBare = xmppPeerJidForConversation(conversation, getCurrentAccount());
        if (!peerBare) {
          showToast("XMPP call controls currently work in DMs.", { tone: "error" });
          return;
        }
        const targetId = token
          ? ([...xmppCallSessionById.keys()].find((id) => id.toLowerCase().startsWith(token)) || "")
          : latestXmppCallSessionIdForPeer(peerBare, (sub === "cancel" || sub === "end") ? "outgoing" : "incoming");
        if (!targetId) {
          showToast("No matching XMPP call session.", { tone: "error" });
          return;
        }
        const session = xmppCallSessionById.get(targetId) || null;
        const peerTarget = xmppResolveSessionPeerJid(session, peerBare, { preferFull: true }) || peerBare;
        if (xmppSessionIsMujiCallInvite(session)) {
          if (sub === "ring" || sub === "transport") {
            showToast("Muji room invites do not use /callxmpp ring or /callxmpp transport.", { tone: "error" });
            return;
          }
          if (sub === "accept") {
            void acceptIncomingXmppCall(targetId).then((ok) => {
              showToast(ok
                ? `Accepted Muji room call invite (${targetId.slice(0, 8)}).`
                : "Failed to accept Muji room call invite.", { tone: ok ? "info" : "error" });
            });
            return;
          }
          const sentMuji = declineIncomingXmppCall(targetId);
          showToast(sentMuji
            ? `Sent Muji ${sub === "end" ? "leave" : "reject"} (${targetId.slice(0, 8)}).`
            : "Failed to send Muji call action.", { tone: sentMuji ? "info" : "error" });
          return;
        }
        const isJinglePhase = (session?.state || "").includes("session");
        const action = sub === "accept" ? "proceed" : (sub === "reject" ? "reject" : "retract");
        let sent = false;
        if (sub === "accept" && isJinglePhase) {
          void (async () => {
            const ok = await xmppSendJingleSessionAccept(peerTarget, targetId, {
              media: Array.isArray(session?.media) && session.media.length > 0 ? session.media : XMPP_CALL_DEFAULT_MEDIA,
              screenShare: Boolean(session?.screenShare)
            });
            if (!ok) {
              showToast("Failed to send XMPP call action.", { tone: "error" });
              return;
            }
            showToast(`Sent XMPP session-accept (${targetId.slice(0, 8)}).`);
            if (addSystemDmMessageByPeerJid(peerBare, `Sent XMPP session-accept (${targetId.slice(0, 8)}).`)) {
              refreshDmUiForPeerJid(peerBare);
            }
            openNativeXmppCallSurface(targetId);
          })();
          return;
        } else if (sub === "end") {
          sent = xmppSendJingleSessionTerminate(peerTarget, targetId, {
            reason: "success",
            text: "Ended by local user"
          });
        } else if (sub === "ring") {
          sent = isJinglePhase
            ? xmppSendJingleSessionInfo(peerTarget, targetId, { info: "ringing" })
            : xmppSendJingleMessageAction(peerTarget, "ringing", { sessionId: targetId });
        } else if (sub === "transport") {
          const localTransport = session?.localTransport && typeof session.localTransport === "object"
            ? session.localTransport
            : xmppBuildJingleTransportCreds();
          if (session) session.localTransport = localTransport;
          sent = xmppQueueTransportInfoGatherAndSend(peerTarget, targetId, { force: true });
        } else {
          sent = xmppSendJingleMessageAction(peerTarget, action, { sessionId: targetId });
        }
        if (!sent) {
          showToast("Failed to send XMPP call action.", { tone: "error" });
          return;
        }
        const sentLabel = sub === "accept" && isJinglePhase
          ? "session-accept"
          : (sub === "end"
            ? "session-terminate"
            : (sub === "ring"
              ? (isJinglePhase ? "session-info/ringing" : "ringing")
              : (sub === "transport" ? "transport-info (queued)" : action)));
        showToast(`Sent XMPP ${sentLabel} (${targetId.slice(0, 8)}).`);
        if (addSystemDmMessageByPeerJid(peerBare, `Sent XMPP ${sentLabel} (${targetId.slice(0, 8)}).`)) {
          refreshDmUiForPeerJid(peerBare);
        }
        if (sub === "accept") {
          if (isJinglePhase) {
            openNativeXmppCallSurface(targetId);
          } else {
            launchConversationCall({ screenShare: false, autoPost: true });
          }
        }
        if (["reject", "cancel", "end"].includes(sub) || (sub === "accept" && !isJinglePhase)) {
          forgetXmppCallSession(targetId);
        }
        return;
      }
      const lowerRaw = raw.toLowerCase();
      const screenShare = lowerRaw === "screen" || lowerRaw === "screenshare" || lowerRaw === "share";
      launchNativeXmppConversationCall({ screenShare });
      return;
    }
    if (dmCommand === "whiteboard") {
      const raw = (dmArg || "").trim();
      const parts = raw ? raw.split(/\s+/) : [];
      const first = (parts[0] || "").toLowerCase();
      const explicitAction = ["open", "join", "copy", "link", "post", "fallback"].includes(first) ? first : "";
      const action = explicitAction || "open";
      const roomOverride = explicitAction ? parts.slice(1).join(" ") : raw;
      if (action === "copy" || action === "link") {
        const url = conversationWhiteboardUrl(conversation, roomOverride);
        if (!url) {
          showToast("Could not resolve whiteboard room URL.", { tone: "error" });
          return;
        }
        if (action === "copy") {
          void copyText(url).then((ok) => showToast(ok ? "Whiteboard link copied." : "Failed to copy whiteboard link.", { tone: ok ? "info" : "error" }));
        } else {
          showToast(url, { duration: 2600 });
        }
        return;
      }
      const wantsPost = action === "post" || action === "fallback";
      launchConversationWhiteboard({ roomOverride, autoPost: wantsPost });
      return;
    }
    if (dmCommand === "joinxmpp" || dmCommand === "joinmuc") {
      const result = handleJoinXmppCommand(dmArg, account, { focus: true });
      showToast(result.message, { tone: result.ok ? "info" : "error", duration: result.ok ? 2200 : 3200 });
      return;
    }
    if (dmCommand === "leavexmpp" || dmCommand === "leavemuc") {
      const result = handleLeaveXmppCommand(dmArg, account);
      showToast(result.message, { tone: result.ok ? "info" : "error", duration: result.ok ? 2200 : 3200 });
      if (result.ok) {
        renderServers();
        renderChannels();
      }
      return;
    }
    if (dmCommand === "invitexmpp" || dmCommand === "invitemuc") {
      const peerBare = xmppBareJid(xmppPeerJidForDmThread(conversation.thread, account));
      if (!peerBare) {
        showToast("Active DM is not XMPP-backed.", { tone: "error" });
        return;
      }
      const inviteArgs = parseXmppDirectMucInviteCommandArg(dmArg);
      if (!inviteArgs.roomJid) {
        showToast("Usage: /invitexmpp <room@conference.example.org> [| reason [| password [| continue [| thread-id]]]]", { tone: "error" });
        return;
      }
      const sent = xmppSendDirectMucInvite(peerBare, inviteArgs.roomJid, {
        reason: inviteArgs.reason,
        password: inviteArgs.password,
        thread: inviteArgs.thread || (conversation.thread?.id || "").toString().trim().slice(0, 120),
        continueThread: Boolean(inviteArgs.continueThread),
        preferFull: true
      });
      if (!sent.ok) {
        const reason = sent.reason === "xmpp-offline"
          ? "XMPP relay is not connected."
          : (sent.reason === "invalid-room"
            ? "Invalid XMPP room JID."
            : "Could not send XMPP room invite.");
        showToast(reason, { tone: "error" });
        return;
      }
      if (addSystemDmMessageByPeerJid(peerBare, `Sent XMPP room invite: ${inviteArgs.roomJid}${inviteArgs.reason ? ` (${inviteArgs.reason})` : ""}.`)) {
        refreshDmUiForPeerJid(peerBare);
      }
      showToast("XMPP room invite sent.");
      return;
    }
    if (dmCommand === "spacesxmpp" || dmCommand === "xmppspaces") {
      const raw = (dmArg || "").trim();
      const [subRaw, ...restParts] = raw.split(/\s+/).filter(Boolean);
      const sub = (subRaw || "list").toLowerCase();
      const dmConversation = { type: "dm", id: conversation.thread?.id || "", thread: conversation.thread };
      if (sub === "join") {
        const result = handleJoinXmppCommand(restParts.join(" "), account, { focus: true });
        if (addSystemMessageToConversation(dmConversation, result.message)) {
          refreshConversationUi(dmConversation);
        }
        showToast(result.message, { tone: result.ok ? "info" : "error", duration: result.ok ? 2200 : 3200 });
        return;
      }
      if (sub === "open") {
        const opened = focusXmppSpacesGuild(account, getPreferences());
        showToast(opened ? "Opened XMPP Spaces." : "Could not open XMPP Spaces.", { tone: opened ? "info" : "error" });
        return;
      }
      if (sub === "sync" || sub === "discover") {
        showToast(`Syncing XMPP Spaces (${sub === "discover" ? "forced discovery" : "cached discovery"})...`, { duration: 2400 });
        void syncXmppSpacesNow({
          account,
          prefs: getPreferences(),
          forceDiscovery: sub === "discover"
        }).then((result) => {
          showToast(result.message, { tone: result.ok ? "info" : "error", duration: result.ok ? 3200 : 3600 });
          if (addSystemMessageToConversation(dmConversation, result.message)) {
            refreshConversationUi(dmConversation);
          }
          if (result.ok) {
            renderServers();
            renderChannels();
          }
        }).catch(() => {
          showToast("Failed to sync XMPP Spaces.", { tone: "error" });
        });
        return;
      }
      if (sub === "list" || sub === "status") {
        const lines = xmppSpacesSummaryLines({ limit: 20, prefs: getPreferences() });
        const summaryText = lines.length > 0
          ? `XMPP Spaces rooms:\n${lines.join("\n")}`
          : "No XMPP Spaces rooms mapped yet. Use /spacesxmpp sync or /joinxmpp <room@conference.domain>.";
        if (addSystemMessageToConversation(dmConversation, summaryText)) {
          refreshConversationUi(dmConversation);
        }
        showToast(lines.length > 0 ? `XMPP Spaces: ${lines.length} room(s).` : "No XMPP Spaces rooms mapped.", {
          tone: lines.length > 0 ? "info" : "error",
          duration: 2600
        });
        return;
      }
      showToast("Usage: /spacesxmpp [list|open|sync|discover|join <room@conference.domain>]", {
        tone: "error",
        duration: 3200
      });
      return;
    }
    if (dmCommand === "focus") {
      if (!dmArg || dmArg.toLowerCase() === "search") {
        ui.dmSearchInput?.focus();
        ui.dmSearchInput?.select?.();
      } else {
        ui.messageInput.focus();
      }
      return;
    }
    if (dmCommand === "devtools") {
      if (!requestDevtoolsToggle()) {
        showToast("DevTools toggle is only available in the Electron app.", { tone: "error" });
      }
      return;
    }
    if (dmCommand === "xmppconsole" || dmCommand === "xmppinspect") {
      const scoped = applyXmppConsoleScopeArg(dmArg, { type: "dm", thread: conversation.thread }, getCurrentAccount());
      openXmppConsoleDialog();
      showToast(scoped.message, { tone: scoped.ok ? "info" : "error" });
      return;
    }
    if (dmCommand === "relay") {
      state.preferences = getPreferences();
      const [subRaw, ...restRelay] = dmArg.split(" ");
      const sub = (subRaw || "status").toLowerCase();
      const payload = restRelay.join(" ").trim();
      if (sub === "status") {
        const adapter = getTransportAdapter(state.preferences.relayMode);
        const relayUrl = state.preferences.relayMode === "xmpp"
          ? (resolveXmppServiceUrl(state.preferences) || "(unset)")
          : state.preferences.relayUrl;
        showToast(
          `Relay: ${relayStatusText()} · ${state.preferences.relayMode}/${adapter.label} · ${relayUrl} · auto:${state.preferences.relayAutoConnect}`
        );
        return;
      }
      if (sub === "connect") {
        if (/^xmpp$/i.test(payload)) state.preferences.relayMode = "xmpp";
        else state.preferences.relayMode = payload.toLowerCase().startsWith("http") ? "http" : "ws";
        if (payload) state.preferences.relayUrl = normalizeRelayUrl(payload);
        saveState();
        connectRelaySocket({ force: true });
        showToast("Relay connect requested.");
        return;
      }
      if (sub === "reconnect") {
        disconnectRelaySocket({ manual: false });
        connectRelaySocket({ force: true });
        showToast("Relay reconnect requested.");
        return;
      }
      if (sub === "disconnect") {
        disconnectRelaySocket({ manual: true });
        showToast("Relay disconnected.");
        return;
      }
      if (sub === "mode") {
        state.preferences.relayMode = normalizeRelayMode(payload);
        saveState();
        if (["ws", "http", "xmpp"].includes(state.preferences.relayMode)) connectRelaySocket({ force: true });
        else disconnectRelaySocket({ manual: true });
        showToast(`Relay mode: ${state.preferences.relayMode}`);
        return;
      }
      if (sub === "url") {
        if (!payload) {
          showToast(`Relay URL: ${state.preferences.relayUrl}`);
          return;
        }
        state.preferences.relayUrl = normalizeRelayUrl(payload);
        saveState();
        showToast(`Relay URL set: ${state.preferences.relayUrl}`);
        return;
      }
      if (sub === "room") {
        state.preferences.relayRoom = !payload || payload.toLowerCase() === "clear" ? "" : normalizeRelayRoom(payload);
        saveState();
        syncRelayRoomForActiveConversation();
        showToast(state.preferences.relayRoom ? `Relay room: ${state.preferences.relayRoom}` : "Relay room override cleared.");
        return;
      }
      if (sub === "roomsync") {
        syncRelayRoomForActiveConversation();
        showToast(`Relay room synced: ${relayRoomForActiveConversation()}`);
        return;
      }
      if (sub === "autoconnect") {
        const value = payload.toLowerCase();
        if (!value || value === "status") {
          showToast(`Relay auto-connect: ${state.preferences.relayAutoConnect}`);
          return;
        }
        if (!["on", "off"].includes(value)) {
          showToast("Usage: /relay autoconnect <on|off|status>", { tone: "error" });
          return;
        }
        state.preferences.relayAutoConnect = value;
        saveState();
        if (value === "on" && ["ws", "http", "xmpp"].includes(state.preferences.relayMode)) {
          connectRelaySocket({ force: true });
        } else if (value === "off") {
          clearRelayReconnectTimer();
        }
        showToast(`Relay auto-connect set to: ${value}`);
        return;
      }
      if (sub === "ping") {
        const prefs = getPreferences();
        if (prefs.relayMode === "xmpp") {
          if (!xmppConnection || relayStatus !== "connected") {
            showToast("XMPP relay is not connected.", { tone: "error" });
            return;
          }
          const sent = sendXmppPing(xmppConnection);
          showToast(sent ? "Sent XMPP ping request." : "Could not send XMPP ping request.", { tone: sent ? "info" : "error" });
          return;
        }
        if (!["ws", "http"].includes(prefs.relayMode)) {
          showToast("Relay ping is available only for ws/http/xmpp modes.", { tone: "error" });
          return;
        }
        const startedAt = Date.now();
        const healthUrl = relayHealthUrlFromRelayUrl(prefs.relayUrl);
        if (!healthUrl) {
          showToast("Relay URL is invalid.", { tone: "error" });
          return;
        }
        fetch(healthUrl, { cache: "no-store" })
          .then(async (response) => {
            const elapsed = Date.now() - startedAt;
            let body = "";
            try {
              body = (await response.text()).replace(/\s+/g, " ").trim().slice(0, 200);
            } catch {
              body = "";
            }
            const prefix = response.ok ? "Relay ping ok" : "Relay ping failed";
            showToast(`${prefix} (${elapsed}ms) · HTTP ${response.status}${body ? ` · ${body}` : ""}`, {
              tone: response.ok ? "info" : "error",
              duration: 2600
            });
          })
          .catch((error) => {
            showToast(`Relay ping failed: ${String(error?.message || error)}`, { tone: "error" });
          });
        return;
      }
      showToast(
        "Usage: /relay [status|connect|disconnect|reconnect|mode <local|http|ws|xmpp|off>|url|room|roomsync|autoconnect <on|off|status>|ping]",
        { tone: "error" }
      );
      return;
    }
    if (dmCommand === "quests") {
      showToast(formatQuestSummaryText(account.id));
      return;
    }
    if (dmCommand === "questprogress") {
      showToast(formatQuestSummaryText(account.id));
      return;
    }
    if (dmCommand === "questbadges") {
      const badges = resolveQuestBadgesForAccount(account.id);
      showToast(badges.length > 0 ? `Badges: ${badges.join(", ")}` : "No badges unlocked yet.");
      return;
    }
    if (dmCommand === "profilefx") {
      if (!dmArg) {
        showToast(`Current profile effect: ${accountProfileEffect(account)}`);
        return;
      }
      if (!["none", "aurora", "flame", "ocean"].includes(dmArg.toLowerCase())) {
        showToast("Usage: /profilefx <none|aurora|flame|ocean>", { tone: "error" });
        return;
      }
      account.profileEffect = normalizeProfileEffect(dmArg);
      saveState();
      render();
      showToast(`Profile effect set to: ${account.profileEffect}`);
      return;
    }
    if (dmCommand === "guildtag") {
      const rawTag = dmArg.trim();
      if (!rawTag) {
        showToast(`Current guild tag: ${accountGuildTag(account) || "(none)"}`);
        return;
      }
      if (rawTag.toLowerCase() === "clear") {
        account.guildTag = "";
        account.guildTagGuildId = "";
        saveState();
        render();
        showToast("Guild tag cleared.");
        return;
      }
      account.guildTag = rawTag.slice(0, 8).toUpperCase();
      const activeGuild = getActiveGuild();
      account.guildTagGuildId = activeGuild && activeGuild.memberIds.includes(account.id) ? activeGuild.id : "";
      saveState();
      render();
      showToast(`Guild tag set to: ${account.guildTag}`);
      return;
    }
    if (dmCommand === "decor") {
      const rawDecor = dmArg.trim();
      if (!rawDecor) {
        showToast(`Current avatar decoration: ${accountDecorationEmoji(account) || "(none)"}`);
        return;
      }
      if (rawDecor.toLowerCase() === "clear") {
        account.avatarDecoration = "";
        saveState();
        render();
        showToast("Avatar decoration cleared.");
        return;
      }
      account.avatarDecoration = rawDecor.slice(0, 4);
      saveState();
      render();
      showToast(`Avatar decoration set to: ${account.avatarDecoration}`);
      return;
    }
    if (dmCommand === "nameplate") {
      const rawNameplate = dmArg.trim();
      if (!rawNameplate) {
        showToast(`Current nameplate: ${accountNameplateSvg(account) || "(none)"}`);
        return;
      }
      if (rawNameplate.toLowerCase() === "clear") {
        account.profileNameplateSvg = "";
        saveState();
        render();
        showToast("Nameplate cleared.");
        return;
      }
      if (!/^https?:\/\//i.test(rawNameplate) && !/^data:image\/svg\+xml/i.test(rawNameplate)) {
        showToast("Usage: /nameplate <https://...|data:image/svg+xml...|clear>", { tone: "error" });
        return;
      }
      account.profileNameplateSvg = rawNameplate.slice(0, 280);
      saveState();
      render();
      showToast("Nameplate updated.");
      return;
    }
    if (dmCommand === "whoami") {
      showToast(formatIdentitySummaryText(account, null));
      return;
    }
    if (dmCommand === "whois") {
      const query = (dmArg || "").trim();
      if (!query) {
        showToast("Usage: /whois <username-or-jid>", { tone: "error" });
        return;
      }
      const target = resolveAccountByIdentityToken(query, { includeSelf: true });
      if (!target) {
        showToast("No matching account found.", { tone: "error" });
        return;
      }
      showToast(formatIdentitySummaryText(target, null), { duration: 2600 });
      return;
    }
    if (["online", "idle", "dnd", "invisible", "away"].includes(dmCommand)) {
      const nextPresence = dmCommand === "away" ? "idle" : dmCommand;
      setCurrentAccountPresence(nextPresence, { persist: true, rerender: true, announceXmpp: true });
      showToast(`Presence changed to ${presenceLabel(nextPresence)}.`);
      return;
    }
    if (dmCommand === "nick") {
      const rawNick = (dmArg || "").trim();
      if (!rawNick) {
        showToast(`Display name: ${displayNameForAccount(account, null)}`);
        return;
      }
      if (rawNick.toLowerCase() === "clear") {
        account.displayName = account.username || account.displayName;
        saveState();
        render();
        showToast(`Display name reset to ${account.displayName}.`);
        return;
      }
      account.displayName = rawNick.slice(0, 32);
      saveState();
      render();
      showToast(`Display name changed to ${account.displayName}.`);
      return;
    }
    if (dmCommand === "status") {
      const statusInput = (dmArg || "").trim();
      account.customStatus = (!statusInput || statusInput.toLowerCase() === "clear")
        ? ""
        : statusInput.slice(0, 80);
      saveState();
      render();
      showToast(account.customStatus ? `Status set to: ${account.customStatus}` : "Status cleared.");
      return;
    }
    if (dmCommand === "presence") {
      const token = (dmArg || "").trim().toLowerCase();
      if (!token || token === "status") {
        showToast(`Presence: ${presenceLabel(account.presence || "online")}.`);
        return;
      }
      if (!["online", "idle", "dnd", "invisible"].includes(token)) {
        showToast("Usage: /presence <online|idle|dnd|invisible|status>", { tone: "error" });
        return;
      }
      setCurrentAccountPresence(token, { persist: true, rerender: true, announceXmpp: true });
      showToast(`Presence changed to ${presenceLabel(token)}.`);
      return;
    }
    if (dmCommand === "profilecard") {
      conversation.thread.messages.push({
        id: createId(),
        userId: account.id,
        authorName: "",
        text: `🪪 ${formatIdentitySummaryText(account, null)}`,
        ts: new Date().toISOString(),
        reactions: [],
        attachments: []
      });
      saveState();
      renderMessages();
      return;
    }
    if (dmCommand === "shop") {
      openCosmeticsDialog(dmArg);
      return;
    }
    if (dmCommand === "inventory") {
      showToast(formatCosmeticInventorySummary(account.id));
      return;
    }
    if (dmCommand === "find") {
      openFindDialogWithQuery(dmArg);
      return;
    }
    if (dmCommand === "findlinks") {
      openFindDialogWithQuery("has:link");
      return;
    }
    if (dmCommand === "findfrom") {
      const sender = (dmArg || "").trim();
      if (!sender) {
        showToast("Usage: /findfrom <username>", { tone: "error" });
        return;
      }
      openFindDialogWithQuery(`from:${sender}`);
      return;
    }
    if (dmCommand === "findtoday") {
      const today = new Date();
      const yyyy = today.getFullYear();
      const mm = String(today.getMonth() + 1).padStart(2, "0");
      const dd = String(today.getDate()).padStart(2, "0");
      openFindDialogWithQuery(`after:${yyyy}-${mm}-${dd}`);
      return;
    }
    if (dmCommand === "findnext") {
      if (!findQuery.trim()) {
        openFindDialog();
        return;
      }
      moveFindSelection(1);
      return;
    }
    if (dmCommand === "findprev") {
      if (!findQuery.trim()) {
        openFindDialog();
        return;
      }
      moveFindSelection(-1);
      return;
    }
    if (dmCommand === "markunread") {
      const bucket = conversation.thread?.messages || [];
      if (bucket.length === 0) {
        showToast("No messages to mark unread from.", { tone: "error" });
        return;
      }
      const needle = dmArg.trim().toLowerCase();
      const targetMessage = !needle || needle === "last"
        ? bucket[bucket.length - 1]
        : bucket.find((entry) => (entry.id || "").toLowerCase().startsWith(needle));
      if (!targetMessage) {
        showToast("Usage: /markunread [message-id-prefix|last]", { tone: "error" });
        return;
      }
      if (!markConversationUnreadFromMessage(conversation, targetMessage.id, account.id)) return;
      saveState();
      render();
      showToast(`Marked unread from ${targetMessage.id.slice(0, 8)}.`);
      return;
    }
    if (dmCommand === "schedule") {
      const splitAt = dmArg.indexOf("|");
      if (splitAt < 0) {
        showToast("Usage: /schedule <when> | <text>", { tone: "error" });
        return;
      }
      const queued = queueScheduledMessage(
        conversation,
        account,
        dmArg.slice(0, splitAt).trim(),
        dmArg.slice(splitAt + 1).trim()
      );
      if (!queued.ok) {
        showToast(queued.error || "Could not schedule message.", { tone: "error" });
        return;
      }
      ui.messageInput.value = "";
      resizeComposerInput();
      saveState();
      renderMessages();
      showToast(`Scheduled ${queued.entry.id.slice(0, 8)} for ${new Date(queued.entry.sendAt).toLocaleString()}.`);
      return;
    }
    if (dmCommand === "scheduled") {
      const rows = listScheduledMessagesForConversation(conversation.id);
      showToast(rows.length > 0 ? `${rows.length} scheduled message${rows.length === 1 ? "" : "s"} in this DM.` : "No scheduled messages in this DM.");
      return;
    }
    if (dmCommand === "unschedule") {
      const removed = removeScheduledMessageByToken(conversation.id, dmArg.trim() || "last");
      if (removed > 0) {
        saveState();
        showToast(`Removed ${removed} scheduled message${removed === 1 ? "" : "s"}.`);
      } else {
        showToast("No scheduled message matched.", { tone: "error" });
      }
      return;
    }
  }
  if (conversation.type === "channel" && !canCurrentUserPostInChannel(conversation.channel, account)) {
    if (conversation.channel.type === "voice" || conversation.channel.type === "stage") {
      showToast("This channel uses voice controls instead of text messages.", { tone: "error" });
    } else {
      showToast("You do not have permission to send messages in this channel.", { tone: "error" });
    }
    renderComposerMeta();
    return;
  }
  if (conversation.type === "channel") {
    const remainingMs = getChannelSlowmodeRemainingMs(conversation.channel, account.id);
    if (remainingMs > 0) {
      const waitSeconds = Math.max(1, Math.ceil(remainingMs / 1000));
      showToast(`Slowmode active: wait ${waitSeconds}s`, { tone: "error" });
      renderComposerMeta();
      return;
    }
  }

  if (conversation.type === "channel" && text) ensureCurrentUserInActiveServer();
  if (!(conversation.type === "channel" && text && handleSlashCommand(text, conversation.channel, account))) {
    const nextReply = replyTarget && replyTarget.channelId === conversation.id
      ? {
        messageId: replyTarget.messageId,
        authorName: replyTarget.authorName,
        text: replyTarget.text,
        threadId: replyTarget.threadId || null
      }
      : null;
    const nextMessage = {
      id: createId(),
      userId: account.id,
      authorName: "",
      text,
      ts: new Date().toISOString(),
      reactions: [],
      attachments: composerPendingAttachments.map((entry) => ({
        type: entry.type || "pdf",
        url: entry.url,
        name: entry.name || "file",
        format: entry.format || "image"
      })),
      replyTo: nextReply
    };
    if (conversation.type === "channel" && conversation.channel.type === "forum") {
      if (nextReply?.threadId) {
        nextMessage.forumThreadId = nextReply.threadId;
        nextMessage.forumParentId = nextReply.messageId || nextReply.threadId;
      } else {
        if (!canCurrentUserCreateThreadsInChannel(conversation.channel, getActiveGuild())) {
          showToast("You do not have permission to create forum posts in this channel.", { tone: "error" });
          renderComposerMeta();
          return;
        }
        const [firstLine, ...rest] = text.split("\n");
        nextMessage.forumTitle = (firstLine || "Untitled Post").trim().slice(0, 100) || "Untitled Post";
        nextMessage.text = rest.join("\n").trim();
        const defaultTags = normalizeThreadTagIds(
          getForumThreadTagFilter(conversation.channel.id),
          forumTagsForChannel(conversation.channel)
        );
        if (defaultTags.length > 0) nextMessage.forumTagIds = defaultTags;
      }
    }
    if (conversation.type === "dm") {
      conversation.thread.messages.push(nextMessage);
      publishRelayDirectMessage(conversation.thread, nextMessage, account);
    } else {
      conversation.channel.messages.push(nextMessage);
      recordChannelSlowmodeSend(conversation.channel, account.id);
      publishRelayChannelMessage(conversation.channel, nextMessage, account);
    }
    replyTarget = null;
    clearComposerPendingAttachment();
    if (swfPipTabs.length > 0 && !(conversation.type === "channel" && conversation.channel.type === "forum")) {
      ui.messageInput.value = "";
      setComposerDraft(conversation.id, "");
      composerTempLimitConversationId = null;
      composerTempLimitExtra = 0;
      applyComposerInputLimit();
      resizeComposerInput();
      slashSelectionIndex = 0;
      closeMediaPicker();
      saveState();
      appendMessageRowLite(conversation.type === "dm" ? conversation.thread : conversation.channel, nextMessage);
      renderChannels();
      renderMemberList();
      return;
    }
  }

  ui.messageInput.value = "";
  setComposerDraft(conversation.id, "");
  composerTempLimitConversationId = null;
  composerTempLimitExtra = 0;
  applyComposerInputLimit();
  clearComposerPendingAttachment();
  slashSelectionIndex = 0;
  closeMediaPicker();
  resizeComposerInput();
  saveState();
  renderMessages();
  renderMemberList();
  renderComposerMeta();
});

ui.messageInput.addEventListener("input", () => {
  const conversation = getActiveConversation();
  const limited = trimTextForConversation(ui.messageInput.value || "", conversation);
  if (limited !== ui.messageInput.value) {
    ui.messageInput.value = limited;
  }
  setComposerDraft(composerDraftConversationId, ui.messageInput.value);
  queueComposerDraftSave();
  resizeComposerInput();
  renderChannels();
  slashSelectionIndex = 0;
  mentionSelectionIndex = 0;
  renderSlashSuggestions();
  updateComposerTypingPublish();
  renderComposerMeta();
});

ui.messageInput.addEventListener("blur", () => {
  publishRelayTypingState(false, { force: true });
});

window.addEventListener("keydown", (event) => {
  if (event.defaultPrevented) return;
  if (event.ctrlKey || event.metaKey || event.altKey) return;
  if (event.key !== "/") return;
  const conversation = getActiveConversation();
  if (conversation?.id) return;
  const target = event.target;
  if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) return;
  event.preventDefault();
  setComposerCollapsedState(false);
  ui.messageInput.readOnly = false;
  ui.messageInput.value = "/";
  resizeComposerInput();
  slashSelectionIndex = 0;
  mentionSelectionIndex = 0;
  renderSlashSuggestions();
  renderComposerMeta();
  ui.messageInput.focus();
});

ui.composerCharCount?.addEventListener("click", () => {
  if (composerCharCountClickTimer) {
    clearTimeout(composerCharCountClickTimer);
    composerCharCountClickTimer = null;
  }
  composerCharCountClickTimer = setTimeout(() => {
    composerCharCountClickTimer = null;
    bumpComposerTemporaryLimit();
  }, 220);
});

ui.composerCharCount?.addEventListener("dblclick", async (event) => {
  event.preventDefault();
  if (composerCharCountClickTimer) {
    clearTimeout(composerCharCountClickTimer);
    composerCharCountClickTimer = null;
  }
  await configureDefaultComposerLimit();
});

ui.openMediaPickerBtn.addEventListener("click", () => {
  toggleMediaPicker();
});
ui.openMediaPickerBtn.addEventListener("contextmenu", (event) => {
  event.preventDefault();
  ui.quickAttachInput.click();
});
ui.openMediaPickerBtn.addEventListener("mouseenter", warmMediaPickerRuntimes);
ui.openMediaPickerBtn.addEventListener("focus", warmMediaPickerRuntimes);

ui.openGifPickerBtn?.addEventListener("click", () => {
  openMediaPickerWithTab("gif");
});
ui.openStickerPickerBtn?.addEventListener("click", () => {
  openMediaPickerWithTab("sticker");
});
ui.openEmojiPickerBtn?.addEventListener("click", () => {
  openMediaPickerWithTab("emoji");
});

ui.quickFileAttachBtn.addEventListener("click", () => {
  ui.quickAttachInput.click();
});

ui.quickFileAttachBtn.addEventListener("contextmenu", (event) => {
  event.preventDefault();
  openMediaPickerWithTab("pdf");
});

ui.quickAttachInput.addEventListener("change", async () => {
  const files = [...(ui.quickAttachInput.files || [])];
  if (files.length === 0) return;
  try {
    let attachedCount = 0;
    for (const file of files.slice(0, 6)) {
      const attached = await attachFileToComposer(file);
      if (!attached) continue;
      attachedCount += 1;
    }
    if (attachedCount === 0) {
      showToast("Unsupported attachment type for selected files.", { tone: "error" });
      return;
    }
    showToast(attachedCount > 1 ? `${attachedCount} files attached.` : "Attachment added.");
    ui.messageInput.focus();
  } catch {
    showToast("Failed to attach file.", { tone: "error" });
  } finally {
    ui.quickAttachInput.value = "";
  }
});

ui.clearComposerAttachmentBtn.addEventListener("click", () => {
  clearComposerPendingAttachment();
});

ui.saveComposerAttachmentBtn?.addEventListener("click", () => {
  if (composerPendingAttachments.length === 0) return;
  const ok = saveComposerAttachmentToPicker();
  if (!ok) {
    showToast("Could not save attachment to picker.", { tone: "error" });
    return;
  }
  const tab = pickerTabForAttachmentType(composerPendingAttachments[0]?.type || "pdf");
  showToast(composerPendingAttachments.length > 1 ? "Attachments saved to picker." : "Attachment saved to picker.");
  openMediaPickerWithTab(tab);
});

ui.toggleSwfAudioBtn.addEventListener("click", () => {
  const mode = getPreferences().swfQuickAudioMode;
  if (mode === "off") {
    setSwfQuickAudioMode("click");
    return;
  }
  if (mode === "click") {
    setSwfQuickAudioMode("on");
    return;
  }
  setSwfQuickAudioMode("click");
});

ui.toggleSwfAudioBtn.addEventListener("contextmenu", (event) => {
  event.preventDefault();
  const mode = getPreferences().swfQuickAudioMode;
  if (mode === "off") {
    setSwfQuickAudioMode("click");
    return;
  }
  setSwfQuickAudioMode("off");
});

ui.toggleMediaPrivacyBtn?.addEventListener("click", () => {
  state.preferences = getPreferences();
  const nextMode = state.preferences.mediaPrivacyMode === "off" ? "safe" : "off";
  state.preferences.mediaPrivacyMode = nextMode;
  saveState();
  applyPreferencesToUI();
  if (mediaPickerOpen) renderMediaPicker();
  renderMessages();
  showToast(nextMode === "off" ? "Media privacy gate disabled." : "Media privacy gate enabled.");
});

ui.mediaTabs.forEach((tabBtn) => {
  tabBtn.addEventListener("click", () => {
    const nextTab = tabBtn.dataset.mediaTab;
    if (!MEDIA_TABS.includes(nextTab)) return;
    if (gifPickerQueryDebounceTimer) {
      clearTimeout(gifPickerQueryDebounceTimer);
      gifPickerQueryDebounceTimer = null;
    }
    if (nextTab !== mediaPickerTab) {
      gifPickerVisibleCount = GIF_PICKER_INITIAL_PAGE_SIZE;
      stickerPickerVisibleCount = STICKER_PICKER_INITIAL_PAGE_SIZE;
      emojiPickerVisibleCount = EMOJI_PICKER_INITIAL_PAGE_SIZE;
    }
    mediaPickerTab = nextTab;
    mediaPickerQuery = "";
    renderMediaPicker();
    if (mediaPickerTab === "gif") {
      if (activeGifScope() === "all") maybeLoadMoreGifPickerEntries({ reset: true });
    } else if (mediaPickerTab === "sticker") {
      maybeLoadMoreStickerPickerEntries({ reset: true });
    } else if (mediaPickerTab === "emoji") {
      void ensureEmojiLibraryLoaded();
    }
    ui.mediaSearchInput.focus();
  });
});

ui.mediaSearchInput.addEventListener("input", () => {
  mediaPickerQuery = ui.mediaSearchInput.value.slice(0, 80);
  if (mediaPickerTab === "gif") {
    gifPickerVisibleCount = GIF_PICKER_INITIAL_PAGE_SIZE;
  } else if (mediaPickerTab === "sticker") {
    stickerPickerVisibleCount = STICKER_PICKER_INITIAL_PAGE_SIZE;
  } else if (mediaPickerTab === "emoji") {
    emojiPickerVisibleCount = EMOJI_PICKER_INITIAL_PAGE_SIZE;
  }
  renderMediaPicker();
  if (mediaPickerTab === "gif" || mediaPickerTab === "sticker") {
    if (gifPickerQueryDebounceTimer) clearTimeout(gifPickerQueryDebounceTimer);
    gifPickerQueryDebounceTimer = setTimeout(() => {
      gifPickerQueryDebounceTimer = null;
      if (mediaPickerTab === "gif") {
        if (activeGifScope() === "all") maybeLoadMoreGifPickerEntries({ reset: true });
      } else if (mediaPickerTab === "sticker") {
        maybeLoadMoreStickerPickerEntries({ reset: true });
      }
    }, 220);
  }
});

ui.mediaSearchInput.addEventListener("keydown", (event) => {
  if (event.key === "Escape") {
    if (mediaPickerQuery) {
      event.preventDefault();
      mediaPickerQuery = "";
      if (mediaPickerTab === "gif") gifPickerVisibleCount = GIF_PICKER_INITIAL_PAGE_SIZE;
      if (mediaPickerTab === "sticker") stickerPickerVisibleCount = STICKER_PICKER_INITIAL_PAGE_SIZE;
      if (mediaPickerTab === "emoji") emojiPickerVisibleCount = EMOJI_PICKER_INITIAL_PAGE_SIZE;
      renderMediaPicker();
      if (mediaPickerTab === "gif" && activeGifScope() === "all") maybeLoadMoreGifPickerEntries({ reset: true });
      if (mediaPickerTab === "sticker") maybeLoadMoreStickerPickerEntries({ reset: true });
      if (mediaPickerTab === "emoji") void ensureEmojiLibraryLoaded();
      return;
    }
    closeMediaPicker();
    return;
  }
  if (event.key !== "Enter") return;
  event.preventDefault();
  const [first] = filteredMediaEntries();
  if (!first) return;
  if (mediaPickerTab === "emoji") {
    const value = first.value || "";
    if (value && mediaPickerEmojiOnlyMode && mediaPickerEmojiSelectHandler) {
      mediaPickerEmojiSelectHandler(value, first);
      rememberRecentEmoji(value);
      saveState();
      closeMediaPicker();
      return;
    }
    insertTextAtCursor(value);
    if (value) {
      rememberRecentEmoji(value);
      saveState();
    }
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "docs") {
    sendMediaAttachment(first, first.type === "rtf" ? "rtf" : "odf");
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "html") {
    sendMediaAttachment(first, "html");
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "pdf") {
    sendMediaAttachment(first, "pdf");
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "text") {
    sendMediaAttachment(first, "text");
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "swf") {
    sendMediaAttachment(first, "swf");
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "sticker") {
    sendMediaAttachment(first, "sticker");
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "gif") {
    sendMediaAttachment(first, "gif");
    closeMediaPicker();
    return;
  }
  if (mediaPickerTab === "svg") {
    sendMediaAttachment(first, "svg");
    closeMediaPicker();
  }
});

